  @override
  String get methMilestone730Title => 'Два года - устойчивое восстановление';

  @override
  String get methMilestone730Description =>
      'Два года без метамфетамина дают мозгу достаточно времени для восстановления. Внимание, настроение, память и качество повседневной жизни продолжают улучшаться.';

  @override
