  @override
  String get nitrousOxideMilestone1Title => 'Первые 24 часа – очистка системы';

  @override
  String get nitrousOxideMilestone1Description =>
      'Газ покидает организм в течение нескольких минут, но восстановление занимает больше времени. Головокружение проходит, головная боль уменьшается, а мозг начинает адаптироваться без искусственного допаминового подкрепления. Восстановление уровня B12 начинается уже сейчас.';

  @override
  String get nitrousOxideMilestone3Title =>
      'День 3 — физической абстиненции нет';

  @override
  String get nitrousOxideMilestone3Description =>
      'Хорошие новости: закись азота не вызывает физической абстиненции. Побуждения, которые вы испытываете, носят психологический характер — привычка и ассоциация, а не ваше тело, требующее вещества. Это делает их управляемыми.';

  @override
  String get nitrousOxideMilestone7Title => 'Одна неделя – рост B12';

  @override
  String get nitrousOxideMilestone7Description =>
      'Одна неделя без уничтожения новых B12. Если вы начали принимать добавки, ваш уровень уже повышается. Энергия, настроение и сосредоточенность связаны с витамином B12 — вы должны почувствовать их улучшение.';

  @override
  String get nitrousOxideMilestone14Title => 'Две недели – исцеление нервов';

  @override
  String get nitrousOxideMilestone14Description =>
      'B12 необходим для защитного покрытия нервных волокон. Прошло две недели, и процесс ремонта активно идет. Любое покалывание или онемение, которые у вас были, должно пройти — ваша нервная система восстанавливается.';

  @override
  String get nitrousOxideMilestone30Title => 'Один месяц — возврат энергии';

  @override
  String get nitrousOxideMilestone30Description =>
      'B12 играет ключевую роль в производстве красных кровяных телец, что означает доставку кислорода к каждой клетке вашего тела. Один месяц восстановления и приема добавок означает значительно большую энергию, более ясное мышление и более стабильное настроение.';

  @override
  String get nitrousOxideMilestone90Title =>
      'Три месяца - неврологическое восстановление';

  @override
  String get nitrousOxideMilestone90Description =>
      'Три месяца без разрушения B12 означают три месяца восстановления нервов. Нервная система устойчива — большинство людей, начавших лечение, к этому моменту сразу же замечают значительное выздоровление от покалывания, слабости и затуманивания сознания.';

  @override
  String get nitrousOxideMilestone365Title =>
      'Один год – долгосрочное здоровье гарантировано';

  @override
  String get nitrousOxideMilestone365Description =>
      'Целый год без закиси азота. Ваши запасы витамина B12 восстановлены, вашей нервной системе дан год на восстановление, а сердечно-сосудистый риск, связанный с повышенным уровнем гомоцистеина, исчез. Ваше тело снова работает на основе своей собственной химии.';

