      'Наиболее интенсивные физические симптомы начинают стихать. Ваш пульс и артериальное давление стабилизируются. Хотя психологическая тяга может сохраняться, ваше тело исцеляется.';

  @override
  String get cocaineMilestone14Title => 'Две недели – обретение стабильности';

  @override
  String get cocaineMilestone14Description =>
      'Многие люди начинают чувствовать себя более стабильными эмоционально. Ваш уровень энергии повышается, а острые симптомы абстиненции ослабевают. Ваше сердечно-сосудистое здоровье продолжает значительно улучшаться.';

  @override
