  @override
  String get cocaineMilestone180Title => 'Шесть месяцев – более ясное мышление';

  @override
  String get cocaineMilestone180Description =>
      'Сканирование мозга показывает восстановление передней части мозга — области, отвечающей за планирование и самоконтроль. Память, контроль импульсов и ясное мышление продолжают укрепляться.';

  @override
