  @override
  String get alcoholMilestone3Title => 'Восстановление уровня гидратации';

  @override
  String get alcoholMilestone3Description =>
      'Ваши почки восстанавливаются после мочегонного действия алкоголя. Алкоголь подавляет антидиуретический гормон, что приводит к увеличению мочеиспускания и обезвоживанию. К третьему дню баланс жидкости в вашем организме значительно улучшается.';

