      'День 3: Фаза наивысшего риска — необходим медицинский контроль';

  @override
  String get maoiMilestone3Description =>
      'ИМАО несут самый серьезный риск прекращения приема из любого класса антидепрессантов. Резкое прекращение приема фенелзина и транилципромина может вызвать сильное возбуждение, спутанность сознания, галлюцинации, миоклонус и гипертермию. Если вы испытываете эти симптомы, немедленно обратитесь за медицинской помощью. ИМАО действуют путем постоянного отключения ферментов МАО; Для восстановления требуется, чтобы организм синтезировал новый фермент, и этот процесс занимает примерно 14 дней.';

  @override
  String get maoiMilestone7Title => 'Одна неделя: идет синтез фермента МАО';

  @override
  String get maoiMilestone7Description =>
      'ИМАО навсегда разрушают молекулы ферментов МАО; восстановление требует синтеза совершенно нового фермента. За одну неделю примерно 50% нормальной активности МАО может восстановиться. Тяжелые острые симптомы отмены (делирий, миоклонус, гипертермия) существенно уменьшаются. Тщательное медицинское наблюдение остается важным.';

  @override
  String get maoiMilestone14Title =>
      'Две недели: активность фермента МАО существенно восстановилась';

  @override
  String get maoiMilestone14Description =>
      'Две недели — стандартный клинический срок восстановления фермента МАО после прекращения приема. Примерно к 14 дню активность МАО-А и МАО-В в значительной степени восстанавливается и восстанавливается нормальный метаболизм тирамина. Диетические ограничения, необходимые во время лечения ИМАО, обычно можно смягчить после консультации с лечащим врачом.';

  @override
  String get maoiMilestone30Title =>
      'Один месяц: восстановление баланса химических систем мозга';

  @override
  String get maoiMilestone30Description =>
      'Через месяц после прекращения приема ИМАО фермент МАО снова становится активным, и мозг естественным образом обрабатывает серотонин, норадреналин, дофамин и тирамин. Период специального взаимодействия продуктов питания и лекарств закончился, однако вам все равно следует сообщить врачам, назначающим лекарства, о предыдущем использовании ИМАО.';

  @override
  String get maoiMilestone90Title => 'Три месяца: нормализация биохимии мозга';

  @override
  String get maoiMilestone90Description =>
      'Три месяца дают настроению мозга и энергетическим системам достаточное время для адаптации после ИМАО. Настроение, энергия и ясное мышление стабилизируются, поскольку мозг снова естественным образом обрабатывает эти химические вещества.';

  @override
  String get maoiMilestone180Title =>
      'Шесть месяцев: долгосрочное восстановление';

  @override
  String get maoiMilestone180Description =>
      'Шесть месяцев представляют собой значительный период естественной функции моноаминов. Популяции рецепторов серотонина, норадреналина и дофамина нормализовались. Пути фенэтиламина (ФЭА), на которые также влияют ИМАО, восстановились до естественного уровня — часто упускаемый из виду аспект выздоровления, который способствует эмоциональной нормализации.';

