  @override
  String get adderallReferenceDay1 =>
      'Отмена амфетамина: что происходит на ранних стадиях\n\nИсточник: MedlinePlus (Национальная медицинская библиотека США).\n\nЧто такое амфетамины?\nАмфетамины — это стимулирующие препараты, в состав которых входят как запрещенные вещества (например, уличная скорость), так и отпускаемые по рецепту лекарства, используемые для лечения СДВГ и нарколепсии (например, Аддералл и Виванс). Они резко увеличивают дофамин и норадреналин, что может вызвать интенсивную концентрацию, энергию и эйфорию. При регулярном интенсивном использовании мозг адаптируется к этим повторяющимся всплескам, поэтому остановка может временно привести к снижению настроения, энергии и мотивации.\n\nОбщие симптомы абстиненции\nMedlinePlus называет их типичными при прекращении приема амфетаминов:\n• Сильная тяга к наркотику.\n• Перепады настроения от депрессивного до возбужденного и тревожного.\n• Чувство усталости в течение всего дня\n• Не способен сконцентрироваться\n• Галлюцинации (видение или слух вещей, которых нет на самом деле)\n• Физические реакции, такие как головные боли, боли, повышенный аппетит и плохой сон.\n\nОпасен ли отказ?\nMedlinePlus не описывает отмену амфетамина как опасную с медицинской точки зрения саму по себе, но отмечает, что тяжелые симптомы могут потребовать программы лечения с проживанием, и что проблемы настроения и эмоциональные проблемы, связанные с употреблением амфетамина, включая депрессию, могут быть серьезными и требовать поддержки.\n\nПолучение помощи\nMedlinePlus советует обратиться к своему лечащему врачу, если вы или кто-то из ваших знакомых страдаете зависимостью от амфетаминов и вам нужна помощь, чтобы прекратить их употребление. Если у вас есть мысли о членовредительстве, он направляет читателей на кризисные ресурсы, такие как 988 или 911.';

  @override
  String get adderallReferenceDay3 =>
      'Управление отменой амфетамина: день 3\n\nИсточник: «Клинические рекомендации по лечению абстиненции и лечению наркотической зависимости в закрытых учреждениях», Всемирная организация здравоохранения (2009), на книжной полке NCBI.\n\nГде проходит День 3\nВ рекомендациях ВОЗ говорится, что симптомы отмены стимуляторов «начинаются в течение 24 часов после последнего использования стимуляторов и длятся 3–5 дней». Третий день приходится непосредственно на острую фазу — обычно это один из самых тяжелых дней, прежде чем симптомы начнут стихать.\n\nСимптомы\nДля стимуляторов амфетаминового ряда в руководящих принципах перечислены:\n• Возбуждение и раздражительность\n• Депрессия\n• Улучшение сна и аппетита.\n• Мышечные боли\nУ заядлых потребителей также могут развиться психотические симптомы, такие как паранойя, беспорядочные мысли или галлюцинации.\n\nВ основном психологическая проблема\nВ отличие от отмены алкоголя или опиоидов, отмена стимуляторов не вызывает рвоты, тремора или судорог. Основная трудность носит психологический характер: плохое настроение, потеря удовольствия и тяга, вызванная истощенным дофамином мозгом.\n\nПодход к управлению\nРекомендации ВОЗ рекомендуют поддерживающую терапию:\n• Питьё не менее 2–3 литров воды в день.\n• Мультивитаминные добавки с витаминами группы B и витамином C.\n• Симптоматические лекарства от болей и беспокойства.\n• При сильном возбуждении сначала следует применять поведенческие стратегии, а при необходимости использовать седацию диазепамом.\n\nЗа пределами острой фазы\nВ рекомендациях говорится, что самый тяжелый период абстиненции длится всего несколько дней, за которым следует более мягкий период восстановления, который может длиться от одного до двух месяцев.';

  @override
  String get adderallReferenceDay7 =>
      'Одна неделя без аддерола: худшее проходит\n\nИсточник: Ли и Шоптоу, «Клиническое лечение отмены психостимуляторов: обзор доказательств», Наркомания (2023), на PubMed Central.\n\nОстрая фаза проходит\nВ этом обзоре данных описывается поэтапная отмена психостимуляторов. В острой фазе симптомы «набирают пик после первых 2–3 дней», а «сильный дискомфорт, вызванный этими симптомами, обычно проходит в течение 4–7 дней». К концу первой недели самая тяжелая часть кризиса уже позади для большинства людей — энергия и аппетит начинают стабилизироваться, а сон начинает регулироваться.\n\nЧто будет дальше\nВ обзоре говорится, что большинство оставшихся симптомов продолжают ослабевать в течение следующих двух-трех недель. На седьмой день восстановление уже идет полным ходом.\n\nЧто еще присутствует на седьмом дне\nПсихологические симптомы обычно сохраняются дольше, чем физическая авария:\n• Низкая мотивация и потеря удовольствия.\n• Трудности с концентрацией внимания\n• Настроение все еще ниже нормы.\nОни отражают перестройку дофаминовой системы — нормальную, временную часть восстановления.\n\nСигнал восстановления\nНи одно лекарство, одобренное FDA, специально не лечит синдром отмены стимуляторов, поэтому поддерживающий уход, структура, сон, питание и психологическая поддержка являются основой на этом этапе.';

  @override
  String get adderallReferenceDay14 =>
      'Две недели без Аддерола: переход к более длительной фазе восстановления\n\nИсточник: «Клинические рекомендации по лечению абстиненции и лечению наркотической зависимости в закрытых учреждениях», Всемирная организация здравоохранения (2009), на книжной полке NCBI.\n\nПрохождение острой фазы\nПо оценкам ВОЗ, самый тяжелый период отмены стимуляторов составляет от трех до пяти дней, за которым следует более мягкий период восстановления, продолжающийся примерно один-два месяца. Через две недели крах уже далеко позади.\n\nКак ощущается более длительная фаза восстановления\nТяжелый сон, возбуждение и мышечные боли в основном утихли. То, что остается, обычно мягче: плохое или меняющееся настроение, снижение мотивации и периодическая тяга к стимулятору по мере перестройки системы вознаграждения мозга.\n\nСон и аппетит\nУсиление сна и аппетит в острой фазе нормализуются. По мере того, как сон стабилизируется, обычно появляются настроение, концентрация и энергия.\n\nРиск рецидива и СДВГ\nЭто по-прежнему период повышенного риска, особенно если основные симптомы СДВГ возвращаются без лечения. В рекомендациях ВОЗ особое внимание уделяется психологической поддержке и навыкам предотвращения рецидивов; для людей, которые принимали Аддералл от СДВГ, это хорошее время, чтобы обсудить с врачом стратегии или альтернативы, не связанные с использованием стимуляторов.';

  @override
  String get adderallReferenceDay30 =>
      'Месячный перерыв на Аддерол: большинство симптомов позади\n\nИсточник: Ли и Шоптоу, «Клиническое лечение отмены психостимуляторов: обзор доказательств», Наркомания (2023), на PubMed Central.\n\nЧто означает один месяц\nОбзор показывает, что большинство симптомов абстиненции исчезают в течение первых двух-трех недель. К 30 дням большинство из них проходит, а настроение и мотивация обычно намного лучше, чем в первую неделю.\n\nПоздняя фаза восстановления\nОт одного до шести месяцев память, планирование, внимание и принятие решений продолжают улучшаться. Через месяц крах закончился, и этот рост уже начался.\n\nНастроение и мотивация\nГлубокая потеря удовольствия от аварии к настоящему времени в значительной степени исчезла. Действия, которые в первую неделю казались безрадостными, снова начинают приносить пользу, поскольку естественная передача сигналов дофамина восстанавливается.\n\nДля людей с СДВГ\nЕсли Аддералл был назначен при СДВГ, основные симптомы теперь могут быть более заметными. На этом этапе важно работать с поставщиком медицинских услуг над нестимулирующими стратегиями или альтернативами.';

  @override
  String get adderallReferenceDay60 =>
      'Два месяца без Аддералла: длительная фаза восстановления подходит к концу\n\nИсточник: «Клинические рекомендации по лечению абстиненции и лечению наркотической зависимости в закрытых учреждениях», Всемирная организация здравоохранения (2009), на книжной полке NCBI.\n\nЧто означают два месяца\nВОЗ описывает более мягкий период восстановления, продолжающийся от одного до двух месяцев после первоначального спада. Через 60 дней вы находитесь в дальнем конце этого окна, и сохраняющиеся симптомы в основном проходят.\n\nЧто улучшается\nВозбуждение, депрессивное настроение, нарушения сна и аппетита, указанные в списке рекомендаций по отмене стимуляторов, для большинства людей в основном решены:\n• Обычное настроение более стабильное, с меньшими колебаниями раннего выздоровления.\n• Нормализовались сон и аппетит.\n• Система вознаграждений охотнее реагирует на повседневные удовольствия — еду, физические упражнения, общение.\n\nСигнал восстановления\nБолее высокие дозы и более длительное употребление могут замедлить выздоровление, в то время как воздержание сохраняет настроение, мотивацию и ясное мышление в норме в течение следующих месяцев.\n\nФизическое здоровье\nСтимуляторное воздействие на частоту сердечных сокращений, аппетит и вес снижается по мере того, как препарат выводится из повседневной жизни, а сердечно-сосудистая нагрузка снижается из-за использования стимуляторов.';

  @override
  String get adderallReferenceDay90 =>
      'Три месяца без Аддералла: худшее позади, восстановление продолжается\n\nИсточник: Ли и Шоптоу, «Клиническое лечение отмены психостимуляторов: обзор доказательств», Наркомания (2023), на PubMed Central.\n\nЧто означают 90 дней\nЧерез три месяца ранние симптомы уже давно исчезли, а память, планирование, сосредоточенность, принятие решений и система вознаграждения продолжают улучшаться.\n\nМышление и память продолжают восстанавливаться\nОбзор показывает, что память, планирование, сосредоточенность и принятие решений о риске могут улучшаться в течение нескольких месяцев. На 90-й день концентрация и память все еще движутся в правильном направлении при продолжающемся воздержании.\n\nПочему это окно все еще имеет значение\nНи одно лекарство, одобренное FDA, специально не нацелено на отмену стимуляторов, поэтому структура, терапия, упражнения, сон и поддержка являются инструментами, которые обеспечивают выздоровление на этом этапе. Формирование этих привычек сейчас – это то, что продвигает выздоровление вперед.\n\nБольшая картина\nТри месяца — это настоящее достижение: самые тяжелые физические и эмоциональные нагрузки позади, и дальнейший путь, при постоянном воздержании, — это траектория устойчивого улучшения.';

  @override
  String get adderallReferenceDay180 =>
      'Шесть месяцев без Аддералла: самое сложное уже позади\n\nИсточник: «Синдромы абстиненции», StatPearls (Книжная полка NCBI), Национальная медицинская библиотека США.\n\nЧто говорит StatPearls о стимуляторах\nВ этом клиническом справочнике восстановление после приема стимуляторов описывается как кризис, за которым следует постепенное улучшение. Общие проблемы включают депрессию, длительный сон, повышенный голод, плохое настроение, замедление движений и мышления. Депрессия может длиться несколько недель, после чего продолжается более легкое восстановление.\n\nЧто означают шесть месяцев\nЧерез шесть месяцев вы уже далеко прошли как острый период, так и многонедельную депрессивную фазу, которую описывает StatPearls. Медленное восстановление, о котором идет речь, длилось достаточно долго, и для большинства людей обычное настроение, сон, аппетит и мотивация к настоящему времени стабильны и надежны.\n\nСигнал восстановления\nStatPearls описывает постепенное восстановление после первых недель. К шести месяцам острый кризис и многонедельная депрессивная фаза останутся далеко позади, и стабильное настроение, сон, аппетит и мотивация теперь станут доминирующим паттерном.\n\nСвязь с СДВГ\nДля людей, которые принимали Аддералл от СДВГ, шесть месяцев воздержания являются хорошей отправной точкой для трезвого анализа с врачом текущих симптомов и того, соответствуют ли нестимулирующие подходы — упражнения, сон, структура, терапия или альтернативные лекарства — вашим потребностям.';

  @override
  String get adderallReferenceDay365 =>
      'Годовой перерыв в Adderall: существенное восстановление, честно оформленное\n\nИсточник: Берман и др., «Потенциальные неблагоприятные эффекты лечения амфетамином на мозг и поведение: обзор», Молекулярная психиатрия (2008), на PubMed Central.\n\nОб этом обзоре\nВ этом обзоре отслеживается влияние высоких доз или длительного воздействия амфетамина на мозг, а также документируется измеримое восстановление во время воздержания.\n\nЧто здесь говорится о восстановлении\nВ обзоре документально подтверждено восстановление мозгового кровообращения и белков, перерабатывающих дофамин, после длительного воздержания. Некоторые области мозга восстанавливаются быстрее, чем другие, но общее направление ясно: мозг восстанавливается после прекращения использования.\n\nДолгосрочное восстановление\nВ обзоре документально подтверждено измеримое восстановление мозгового кровообращения и рециркуляции дофамина после длительного воздержания. За год у этих мозговых систем был целый год на восстановление.\n\nЧто это значит через год\nДля большинства людей, особенно для тех, кто принимал Аддералл в предписанных дозах, годовой перерыв означает, что системы вознаграждения, внимания и мотивации работают хорошо изо дня в день. Более интенсивное или длительное использование может занять больше времени, но восстановление продолжается. Риск рецидива намного ниже, чем при раннем выздоровлении.';

  @override
  String get alcoholReferenceDay1 =>
      'Что происходит с вашим сном, когда вы бросаете пить?\n\nИсточник: «Алкоголь и спящий мозг» (Колрейн, Николас и Бейкер), Справочник по клинической неврологии — рецензируемый, размещенный в НИЗ.\n\nАлкоголь и архитектура сна\nАлкоголь оказывает успокаивающее действие, поэтому сокращает время, необходимое для засыпания, и усиливает глубокий медленный сон в первой половине ночи. Но за это приходится платить: алкоголь подавляет быстрый сон (быстрое движение глаз) — восстановительную стадию, связанную с консолидацией памяти и эмоциональной регуляцией — и фрагментирует сон во второй половине ночи по мере его метаболизма.\n\nПервая ночь без алкоголя\nПоскольку алкоголь подавляет быстрый сон, первые ночи без него часто приводят к восстановлению быстрого сна: яркие сны и более легкий, прерывистый сон, в то время как нормальный режим сна возвращается. Это нормальная временная часть восстановления.\n\nВосстановление начинается\nПо мере того, как мозг перестраивается в течение следующих дней и недель, скорость быстрого сна и общее качество сна улучшаются. Нарушение сна является одним из наиболее стойких симптомов, связанных с абстиненцией, но при длительном воздержании оно имеет тенденцию к норме.\n\nПримечание о пьянстве\nУ тех, кто много или длительное время пьет ежедневно, в первые 24 часа также могут возникнуть симптомы абстиненции (беспокойство, потливость, тремор, тошнота). Тяжелая абстиненция может быть опасной — если вы много пили каждый день, поговорите с врачом, прежде чем резко прекратить употребление алкоголя.';

  @override
  String get alcoholReferenceDay3 =>
      'Острая фаза и раннее выздоровление\n\nИсточник: «Отказ от алкоголя», StatPearls — рецензируемая, Национальная медицинская библиотека НИЗ.\n\nПервые 24–72 часа\nStatPearls документально подтверждает, что симптомы абстиненции появляются в течение нескольких часов после последнего употребления алкоголя — тремор, бессонница, возбуждение, потливость, повышенная частота сердечных сокращений и кровяное давление — и что симптомы обычно достигают максимума примерно через 72 часа. У большинства людей худшая часть острой фазы проходит к концу третьего дня. Тяжелая абстиненция (приступы или белая горячка, которая, как отмечает StatPearls, может возникнуть в любой момент в течение 3-5 дней после прекращения или сокращения потребления) требует неотложной медицинской помощи: любителям ежедневного употребления алкоголя не следует резко прекращать употребление алкоголя без консультации с врачом.\n\nТяга приходит волнами\nТяга часто усиливается в течение первых нескольких дней, но индивидуальная тяга кратковременна — обычно проходит в течение нескольких минут. Осознание того, что каждая волна утихает сама по себе, облегчает преодоление этой волны.\n\nГидратация восстанавливается\nАлкоголь подавляет антидиуретический гормон (АДГ), заставляя почки выделять больше воды и приводя к хроническому обезвоживанию тех, кто регулярно пьет. Как только употребление алкоголя прекращается, этот мочегонный эффект прекращается, и баланс жидкости начинает восстанавливаться в течение первых нескольких дней, что часто проявляется в более чистой коже и более стабильном уровне энергии.\n\nРазум и сон начинают успокаиваться\nПо мере прохождения острой фазы химические процессы в мозге, нарушенные алкоголем (ГАМК и глутамат), начинают восстанавливать баланс. Ясность ума улучшается, и качество сна, сильно фрагментированного во время раннего отказа, начинает улучшаться в течение первой недели.';

  @override
  String get alcoholReferenceDay7 =>
      'Как восстанавливается иммунная система\n\nИсточник: «Алкоголь и иммунная система» (Саркар, Юнг и Ван), «Исследование алкоголя: текущие обзоры» — рецензируемое, размещенное в НИЗ.\n\nКак алкоголь ослабляет иммунитет\nАлкоголь ослабляет иммунную систему несколькими способами. Даже один сеанс употребления алкоголя может снизить способность человека бороться с инфекцией на срок до 24 часов. Длительное употребление снижает количество лейкоцитов, нарушает иммунные сигналы и повреждает защиту кишечника и легких, увеличивая риск инфекций и замедляя заживление ран.\n\nУдаление оскорбления\nМногие из этих эффектов улучшаются после прекращения употребления алкоголя. Лейкоциты и иммунные сигналы начинают восстанавливаться, а защита кишечника и дыхательных путей начинает восстанавливаться. В течение первой недели ваша иммунная система больше не подвергается ежедневному ослаблению, и устойчивость к распространенным инфекциям начинает улучшаться.\n\nПостепенный процесс\nПолное восстановление иммунитета занимает больше недели, и степень восстановления зависит от того, интенсивности и продолжительности предыдущего употребления алкоголя, но восстановление начинается с первой недели отказа от алкоголя.';

  @override
  String get alcoholReferenceDay14 =>
      'Раннее восстановление мозга при воздержании\n\nИсточник: Bartsch AJ et al., «Проявления раннего восстановления мозга, связанные с воздержанием от алкоголизма», Brain (2007) — рецензировано.\n\nИзмерение восстановления\nВ этом исследовании использовалась МРТ для наблюдения за людьми с алкогольной зависимостью, недавно прошедшими детоксикацию, в течение первых недель воздержания, сравнивая их со здоровыми людьми из контрольной группы. Он показал, как мозг физически восстанавливается после прекращения употребления алкоголя.\n\nОбъем мозга восстанавливается\nХроническое употребление алкоголя приводит к уменьшению размера мозга — отчасти за счет обратимого уменьшения размера клеток, а не только за счет необратимой потери клеток. При воздержании исследователи измерили средний глобальный прирост объема мозга почти на 2%, сосредоточенный вокруг мозжечка, среднего мозга, желудочков и лобных областей. Большая часть этого возобновления роста происходит рано, в первые пару недель отказа от алкоголя.\n\nМозжечок и внимание\nВосстановление было особенно очевидным в областях мозга, отвечающих за движение и внимание. Показатели здоровья клеток мозга росли вместе с измеримым улучшением внимания, поэтому физическое исцеление сопровождалось реальным улучшением мышления.\n\nОснова, а не завершение\nВысшие функции, такие как сложное мышление, восстанавливаются более постепенно, но первые две недели показывают, что мозг начинает быстро восстанавливаться после прекращения употребления алкоголя.';

  @override
  String get alcoholReferenceDay30 =>
      'Кровяное давление падает, когда вы отказываетесь от алкоголя\n\nИсточник: Roerecke et al., «Влияние снижения потребления алкоголя на кровяное давление: систематический обзор и метаанализ», Lancet Public Health (2017) — рецензировано.\n\nДоказательства\nЭтот метаанализ объединил 36 рандомизированных исследований (около 2865 участников), проверяющих, что происходит с артериальным давлением, когда люди пьют меньше. Был обнаружен явный дозозависимый эффект: чем больше кто-то сокращал потребление, тем сильнее падало его кровяное давление.\n\nНасколько велик эффект?\nЛюди, которые выпивали два или меньше порций напитка в день, не заметили значительных изменений артериального давления от сокращения. Выше этого порога эффект зависел от дозы: он был самым сильным у людей, выпивавших шесть или более порций алкоголя в день, которые сократили потребление примерно вдвое, при этом систолическое артериальное давление упало в среднем примерно на 5,5 мм рт. ст., а диастолическое - примерно на 4,0 мм рт. ст. Уменьшение этого размера клинически значимо — сравнимо с некоторыми лекарствами от артериального давления и достаточно для снижения долгосрочного риска инсульта и сердечных заболеваний.\n\nПочему один месяц имеет значение\nАлкоголь повышает кровяное давление, активируя реакцию на стресс, повышая уровень кортизола и укрепляя кровеносные сосуды. Испытания в этом обзоре показывают, что польза проявляется в течение нескольких недель устойчивого снижения — таким образом, примерно к месяцу воздержания кровяное давление у более пьющего человека успевает приблизиться к более здоровому уровню.\n\nПороговый эффект\nОбзор выявил четкий порог: польза была сконцентрирована у людей, выпивавших более двух порций напитка в день, и становилась тем больше, чем больше было предыдущего употребления. Если вы пьете меньше, не ждите такого особого улучшения артериального давления, но пьющие, пьющие больше, получают реальную, измеримую пользу для сердечно-сосудистой системы от прекращения употребления алкоголя.';

  @override
  String get alcoholReferenceDay60 =>
      'Восстановление печени после отказа от алкоголя\n\nИсточник: Национальный институт по злоупотреблению алкоголем и алкоголизму (NIAAA), «Влияние алкоголя на организм».\n\nКак алкоголь вредит печени\nПечень перерабатывает большую часть выпитого алкоголя и принимает на себя основной урон. NIAAA описывает прогрессирование поражения печени, связанного с алкоголем: оно начинается с жировой дистрофии печени (стеатоза — накопления жира в клетках печени), может перерасти в алкогольный гепатит (воспаление), а при длительном интенсивном употреблении — в фиброз и цирроз печени (рубцевание).\n\nБолее ранние стадии обратимы\nВажным моментом является то, что печень обладает высокой регенеративной способностью, и ранние стадии этого повреждения могут улучшиться, когда прекратить пить. В частности, ожирение печени часто проходит при длительном воздержании. Примерно через два месяца безалкогольного периода печень успевает очистить жировые отложения, успокоить воспаление и восстановить более здоровую функцию, что обычно отражается в падении уровня печеночных ферментов (АЛТ и АСТ).\n\nЗа пределами печени\nNIAAA отмечает, что алкоголь также нагружает сердце, поджелудочную железу и иммунную систему. Длительный отказ от алкоголя позволяет этим системам восстановиться, что способствует более стабильному уровню энергии и улучшению общего состояния здоровья, которое многие люди замечают на этом этапе.';

  @override
  String get alcoholReferenceDay90 =>
      'Мышление и память после трех месяцев трезвости\n\nИсточник: Систематический обзор нейропсихологического восстановления после воздержания от алкоголя (PubMed Central, 2024) — рецензируемый.\n\nЧто показывают доказательства\nВ этом обзоре объединены исследования, в которых отслеживалось, как восстанавливаются мышление и память после того, как люди бросают пить. Большинство навыков возвращаются к норме примерно через шесть-двенадцать месяцев, а некоторые улучшаются раньше.\n\nЧто улучшается в первую очередь\nДве конкретные способности восстанавливаются раньше остальных: базовая скорость обработки (обзор показал, что она обычно восстанавливается примерно за месяц, хотя точность при выполнении более сложных задач отстает) и обновление рабочей памяти. Примерно через три месяца многие люди уже замечают этот подъем.\n\nЧто занимает больше времени\nВнимание, планирование, принятие решений, контроль импульсов, восприятие и память продолжают улучшаться в течение периода восстановления от шести до двенадцати месяцев.\n\nЧто влияет на восстановление\nВ обзоре отмечается, что выздоровление зависит от таких факторов, как возраст, статус курения и преморбидные способности, но, что обнадеживает, не всегда зависит от общего количества ранее выпитого. Восстановление – это ожидаемая траектория.\n\nПочему это важно\nБолее ясное мышление – это практическое выздоровление: лучшее внимание и способность принимать решения помогают людям продолжать лечение и избегать рецидивов.';

  @override
  String get alcoholReferenceDay180 =>
      'Восстановление мозга за шесть месяцев трезвости\n\nИсточник: Рецензируемый обзор структурного и функционального восстановления мозга во время воздержания от употребления психоактивных веществ (PubMed Central).\n\nВосстановление продолжается\nРаннее восстановление объема мозга в первые недели — это только начало. В этом обзоре документально подтверждено, что при длительном воздержании мозг продолжает восстанавливаться структурно и функционально: восстанавливается серое вещество, а поврежденные пути белого вещества, которые координируют связь между областями мозга, восстанавливаются в течение нескольких месяцев.\n\nПередняя часть мозга\nВосстановление особенно важно для передней части мозга, которая отвечает за суждение, планирование и самоконтроль. По мере выздоровления усиливается способность принимать решения и контролировать импульсы.\n\nПерестройка мозга и его функционирование\nНаряду с физическим восстановлением восстанавливаются функции мозга и связи. Мозг может перенастраиваться и переучиваться, что делает длительное воздержание отличным временем для терапии и новых привычек.\n\nСигнал восстановления\nК шести месяцам структура и функции мозга явно приближаются к более здоровому состоянию. Воздержание дает больше времени на выздоровление.';

  @override
  String get alcoholReferenceDay365 =>
      'Алкоголь, риск рака и остановка\n\nИсточник: Национальный институт рака (NCI), «Алкоголь и риск рака».\n\nАлкоголь вызывает рак\nNCI заявляет, что существует сильный научный консенсус в отношении того, что употребление алкоголя может вызвать рак. Алкоголь связан с раком рта (ротовой полости), глотки (горла), гортани (голосового аппарата), пищевода, печени, молочной железы, толстой и прямой кишки. Чем больше человек пьет и чем дольше он пьет, тем выше риск.\n\nКак алкоголь вызывает рак\nМеханизмы включают ацетальдегид, токсичный продукт распада алкоголя, повреждающий ДНК; окислительный стресс и воспаление; нарушение всасывания защитных питательных веществ; и, что касается рака молочной железы, повышенный уровень эстрогена.\n\nРиск снижается после того, как вы остановитесь\nВажно отметить, что NCI сообщает, что отказ от употребления алкоголя связан с более низким риском с течением времени — исследования показывают, что повышенный риск рака полости рта и пищевода снижается после прекращения употребления алкоголя, хотя могут потребоваться годы, чтобы приблизиться к риску человека, который никогда не пил. Один год без алкоголя — значимый шаг на этом пути.\n\nДополнительные преимущества\nДостижение года также фиксирует улучшение состояния сердечно-сосудистой системы и печени в результате воздержания — снижение артериального давления, снижение риска аритмии и продолжающееся заживление печени — наряду со снижением риска рака.';

  @override
  String get benzodiazepineReferenceDay7 =>
      'Отмена бензодиазепинов: первая неделя\n\nИсточник: «Клинические рекомендации по лечению абстиненции и лечению наркотической зависимости в закрытых учреждениях», Всемирная организация здравоохранения (2009), на книжной полке NCBI.\n\nПримечание о безопасности при отмене бензодиазепинов\nОтмена бензодиазепинов может быть опасной. В рекомендациях ВОЗ четко указано, что самым безопасным подходом является назначение бензодиазепинов в постепенно уменьшающихся количествах, что «помогает облегчить симптомы отмены бензодиазепинов и предотвратить развитие судорог». Не прекращайте резко после длительного применения — посоветуйтесь с врачом о постепенном снижении дозы.\n\nКогда начинается синдром отмены\nСроки ВОЗ зависят от продолжительности действия препарата:\n• Кратковременного действия (оксазепам, алпразолам, темазепам): синдром отмены начинается через 1–2 дня после приема последней дозы и продолжается в течение 2–4 недель или дольше.\n• Длительного действия (диазепам, нитразепам): синдром отмены начинается через 2–7 дней после приема последней дозы и продолжается в течение 2–8 недель или дольше.\nВеха в первую неделю – это момент, когда даже бензодиазепины длительного действия выводятся из организма в достаточной степени, чтобы эффект отмены был полным.\n\nРанние симптомы абстиненции\n• Тревога возврата — часто более интенсивная, чем первоначальная тревога, которую лечил препарат.\n• Бессонница и нарушение сна.\n• Тремор и мышечное напряжение\n• Потливость и сердцебиение\n• Повышенная чувствительность к свету и звуку.\n\nМониторинг\nВ рекомендациях ВОЗ отмечается, что тяжесть абстиненции «может заметно колебаться», поэтому использовать формальные шкалы не рекомендуется; вместо этого врач должен приходить каждые несколько часов, успокаивать и объяснять симптомы. Бензодиазепины усиливают действие ГАМК, основного успокаивающего сигнала мозга; длительное применение притупляет эту систему, поэтому отмена препарата приводит к перевозбуждению мозга — источнику тревоги, тремора и риска судорог, которые делают необходимым постепенное снижение дозы.';

  @override
  String get benzodiazepineReferenceDay14 =>
      'Отмена бензодиазепинов: две недели\n\nИсточник: Эштон, «Длительные синдромы отмены бензодиазепинов», Журнал лечения злоупотребления психоактивными веществами (1991), на PubMed.\n\nВсе еще в стадии острой абстиненции\nЧерез две недели многие люди, особенно те, кто прекратил прием бензодиазепинов длительного действия, все еще находятся в острой фазе, когда дисбаланс между успокаивающей (ГАМК) и возбуждающей системами мозга наиболее выражен. Часто наблюдаются тревога, бессонница и нарушения восприятия.\n\nПочему отказ от бензосодержащих препаратов может затянуться\nПрофессор Хизер Эштон описывает, как первые симптомы абстиненции могут перерасти в более длительные проблемы. Тревога, бессонница, проблемы с ясным мышлением и сенсорные изменения могут продолжаться месяцами, поскольку изменения толерантности мозга могут медленно возвращаться вспять.\n\nМедленно обратимые изменения\nЭштон характеризует их как «медленно обратимые функциональные изменения в центральной нервной системе». Центральным требованием является выздоровление: нервная система постепенно обращает вспять функциональные адаптации, вызванные длительным воздействием бензодиазепинов.\n\nПостепенное сокращение является ключевым моментом\nИмеющиеся данные убедительно подтверждают, что медленное и контролируемое снижение дозы является самым безопасным способом остановки, позволяющим мозгу постепенно адаптироваться, а не сталкиваться с внезапной потерей тормозных сигналов.';

  @override
  String get benzodiazepineReferenceDay60 =>
      'Бензодиазепины и восстановление сна к двум месяцам\n\nИсточник: Поярес и др., «Хроническое употребление бензодиазепинов и отказ от них у пациентов с бессонницей», Журнал психиатрических исследований (2004), на PubMed.\n\nКак бензодиазепины меняют сон\nБензодиазепины широко назначают при бессоннице, но они изменяют архитектуру сна. В этом полисомнографическом исследовании пациентов, которые принимали бензодиазепины каждую ночь в среднем в течение почти семи лет, хроническое употребление было связано с сокращением медленноволнового (глубокого) сна и более легким сном 2-й стадии — поэтому пользователи теряют восстанавливающий глубокий сон, даже когда чувствуют себя седативными.\n\nГлубокий сон возвращается\nОбнадеживающий вывод: исследование снова измерило сон через 15 дней после отмены и обнаружило восстановление медленноволнового сна и дельта-активности по сравнению с ночами при хроническом употреблении, а также улучшение субъективного качества сна. Глубокий сон, подавленный препаратом, начал возвращаться примерно через две недели после прекращения приема.\n\nЧто это значит через 60 дней\nЕсли глубокий сон восстанавливается в течение двух недель, то к двум месяцам у вашего мозга будет достаточно времени, чтобы продолжить восстановление естественного восстанавливающего сна. Тяжелая рецидивирующая бессонница, возникшая в результате раннего отказа, обычно проходит. Авторы были честны в том, что отмена поначалу ухудшала сон (именно поэтому постепенное снижение дозы имеет значение), но к концу их протокола качество сна улучшилось по сравнению с хроническим употреблением бензодиазепинов.\n\nДругие улучшения на два месяца\nМногие ранние физические симптомы абстиненции — мышечное напряжение, тремор, сердцебиение, потливость — обычно ослабевают или исчезают к двухмесячной отметке, когда организм восстанавливает регуляцию.';

  @override
  String get benzodiazepineReferenceDay90 =>
      'Три месяца после приема бензодиазепинов: физическое здоровье стабилизируется\n\nИсточник: Эштон, «Длительные синдромы отмены бензодиазепинов», Журнал лечения злоупотребления психоактивными веществами (1991), на PubMed.\n\nФизическая стабилизация\nК 90 дням острая фаза уже позади. У людей, завершивших управляемую отмену, большинство физических симптомов абстиненции — тремор, сердцебиение, головные боли и худшие нарушения сна — существенно уменьшились, и сон, как правило, стал более стабильным.\n\nПочему некоторые симптомы сохраняются\nЭштон документально подтверждает, что некоторые симптомы могут длиться месяцами. Через три месяца все еще могут проявляться затяжная тревога, затуманенность сознания и сенсорные изменения, пока мозг продолжает медленную, обратимую перенастройку.\n\nДве причины, по которым тревога сохраняется\n1. Система ГАМК мозга все еще адаптируется к нормальной чувствительности — медленный процесс.\n2. Любая скрытая тревога, которая привела к употреблению бензо, теперь ощущается без лекарственного буфера.\n\nХорошее время для терапии\nЕсли самые худшие ранние симптомы позади, три месяца — это хороший момент для использования поддержки, такой как разговорная терапия, такая как КПТ (КПТ), для лечения тревоги и развития навыков преодоления стресса, пока нервная система продолжает успокаиваться.';

  @override
  String get benzodiazepineReferenceDay180 =>
      'Мышление и память в шесть месяцев: измеримые успехи\n\nИсточник: Тата и др., «Отсутствие когнитивного восстановления после прекращения длительного употребления бензодиазепинов», Psychoological Medicine (1994), на PubMed.\n\nЧто дало исследование\nВ этом исследовании был протестирован 21 пациент, длительно принимавший бензодиазепины, перед отменой, сразу после отмены и снова через шесть месяцев воздержания, сравнивая их с соответствующей группой контроля. Это один из самых откровенных данных в литературе о восстановлении после бензодиазепинов.\n\nЧто он нашел\nДо прекращения у пациентов были проблемы с вербальным обучением, памятью, скоростью движений, зрительной координацией и зрительным мышлением. Сразу после остановки изменений было мало. К шести месяцам ситуация в некоторых из этих областей заметно улучшилась.\n\nЧто это значит\nК шести месяцам вербальное обучение, память, скорость движений и зрительная координация заметно восстановились. Улучшение уже было очевидным и имело место для продолжения.\n\nБольшая картина\nЕсли через шесть месяцев вы почувствуете затуманенность, это ожидаемо, и дальнейшее воздержание — это путь вперед. Долгосрочные исследования показывают, что восстановление продолжается и после этого момента — мозг продолжает восстанавливаться.';

  @override
  String get benzodiazepineReferenceDay365 =>
      'Год спустя после бензодиазепинов: мышление и память продолжают восстанавливаться\n\nИсточник: Баркер и др., «Сохранение когнитивных эффектов после прекращения длительного употребления бензодиазепинов: метаанализ», Архив клинической нейропсихологии (2004), на PubMed.\n\nСамые убедительные доказательства, которые у нас есть\nИсследователи объединили исследования, в которых повторно тестировались длительные потребители бензодиазепинов после как минимум шести месяцев прекращения приема препарата. Совокупный результат показывает явное восстановление мышления и памяти после отмены.\n\nХорошие новости\nОбъединенные исследования выявили подлинное, измеримое улучшение в нескольких областях мышления и памяти после отмены. Примерно через год восстановление будет широким и очевидным по сравнению с активным использованием.\n\nВосстановление продолжается\nСовместные исследования выявили значительное восстановление мышления и памяти. К году вы уже приближаетесь к тенденции восстановления, которую уже можно было измерить через шесть месяцев.\n\nЧто это значит через год\nОжидайте существенного восстановления мышления, памяти и ясности ума уже через год — большинство людей чувствуют себя заметно острее, чем во время использования. Но если в некоторых областях все еще наблюдается отставание, это соответствует фактическим данным, а не является признаком того, что вы зашли в тупик. Выздоровление продолжается, и год воздержания является важной и важной вехой на этом пути.';

  @override
  String get benzodiazepineReferenceDay540 =>
      '18 месяцев после бензодиазепинов: медленное, но реальное восстановление\n\nИсточник: Эштон, «Длительные синдромы отмены бензодиазепинов», Журнал лечения злоупотребления психоактивными веществами (1991), на PubMed.\n\nПочему восстановление после бензодиазепинов занимает так много времени\nБензодиазепины действуют на ГАМК, главную успокаивающую систему мозга. Длительное использование меняет то, насколько сильно реагирует эта система, и на то, чтобы обратить вспять эти изменения, могут потребоваться месяцы. Вот почему восстановление после бензодиазепинов измеряется месяцами, а не неделями.\n\nЧто означают 18 месяцев\nЭштон описывает более длительные симптомы абстиненции, для облегчения которых могут потребоваться месяцы. К 18 месяцам худшее уже позади, и сохраняющаяся тревога, сенсорные изменения и затуманивание сознания существенно утихли.\n\nМедленно обратимый\nВажно отметить, что Эштон определяет основные изменения как «медленно обратимые функциональные изменения в центральной нервной системе». Медленно, но обратимо — длительный срок отражает глубину адаптации, вызванной бензодиазепинами, а не необратимый ущерб у большинства людей.\n\nСигнал восстановления\nЭштон описывает основные изменения как медленно обратимые. К 18 месяцам успокаивающая система ГАМК мозга уже давно пришла в норму, и доминирующим направлением является дальнейшее восстановление до нормального состояния.';

  @override
  String get benzodiazepineReferenceDay730 =>
      'Два года после бензодиазепинов: значительный, устойчивый прогресс\n\nИсточник: Баркер и др., «Сохранение когнитивных эффектов после прекращения длительного употребления бензодиазепинов: метаанализ», Архив клинической нейропсихологии (2004), на PubMed.\n\nВеха в восстановлении\nДва года — это важная веха, особенно после длительного ухода. Фазы ранних и затяжных симптомов давно прошли, и успехи первого года должны были усилиться еще на один год.\n\nЧто подтверждают доказательства\nОбъединенные исследования показывают восстановление во многих областях после отмены. К двум годам большинство людей сообщают о тревожности на уровне, существовавшем до приема бензодиазепинов, или ниже, о надежном сне без лекарств, о более устойчивых эмоциях и более ясном мышлении, чем во время употребления.\n\nСигнал восстановления\nСовместные исследования установили восстановление во многих областях мышления и памяти. Через два года устойчивое восстановление является обоснованным ожиданием.\n\nСохраняя перспективу\nДва года дают сну, настроению, памяти и ясному мышлению долгое окно восстановления. Данные показывают существенное улучшение по всем четырем показателям, и с этого момента исцеление продолжается.';

  @override
  String get benzodiazepineReferenceDay1095 =>
      'Три года после бензодиазепинов: долгосрочное исцеление\n\nИсточник: Баркер и др., «Сохранение когнитивных эффектов после прекращения длительного употребления бензодиазепинов: метаанализ», Архив клинической нейропсихологии (2004), на PubMed.\n\nДлинный взгляд\nТри года — это крайний срок восстановления после бензодиазепинов. У подавляющего большинства людей, даже после тяжелой длительной абстиненции, разрушительные симптомы остаются далеко позади, и качество жизни меняется по сравнению с активным употреблением.\n\nЧто обнаружил метаанализ\nКомбинированные исследования, проведенные с участием длительных потребителей, показывают восстановление во многих областях после отмены. За годы воздержания преобладает общее восстановление мышления, памяти и повседневной деятельности.\n\nСигнал восстановления\nДолгосрочные исследования показывают восстановление во многих областях мышления и памяти. К трем годам ранние и затяжные этапы синдрома отмены уже далеко позади, и эти достижения должны были укрепиться годами.\n\nСообщение надежды\nПуть восстановления после бензодиазепинов — один из самых сложных в медицине, и три года устойчивого выздоровления — огромное достижение. Доказательства очевидны: мозг существенно восстанавливается, у большинства людей восстанавливается ясность ума, сон и эмоциональный диапазон, и улучшение продолжается со временем.';

  @override
  String get cocaineReferenceDay1 =>
      'Отказ от кокаина: первые 24 часа\n\nИсточник: «Синдромы абстиненции», StatPearls (Книжная полка NCBI), Национальная медицинская библиотека США.\n\nКокаин и мозг\nКокаин блокирует обратный захват дофамина (и других моноаминов) в цепях вознаграждения мозга, вызывая накопление дофамина и вызывая сильную эйфорию и энергию. При регулярном использовании мозг адаптируется, подавляя эту систему, так что без препарата нормальная деятельность кажется пресной.\n\nАвария\nStatPearls описывает отмену стимуляторов как начало «краха» после прекращения употребления, характеризующееся выраженной депрессией, чрезмерным сном, голодом, плохим настроением и серьезным замедлением движений и мышления. В первые 24 часа это обычно включает в себя:\n• Сильная усталость и повышенная потребность во сне.\n• Подавленное настроение и замедление движений и мышления.\n• Повышенный аппетит (кокаин подавляет аппетит).\n\nТяга, раздражительность и тревога также очень часто отмечаются в этот период в более широкой литературе по зависимостям, хотя StatPearls не относит их конкретно к краху.\n\nВ отличие от некоторых других лекарств\nStatPearls отмечает, что синдром отмены стимуляторов лечится наблюдением и поддерживающей терапией; в отличие от отмены алкоголя или бензодиазепинов, она обычно не вызывает судорог или делирия. Основная опасность носит психологический характер — во время аварии может возникнуть депрессия, а у злостных потребителей — суицидальные мысли, поэтому желательны поддержка и наблюдение.\n\nНет одобренного лекарства\nВ настоящее время не существует лекарств, одобренных для лечения синдрома отмены кокаина; ведение является поддерживающим, а немедикаментозные подходы, такие как управление в непредвиденных обстоятельствах, являются научно обоснованными методами лечения основного расстройства, связанного с употреблением наркотиков.';

  @override
  String get cocaineReferenceDay3 =>
      'Три дня без кокаина: преодоление пика\n\nИсточник: «Токсичность кокаина», StatPearls (Книжная полка NCBI), Национальная медицинская библиотека США.\n\nКак кокаин влияет на организм\nStatPearls документально подтверждает, что кокаин блокирует обратный захват дофамина, норадреналина и серотонина, продлевая симпатическую стимуляцию. Это то, что вызывает как эйфорию, так и опасность — оно может повлиять практически на каждую систему органов.\n\nДни 2–4: пик психологической абстиненции\nНа третий день острый кризис уступил место наиболее выраженной психологической абстиненции:\n• Плохое настроение и депрессивное настроение в наиболее сильной форме.\n• Потеря удовольствия\n• Сильная тяга, вызванная сигналом.\n• Тревога и беспокойство\n• Нарушенный сон — у одних чрезмерный, у других — бессонница.\n\nСердечно-сосудистая опасность отступает\nStatPearls определяет сердечно-сосудистую токсичность как самый смертельный эффект кокаина: повышение частоты сердечных сокращений и артериального давления, увеличение потребности миокарда в кислороде, коронарный вазоспазм и активация тромбоцитов, что повышает риск аритмии, инфаркта и инсульта даже у молодых потребителей. Период полувыведения кокаина короткий, около часа, и к третьему дню препарат сам полностью очистил вашу систему — хотя StatPearls отмечает, что его метаболиты все еще могут вызывать сужение кровеносных сосудов в течение нескольких часов после употребления, а один метаболит может сохраняться в течение нескольких недель, поэтому некоторая остаточная сердечно-сосудистая нагрузка может пережить сам препарат.\n\nДорога вперед\nОстрая фаза является интенсивной, но именно психологические симптомы — депрессия, тяга, потеря удовольствия — требуют наибольшей поддержки и сохраняются дольше всего.';

  @override
  String get cocaineReferenceDay7 =>
      'Одна неделя без кокаина: начинается физическое выздоровление\n\nИсточник: «Синдромы абстиненции», StatPearls (Книжная полка NCBI), Национальная медицинская библиотека США.\n\nОстрая фаза заканчивается\nStatPearls описывает отказ от кокаина как переход от первоначального кризиса к более длительной фазе восстановления. К концу первой недели самые худшие симптомы обычно ослабевают, а дофаминовая система продолжает восстанавливаться.\n\nФизическое восстановление продолжается\nКак только симпатическая стимуляция кокаина прекращается, его эффекты на сердечно-сосудистую систему, аппетит, сон и дыхательные пути начинают меняться вспять в течение следующих дней и недель:\n• Частота пульса и артериальное давление возвращаются к норме\n• Аппетит постепенно возвращается (кокаин его сильно подавляет)\n• Режим сна начинает стабилизироваться.\n• Носовые ходы начинают заживать после употребления кокаина.\n\nПсихологические симптомы продолжаются\nStatPearls отмечает, что депрессия и потеря удовольствия характерны для отмены стимуляторов и сохраняются дольше, чем физические симптомы:\n• Настроение остается плохим, хотя и менее тяжелым, чем на пике.\n• Тяга, вызванная сигналом, остается сильной.\n• Концентрация и мотивация по-прежнему нарушены.\n\nПост-острая фаза\nЗатем абстиненция переходит в недели или месяцы более устойчивого улучшения настроения, тяги и ясности мышления. Знание этой закономерности облегчает управление более медленной частью восстановления.';

  @override
  String get cocaineReferenceDay14 =>
      'Две недели без кокаина: обретение стабильности\n\nИсточник: «Синдромы абстиненции», StatPearls (Книжная полка NCBI), Национальная медицинская библиотека США.\n\nДве недели через\nК двум неделям серьезные симптомы аварии — глубокая депрессия, много сна, замедление движений и мышления — в целом ослабли. Восстановление теперь сосредоточено на восстановлении мозга и эмоционального здоровья.\n\nНастроение и эмоциональное состояние\nЧерез две недели настроение все еще может быть ниже нормы, пока дофаминовая система восстанавливается. По сравнению с первой неделей глубокая потеря удовольствия ослабевает и возвращаются моменты настоящего благополучия.\n\nТяга и триггеры\nНа этом этапе тяга, вызванная сигналом, представляет собой серьезную проблему. Мозг сформировал прочные ассоциации между употреблением кокаина и конкретной средой, людьми, эмоциями и деятельностью. Встреча с любым из этих триггеров может вызвать сильную тягу, даже когда общее настроение улучшается. Важно избегать сред высокого риска и создавать новые ассоциации.\n\nУлучшение сна\nК двум неделям сон обычно становится более стабильным и восстанавливающим, чем во время острой фазы отмены. Улучшение сна оказывает значительное положительное влияние на настроение, ясность мышления и способность контролировать тягу.\n\nСоздание фундамента\nПоскольку основанные на фактических данных методы лечения расстройств, вызванных употреблением стимуляторов, являются поведенческими (управление непредвиденными обстоятельствами, терапия и поддержка со стороны коллег), двухнедельная отметка является важным временем для взаимодействия со структурами поддержки, которые будут способствовать долгосрочному выздоровлению.';

  @override
  String get cocaineReferenceDay60 =>
      'Два месяца без кокаина: настроение и вознаграждение начинают восстанавливаться\n\nИсточник: «Выздоровление от кокаина: результаты клинических и доклинических исследований», Neuroscience & Biobehavioral Reviews (2013), на PubMed Central.\n\nЧто делает мозг\nВ этом обзоре синтезированы исследования на людях и животных того, что происходит с мозгом, когда прекращается употребление кокаина. Хронический прием кокаина изменяет дофаминовую систему и снижает активность лобной коры; восстановление этих систем является основой улучшения настроения и мотивации, которое люди замечают при раннем воздержании.\n\nПрогресс системы вознаграждений\nВ исследованиях на животных связанные с кокаином изменения в дофаминовых рецепторах и перерабатывающих белках возвращались к здоровому уровню при устойчивом воздержании. По мере восстановления системы вознаграждения глубокая утрата удовольствия проходит, и повседневные награды — еда, общение, достижения — снова кажутся полезными.\n\nСигнал восстановления\nК двум месяцам настроение улучшается, сон становится более устойчивым, а дофаминовая система и системы лобной коры продолжают восстанавливаться. Исследования на приматах показывают, что связанные с кокаином изменения рецептора и транспортера D1 возвращаются к контрольным уровням при устойчивом воздержании.';

  @override
  String get cocaineReferenceDay90 =>
      'Три месяца без кокаина: восстановление маркеров дофамина\n\nИсточник: «Выздоровление от кокаина: результаты клинических и доклинических исследований», Neuroscience & Biobehavioral Reviews (2013), на PubMed Central.\n\nПочему 90 дней — это знаковое событие\nВ этом обзоре трехмесячный период подчеркивается как биологически значимый. У приматов, не являющихся людьми, рецепторы и транспортеры дофамина D1, повышенный уровень кокаина, продемонстрировали «доказательства возврата к контрольным уровням» примерно через 90 дней воздержания — прямое доказательство того, что система вознаграждения может перестроиться после прекращения приема наркотика.\n\nПередняя часть мозга\nАвторы выделяют восстановление передней части мозга как один из наиболее важных признаков длительного воздержания. Эта область отвечает за контроль импульсивности, принятие решений и самоконтроль, и эти способности усиливаются по мере выздоровления.\n\nЧто показывают 90 дней\nЧерез 90 дней исследования на приматах показали, что плотность D1, D2 и транспортеров дофамина больше существенно не отличается от контрольной группы, не получавшей лекарств. Даже после длительного воздействия к этому моменту уже заметно значительное восстановление дофаминовой системы, которое продолжается при воздержании.';

  @override
  String get cocaineReferenceDay180 =>
      'Шесть месяцев без кокаина: более ясное мышление\n\nИсточник: «Структурное и функциональное восстановление мозга у людей с расстройствами, вызванными употреблением психоактивных веществ во время абстиненции: обзор продольных исследований нейровизуализации», на PubMed Central.\n\nВосстановление, которое вы можете создать\nВ этом обзоре собраны лонгитудинальные исследования по визуализации мозга, в которых неоднократно сканировались одни и те же люди по мере увеличения срока их воздержания. В отношении кокаина сообщается, что функциональная активность заметно восстанавливается при длительном воздержании.\n\nДоказательства визуализации мозга\nДва исследования с помощью функциональной МРТ отслеживали употребление кокаина с течением времени, и оба обнаружили улучшение активации среднего мозга и таламуса при более длительном воздержании. У одного из них, примерно через шесть месяцев воздержания, характер активации мозга был сравним с таковым у здоровых людей из контрольной группы, не страдающих зависимостью. Что касается веществ, в обзоре отмечается, что результаты ядерной визуализации указывают на дофаминергическое восстановление при воздержании.\n\nЧто это значит в шесть месяцев\nЭти функциональные преимущества соответствуют реальным улучшениям, о которых люди сообщают на этом этапе:\n• Улучшение внимания и рабочей памяти.\n• Более четкое принятие решений и контроль импульсивности\n• Более устойчивое настроение и эмоциональная регуляция.\n\nСигнал восстановления\nПримерно через шесть месяцев одна продольная когорта фМРТ показала картину активации, сравнимую с таковой у здоровых людей из контрольной группы, не страдающих зависимостью, в то время как активация среднего и глубокого мозга улучшалась по мере увеличения срока воздержания. Это прямо отражает функциональное восстановление мозга.';

  @override
  String get cocaineReferenceDay365 =>
      'Год без кокаина: устранена нагрузка на сердечно-сосудистую систему\n\nИсточник: «Токсичность кокаина», StatPearls (Книжная полка NCBI), Национальная медицинская библиотека США.\n\nПочему сердце занимает центральное место\nStatPearls определяет сердечно-сосудистую токсичность как самый смертельный эффект кокаина. Каждое употребление повышает частоту сердечных сокращений, артериальное давление и потребность миокарда в кислороде, одновременно вызывая спазм коронарных артерий и способствуя образованию тромбов — сочетание, которое приводит к сердечному приступу, аритмии и инсульту даже у молодых людей.\n\nЧто удаляет год воздержания\nКаждый день без кокаина — это день, свободный от этих острых оскорблений. За год исчезли повторяющиеся скачки артериального давления и частоты сердечных сокращений, устранен риск вызванного кокаином коронарного спазма и острого инфаркта, сердце больше не подвергается кислородному несоответствию.\n\nСигнал восстановления\nОтказ от употребления кокаина останавливает повторный коронарный вазоспазм, тахикардию, гипертонию, образование тромбов и несоответствие кислорода, которые приводят к острому повреждению сердца. Существующий фиброз или миокардит остается медицинской проблемой, но повторяющиеся приступы, вызванные кокаином, прошли.\n\nВосстановление мозга тоже\nК одному году системам вознаграждения и самоконтроля требуется больше времени для восстановления, что обеспечивает лучший контроль над импульсами, более устойчивое настроение и более сильную реакцию на повседневные награды.';

  @override
  String get cocaineReferenceDay730 =>
      'Два года без кокаина: устойчивое восстановление\n\nИсточник: «Выздоровление от кокаина: результаты клинических и доклинических исследований», Neuroscience & Biobehavioral Reviews (2013), на PubMed Central.\n\nДлинный взгляд\nВ этом обзоре собраны результаты исследований на людях и животных о длительном воздержании от кокаина. Главный вывод состоит в том, что сохранение и восстановление функции лобной коры является наиболее важным маркером длительного воздержания: у людей с длительным воздержанием (10+ месяцев), наблюдается более высокая активность лобной коры, чем у людей с более коротким периодом воздержания.\n\nЧто продолжает исцеляться\n• Маркеры дофамина, измененные под воздействием кокаина, продолжают приближаться к норме при устойчивом воздержании.\n• Снижение целостности серого и белого вещества, наблюдаемое у активных потребителей и потребителей на раннем этапе воздержания, может обратить вспять при более длительном воздержании, возможно, за счет продолжающегося созревания миелина.\n• Схема фронтального контроля — контроль импульсов, суждение, эмоциональная регуляция — усиливается.\n\nСигнал восстановления\nАвторы выражают настоящую научную осторожность: некоторые различия в длительном воздержании могут отражать «эффект выжившего» — людям, которые начали с большей целостностью мозга, может быть легче оставаться воздержанным — а не только восстановлением. Ясно то, что два года без кокаина поддерживают мозг, функционирующий гораздо ближе к тому, который есть у человека, не употребляющего кокаин, и жизнь, которая не просто воздерживается от употребления кокаина, но и существенно перестраивается.';

  @override
  String get ghbReferenceDay1 =>
      'Синдром отмены ГОМК: первые часы\n\nИсточник: «Характеристика синдрома отмены ГОМК», на PubMed Central.\n\n⚠ Это неотложная медицинская помощь\nОтказ от ГОМК считается одним из самых опасных видов синдрома отмены психоактивных веществ, конкурируя с тяжелой абстиненцией от алкоголя и бензодиазепинов. Без лечения более чем в половине случаев заболевание может прогрессировать до делирия с опасными колебаниями частоты сердечных сокращений, артериального давления и судорогами. Любой, кто зависит от ГОМК, ГБЛ или 1,4-бутандиола, должен пройти контролируемую стационарную детоксикацию, а не останавливаться в одиночку.\n\nПочему все начинается так быстро\nПериод полувыведения ГОМК составляет всего 30–60 минут, и зависимым потребителям обычно приходится повторять дозу каждые 2–3 часа, чтобы избежать абстиненции — гораздо быстрее, чем у алкоголя или бензодиазепинов. Именно быстрая фармакокинетика является причиной того, что симптомы могут появиться намного раньше, чем при отмене других седативных и снотворных средств.\n\nРанние симптомы\nТревога, бессонница, тремор, потливость, учащенное сердцебиение и повышение артериального давления.';

  @override
  String get ghbReferenceDay3 =>
      'Отказ от ГОМК: самые тяжелые дни\n\nИсточник: «Характеристика синдрома отмены ГОМК», на PubMed Central.\n\nСамый тяжелый этап\nЭто исследование показало, что некоторые основные симптомы абстиненции — мышечные боли, мышечные подергивания, чувство напряжения и стресса, учащенное сердцебиение и спазмы в животе — были наиболее сильными в первые три дня, а к четвертому дню тяжесть многих симптомов снизилась более чем на 70%. Это раннее окно, как правило, является периодом самого высокого риска, когда нелеченая абстиненция, скорее всего, перерастет в делирий, судороги или опасные колебания частоты сердечных сокращений и артериального давления.\n\nТяжелые особенности\n• Сильное возбуждение и тревога.\n• Слуховые и зрительные галлюцинации, паранойя.\n• Тремор, потливость, учащенное сердцебиение и высокое кровяное давление.\n• Риск судорог\n\nЛечение\nВ исследовании описывается снижение дозы бензодиазепинов и снижение дозы фармацевтического ГОМК как два широко используемых метода детоксикации, отмечая некоторые доказательства того, что снижение дозы ГОМК может контролировать симптомы более эффективно, чем одни только бензодиазепины. Любой подход требует тщательного мониторинга — управлять этим дома небезопасно.';

  @override
  String get ghbReferenceDay7 =>
      'Одна неделя без ГОМК\n\nИсточник: «Характеристика синдрома отмены ГОМК», на PubMed Central.\n\nБольшинство симптомов исчезают\nТяжесть и распространенность некоторых основных симптомов абстиненции снизились более чем на 70% в течение первых четырех дней. При контролируемом постепенном сокращении сама фаза снижения длилась в среднем 11 дней, за которой следовала фаза восстановления, продолжавшаяся около шести дней — таким образом, через неделю многие люди уже достигли этого улучшения, даже если процесс еще не полностью завершен.\n\nЧто может задержаться\n• Потливость, тремор и трясущиеся руки.\n• Много спит или, наоборот, бессонница и беспокойство.\n• Тяга к ГОМК\n\nИсследование показало, что эти конкретные симптомы изменились сравнительно мало даже за 11 дней, поэтому сохранение их на этой неделе не является чем-то необычным. Постоянный медицинский надзор остается важным до тех пор, пока синдром не исчезнет.';

  @override
  String get ghbReferenceDay14 =>
      'Две недели без ГОМК\n\nИсточник: «Характеристика синдрома отмены ГОМК», на PubMed Central.\n\nПреодоление острого синдрома\nЧерез две недели острый соматический синдром, описанный в этом исследовании, фазы снижения дозы и восстановления которого вместе составляют в среднем около 17 дней при контролируемом лечении, в целом исчез или очень близок к этому. Частота сердечных сокращений, артериальное давление и большинство физических симптомов должны стабилизироваться.\n\nЧто задерживается\nВ исследовании особо отмечается, что тяга к ГОМК и бессонница все еще присутствуют при выписке у некоторых пациентов, отмечая, что они могут способствовать риску рецидива. Поддержка и структура имеют значение сейчас, даже несмотря на то, что опасный ранний этап уже позади.';

  @override
  String get ghbReferenceDay30 =>
      'Месяц без ГОМК\n\nИсточник: «Характеристика синдрома отмены ГОМК», на PubMed Central.\n\nЧто означает один месяц\nОстрая опасная фаза, описанная в этом исследовании, уже прошла на один месяц. К месяцу острая опасная фаза, сконцентрированная в первые дни и сопровождаемая контролируемым периодом снижения дозы и восстановления, продолжающимся в среднем примерно две с половиной недели, уже давно проходит. Тяга и бессонница являются ключевыми остаточными рисками рецидива, выявленными при выписке.\n\nПочему поддержка все еще помогает\nЕсли тяга к ГОМК, плохое настроение или проблемы со сном все еще присутствуют в течение одного месяца, это соответствует тому, что авторы исследования назвали факторами риска рецидива — именно поэтому постоянная поддержка и структурирование имеют значение.';

  @override
  String get ghbReferenceDay90 =>
      'Три месяца без ГОМК\n\nИсточник: «Характеристика синдрома отмены ГОМК», на PubMed Central.\n\nТри месяца восстановления\nК трем месяцам острый синдром отмены ГОМК надолго проходит. Остаточными рисками, выявленными при выписке, являются тяга к ГОМК и бессонница, поэтому три месяца воздержания дают достаточно времени для закрепления сна, вегетативной стабильности и мероприятий по предотвращению рецидивов.\n\nЧто обычно сообщают люди\n• Более спокойное обычное настроение\n• Более надежный сон\n• Более ясное мышление и менее выраженная тяга к ГОМК\n\nЕсли тревога, бессонница или плохое настроение по-прежнему сохраняются в течение трех месяцев, стоит обсудить это с врачом, а не предполагать, что проблема пройдет сама по себе.';

  @override
  String get ghbReferenceDay180 =>
      'Шесть месяцев без ГОМК\n\nИсточник: «Характеристика синдрома отмены ГОМК», на PubMed Central.\n\nПолгода спустя\nК шести месяцам острый синдром отмены ГОМК уже давно проходит, и восстановление полностью переходит от детоксикации к стабильному сну, контролю тяги и предотвращению рецидивов. Опасная вегетативная фаза с риском делирия относится к первым дням и неделям, а не к этой стадии.\n\nБольшая картина\nБезопасное преодоление отмены ГОМК и воздержание от него в течение полугода является крупным достижением, учитывая, насколько опасна ранняя фаза и насколько реальным может быть риск рецидива, частично вызванный сохраняющейся тягой к ГОМК и бессонницей. Распорядок дня и поддержка, которые привели вас сюда, стоят того, чтобы их сохранить.';

  @override
  String get inhalantsReferenceDay1 =>
      'Отказ от ингалянтов: день первый\n\nИсточник: Радпарвар, «Клиническая оценка и лечение злоупотребления ингалянтами», The Permanente Journal (2023), на PubMed Central.\n\nПочему возникает абстиненция\nХроническое употребление ингалянтов вызывает нейроадаптацию — нервная система начинает ожидать этого вещества. Многие ингалянты воздействуют на те же цепи мозга, что и алкоголь, поэтому прекращение их употребления приводит к временному дисбалансу мозга. Летучие вещества быстро выводятся из крови, но могут накапливаться в жировой ткани, что может сделать время отмены непредсказуемым.\n\nРанние симптомы\nВ этом обзоре синдром отмены ингалянтов описывается как похожий на синдром отмены алкоголя или бензодиазепинов; среди описанных симптомов:\n• Тошнота, рвота и потливость.\n• Тремор и учащенное сердцебиение\n• Бессонница и нарушение сна.\n• Тревога и раздражительность\n\nПримечание по безопасности\nВ более тяжелых случаях в обзоре также перечислены галлюцинации, бред и судороги среди сообщаемых симптомов, хотя в нем не указан точную посуточную хронологию — их следует считать возможными симптомами, а не фиксированной последовательностью. Медицинский контроль во время детоксикации целесообразен, особенно для тяжелых и длительных потребителей.';

  @override
  String get inhalantsReferenceDay7 =>
      'Одна неделя без ингалянтов\n\nИсточник: Радпарвар, «Клиническая оценка и лечение злоупотребления ингалянтами», The Permanente Journal (2023), на PubMed Central.\n\nОстрый период\nВ клинической литературе синдром отмены ингалянтов описывается как синдром отмены алкоголя или бензодиазепинов, но обычно считается, что он кратковременный. К концу первой недели острые физические симптомы — тошнота, тремор, потливость, бессонница — обычно проходят у большинства людей.\n\nЧто осталось\n• Усталость и затуманенность сознания.\n• Плохое или нестабильное настроение.\n• Тяга к ингалянтам\n\nПримечание о раннем воздержании\nМозговой туман на этом этапе не означает длительного повреждения — мозг все еще перестраивается. Исследования того, как мышление и память восстанавливаются в течение следующих недель и месяцев, рассматриваются в последующих этапах.';

  @override
  String get inhalantsReferenceDay14 =>
      'Две недели без ингалянтов\n\nИсточник: Радпарвар, «Клиническая оценка и лечение злоупотребления ингалянтами», The Permanente Journal (2023), на PubMed Central.\n\nПосле острой фазы\nКлинические обзоры описывают отмену ингалянтов как аналогичную отмене алкоголя или бензодиазепинов, но более короткую. К двум неделям тошнота, тремор, бессонница и тревога обычно проходят.\n\nДорога вперед\nВнимание, память, движение и координация восстанавливаются более постепенно в течение следующих месяцев. Продолжительное воздержание дает всем этим системам время для улучшения. Хорошее питание (применение ингаляционных препаратов может привести к истощению запасов витамина B12) и воздержание создают предпосылки для этого.';

  @override
  String get inhalantsReferenceDay30 =>
      'Месяц без ингалянтов\n\nИсточник: Дингуолл и др., «Когнитивное восстановление во время и после лечения злоупотребления летучими растворителями», Зависимость от наркотиков и алкоголя (2011), на PubMed.\n\nЧто означает один месяц\nРанний период абстиненции уже позади. В этом исследовании некоторые навыки обучения улучшились в течение шести недель, тогда как зрительная координация, память, планирование и принятие решений улучшались более постепенно в течение следующих месяцев.\n\nЧто можно улучшить\n• Внимание и некоторые учебные задачи.\n• Настроение и сон по мере стабилизации организма.\n• Скорость движений — постепенно\n\nСигнал восстановления\nВывод исследования ясен: память, планирование и принятие решений улучшаются постепенно в течение месяцев или лет воздержания. Продолжающееся воздержание является сильнейшим фактором этого выздоровления.';

  @override
  String get inhalantsReferenceDay90 =>
      'Три месяца без ингалянтов\n\nИсточник: Дингуолл и др., «Когнитивное восстановление во время и после лечения злоупотребления летучими растворителями», Зависимость от наркотиков и алкоголя (2011), на PubMed.\n\nНеравномерный и более длительный процесс\nВ этом исследовании наблюдались люди, прошедшие восьминедельную программу лечения, а некоторых из них проверяли снова примерно через год. Некоторые навыки обучения улучшились в течение шести недель, тогда как зрительная координация, память, планирование и принятие решений продолжали улучшаться в течение более длительного периода.\n\nОставаясь на курсе\nИсследование показывает, что функции, которые восстанавливаются медленнее, улучшаются постепенно, в течение месяцев или лет. Через три месяца продолжающееся воздержание является самым сильным рычагом для дальнейшего выздоровления месяц за месяцем.';

  @override
  String get inhalantsReferenceDay365 =>
      'Год без ингалянтов\n\nИсточник: «Проспективное исследование нейрокогнитивных изменений через 15 лет после хронического злоупотребления ингалянтами», на PubMed.\n\nРеальное, измеримое восстановление\nДолгосрочное исследование показало значительное выздоровление от хронических нейрокогнитивных нарушений, связанных с ингалянтами, после двух лет воздержания. Через год вы уже успешно продвинулись по пути восстановления.\n\nЧто это значит\nПамять, внимание и двигательные функции продолжают улучшаться. Длительное воздержание приводит к подлинному восстановлению мозга: к двум годам большинство показателей работы мозга, памяти и мышления вернулись к норме у хронических потребителей, у которых не было повреждений головного мозга из-за свинца.';

  @override
  String get inhalantsReferenceDay730 =>
      'Два года без ингалянтов\n\nИсточник: «Проспективное исследование нейрокогнитивных изменений через 15 лет после хронического злоупотребления ингалянтами», на PubMed.\n\nДвухлетний рубеж\nЭто ключевая веха в исследовании: дефицит, отражающий повреждение головного мозга в результате длительного употребления растворителей, значительно восстановился после двух лет воздержания. Авторы пришли к выводу, что при отсутствии повреждений головного мозга от этилированного бензина длительное воздержание может позволить восстановить нормальную функцию мозга.\n\nСигнал восстановления\nОсновным исключением является ущерб от злоупотребления этилированным бензином, который может вызвать постоянный дефицит. В противном случае два года воздержания представляют собой лучшую задокументированную возможность для восстановления мозга — наряду с жизнью, построенной вокруг него.';

  @override
  String get ketamineReferenceDay1 =>
      'Отказ от кетамина: первый день\n\nИсточник: «Цистит, вызванный кетамином: комплексный обзор урологических эффектов этого психоактивного препарата», на PubMed Central.\n\nАбстиненция в основном психологическая\nВ отличие от опиоидов или алкоголя, кетамин редко вызывает тяжелую физическую абстиненцию. Прекращение приема обычно безопасно; люди чаще сталкиваются с тягой к кетамину и психологической зависимостью, чем с выраженными физическими симптомами.\n\nЧто вы можете почувствовать\n• Перепады настроения и сниженное настроение\n• Тяга к кетамину\n• Периодическое потоотделение или сердцебиение.\n\nКлючевой шаг\nДля любого человека с симптомами мочевого пузыря немедленный и полный отказ от кетамина является обязательной отправной точкой для восстановления, поэтому первый день является самым важным решением из всех.';

  @override
  String get ketamineReferenceDay7 =>
      'Одна неделя без кетамина\n\nИсточник: «Цистит, вызванный кетамином: комплексный обзор», на PubMed Central.\n\nПсихологическая фаза\nОсновная проблема при раннем отказе от кетамина носит психологический характер: тяга к кетамину, изменение или плохое настроение, а также некоторый туман в голове. Физическая абстиненция, если она присутствует, обычно легкая.\n\nНа этой стадии часто встречается затуманивание сознания: концентрация требует усилий, время реакции замедляется, а кратковременная память может показаться ненадежной. Это влияние на мышление и память улучшается при воздержании: продольное исследование 114 потребителей кетамина выявило значительное улучшение вербальной и зрительной памяти, скорости обработки информации, а также планирования, концентрации и принятия решений после 12 недель без кетамина.\n\nСимптомы мочевого пузыря\nЕсли у вас цистит, вызванный кетамином (императивные позывы к мочеиспусканию, частое мочеиспускание, боль или кровь в моче), прекращение приема препарата сейчас дает мочевому пузырю лучший шанс на выздоровление. Боль может побудить людей вернуться к кетамину для самолечения — вместо этого стоит разорвать порочный круг с помощью надлежащей обезболивающей поддержки.';

  @override
  String get ketamineReferenceDay14 =>
      'Две недели без кетамина\n\nИсточник: «Цистит, вызванный кетамином: комплексный обзор», на PubMed Central.\n\nБолее ясное мышление\nКогда наркотик полностью выведен из организма, туман в уме и бессвязное мышление, связанные с регулярным употреблением кетамина, начинают рассеиваться. Улучшаются память и концентрация, а настроение стабилизируется.\n\nНачало восстановления мочевого пузыря\nВ обзоре подчеркивается, что для ранней стадии цистита полный отказ от кетамина является самым важным шагом для уменьшения симптомов, и что более раннее прекращение приема дает лучшие шансы на выздоровление до того, как повреждение станет необратимым. Две недели воздержания — начало этого процесса.';

  @override
  String get ketamineReferenceDay30 =>
      'Месяц без кетамина\n\nИсточник: «Распространенность и естественная история мочевых симптомов среди потребителей кетамина в рекреационных целях», Уинсток и др., BJU International (2012).\n\nВосстановление мочевого пузыря\nЕдинственным наиболее важным методом лечения кетаминового цистита является прекращение приема кетамина. Это исследование рекреационных потребителей кетамина показало, что 51% из тех, у кого были симптомы мочеиспускания, сообщили об улучшении после прекращения употребления, тогда как менее 4% стало хуже. Чем раньше вы остановитесь, тем лучше будет результат.\n\nРазум и настроение\nПознание и настроение продолжают улучшаться в течение одного месяца. Психологическая и социальная поддержка существенно повышает шансы отказаться от кетамина — сохранять отказ легче, когда есть поддержка.';

  @override
  String get ketamineReferenceDay90 =>
      'Три месяца без кетамина\n\nИсточник: «Цистит, вызванный кетамином: комплексный обзор», на PubMed Central.\n\nПродолжение восстановления\nВосстановление мочевого пузыря после кетамина часто происходит постепенно; в обзоре описано уменьшение выраженности симптомов после отказа от кетамина, хотя оно может быть длительным и вариабельным. Три месяца дают мочевыводящим путям продолжительное время для заживления в тех случаях, когда на лечение ожидается ответ.\n\nРазум\nМышление заметно яснее, настроение стабильнее, чем при раннем воздержании, а тяга к кетамину возникает реже. Стойкие или тяжелые симптомы со стороны мочевого пузыря требуют оценки уролога.';

  @override
  String get ketamineReferenceDay180 =>
      'Шесть месяцев без кетамина\n\nИсточник: «Цистит, вызванный кетамином: комплексный обзор», на PubMed Central.\n\nПолгода спустя\nПри длительном воздержании симптомы со стороны мочевого пузыря продолжают улучшаться в тех случаях, когда они уменьшаются после отказа от кетамина, а мышление, память и настроение остаются стабильными. Компульсивное желание употребить кетамин значительно ослабло.\n\nСигнал восстановления\nВосстановление установленного повреждения мочевого пузыря может быть неполным, поэтому ранний отказ от кетамина имеет такое большое значение. На каком бы этапе вы ни отказались от кетамина, сохранение воздержания дает мочевому пузырю наилучший шанс на восстановление.';

  @override
  String get ketamineReferenceDay365 =>
      'Год без кетамина\n\nИсточник: «Цистит, вызванный кетамином: комплексный обзор», на PubMed Central.\n\nГод спустя\nДвенадцать месяцев воздержания дают мочевому пузырю (в случаях раннего выявления) максимальный шанс на восстановление и сохраняют мышление, память и настроение стабильными и ясными. Психологическая зависимость, из-за которой было трудно остановиться, в значительной степени исчезла.\n\nБольшая картина\nГод без кетамина означает глубокие изменения в физическом здоровье, ясности мышления и самостоятельности. Поддержка, которая помогла вам достичь этого этапа, помогает сохранить достигнутое.';

  @override
  String get kratomReferenceDay1 =>
      'Отказ от кратома: первый день\n\nИсточник: Своггер и др. (2022), «Понимание использования кратома: руководство для поставщиков медицинских услуг», Frontiers in Pharmacology.\n\nПочему возникает абстиненция\nАктивные соединения Кратома действуют на те же опиоидные рецепторы, что и классические опиоиды. При регулярном употреблении организм адаптируется, поэтому прекращение приема приводит к синдрому отмены, подобному опиоидному. В этом клиническом руководстве зависимость и синдром абстиненции описываются как признанные риски регулярного употребления кратома.\n\nЧто показывают данные о начале\nИсследования на животных, упомянутые в руководстве, показывают, что соматические симптомы абстиненции появляются примерно через 12 часов, а эффекты, подобные тревоге, проявляются через 24 часа; Точное время начала заболевания у человека менее установлено, но обычно сообщаемые ранние симптомы включают:\n• Беспокойство, тревога и раздражительность.\n• Мышечные боли и насморк.\n• Потливость и слезотечение.\n• Тяга к кратому\n\nПримечание о серьезности\nВ руководстве отмечается, что более длительная продолжительность применения и более высокие дозы связаны с более тяжелой и продолжительной абстиненцией. Стоит обратиться за медицинской помощью под наблюдением, особенно если кратом использовался в высоких дозах или вместе с опиоидами.';

  @override
  String get kratomReferenceDay3 =>
      'Отказ от кратома: самые тяжелые дни\n\nИсточник: Сингх и др. (2014), Зависимость от наркотиков и алкоголя - опрос 293 регулярных потребителей кратома в Малайзии.\n\nЧто показывают доказательства\nЭто исследование показало, что вместо одного определенного «пикового дня» тяжесть абстиненции отслеживает, сколько и как долго кто-то употреблял: люди, выпивающие три или более стаканов кратома в день, имели значительно более высокие шансы на тяжелую зависимость и более трудную абстиненцию. Для большинства людей первые несколько дней после прекращения употребления кратома являются самыми тяжелыми.\n\nЧасто встречающиеся симптомы\n• Боли в мышцах и суставах, беспокойство в ногах.\n• Бессонница, несмотря на утомление.\n• Тошнота, спазмы желудка и диарея.\n• Тревога, плохое настроение и раздражительность.\n• Сильная тяга к кратому.\n\nКак пройти через это\nГидратация, отдых и симптоматическая поддержка помогают. Если до сих пор абстиненция ощущалась серьезной, это связано с более тяжелым или длительным употреблением, а не с чем-то необычно неправильным - и с этого момента она имеет тенденцию ослабевать.';

  @override
  String get kratomReferenceDay7 =>
      'Одна неделя без кратома\n\nИсточник: Своггер и др. (2022), «Понимание использования кратома: руководство для поставщиков медицинских услуг», Frontiers in Pharmacology.\n\nПрохождение острой фазы\nДанные самоотчетов людей, приведенные в этом руководстве, показывают, что симптомы абстиненции проходят в течение примерно одного-трех дней для большинства людей, которые прекращают употребление кратома. К одной неделе острые физические симптомы — мышечные боли, потливость, тошнота — обычно у большинства проходят. То, что может остаться, является более психологическим: усталость, нарушение сна и плохое настроение, поскольку опиоидные рецепторы, которые стимулировал кратом, приспосабливаются к собственным сигналам организма.\n\nРеальный риск\nВ руководстве также отмечается, что небольшому количеству людей очень трудно отказаться от кратома, при этом более тяжелая и длительная абстиненция наблюдается среди более тяжелых и длительных потребителей. Эта неделя является обычным моментом для рецидивов, и толерантность быстро падает — возвращение к предыдущей дозе, особенно если речь идет об опиоидах, теперь действительно опасно.';

  @override
  String get kratomReferenceDay14 =>
      'Две недели без кратома\n\nИсточник: Национальный институт по борьбе со злоупотреблением наркотиками (NIDA), «Кратом».\n\nЗа пределами изучаемого окна\nКонтролируемые человеческие данные о сроках отмены кратома обычно охватывают только первые несколько дней, поэтому не существует четко установленных исследований, определяющих конкретный «двухнедельный» этап. Документально подтверждена более широкая закономерность: кратом действует на те же опиоидные рецепторы, что и классические опиоиды, и по мере прекращения регулярного употребления эти рецепторы постепенно восстанавливают свою чувствительность к собственным сигналам организма.\n\nЧто обычно сообщают люди\n• Аппетит и энергия часто улучшаются.\n• Сон становится более надежным.\n• Настроение обычно более устойчивое, хотя и все еще изменчивое.\n\nТяга к кратому по-прежнему вызывается стрессом и знакомыми сигналами, поэтому иметь план на ее счет по-прежнему полезно.';

  @override
  String get kratomReferenceDay30 =>
      'Месяц без кратома\n\nИсточник: Национальный институт по борьбе со злоупотреблением наркотиками (NIDA), «Кратом».\n\nВосстановление системы вознаграждений\nNIDA описывает, что кратом действует на опиоидные рецепторы мозга, при этом зависимость и абстиненция являются признанными рисками регулярного употребления. Конкретного исследования, определяющего этап выздоровления в один месяц, не существует, но общая картина зависимости, основанной на опиоидных рецепторах, такова, что реакция мозга на повседневные удовольствия постепенно нормализуется при длительном воздержании.\n\nЧто может дать месяц без кратома\nМесяц без кратома — это месяц постоянного сна, еды и рутины, заменяющих необходимые затраты времени и усилий. Тяга, как правило, возникает реже и становится более управляемой, хотя моменты сильного стресса остаются наиболее уязвимыми.';

  @override
  String get kratomReferenceDay90 =>
      'Три месяца без кратома\n\nИсточник: Национальный институт по борьбе со злоупотреблением наркотиками (NIDA), «Кратом».\n\nБолее устойчивое повседневное состояние\nКратом действует на опиоидные рецепторы, поэтому три месяца без него дают мозгу и системам стресса достаточно времени, чтобы успокоиться. Многие люди сообщают о более ясном мышлении и более устойчивой мотивации по мере того, как они продвигаются от активного использования.\n\nПочему это важно\nЧем больше времени проходит без кратома, тем слабее обычно становится ежедневная тяга к нему, что делает эту веху прочной основой для длительного выздоровления.';

  @override
  String get kratomReferenceDay365 =>
      'Год без кратома\n\nИсточник: Национальный институт по борьбе со злоупотреблением наркотиками (NIDA), «Кратом».\n\nДалеко за пределами острой абстиненции\nNIDA не публикует конкретные годичные сроки восстановления после употребления кратома, но год устойчивого воздержания выходит далеко за рамки острого и раннего периода психологической абстиненции, зафиксированного в исследованиях кратома. Для большинства людей, достигших этой точки, тяга к кратому возникает нечасто, и с ней гораздо легче справиться.\n\nБольшая картина\nГод воздержания представляет собой существенные изменения в здоровье, финансах и самоконтроле. Сохранение связи с поддерживающими людьми и службами помогает удерживать достигнутый прогресс.';

  @override
  String get maoiReferenceDay3 =>
      'Прекращение приема ИМАО: этап наибольшего риска\n\nИсточник: Dilsaver (1988), исследование реакций отмены ИМАО.\n\nКритическое предупреждение о безопасности\nИМАО несут самый серьезный риск прекращения приема из любого класса антидепрессантов. Резкое прекращение приема фенелзина и транилципромина может вызвать серьезные реакции, в том числе:\n• Сильная тревога и возбуждение.\n• Напряженная речь и беспокойство.\n• Бессонница или сонливость.\n• Галлюцинации\n• Делирий и параноидальный психоз.\n\nЕсли вы испытываете эти симптомы, немедленно обратитесь за медицинской помощью.\n\nКак работают ИМАО\nИМАО действуют путем необратимого связывания и отключения ферментов моноаминоксидазы (МАО-А и МАО-В). Эти ферменты обычно расщепляют серотонин, норадреналин, дофамин и тирамин в мозге и кишечнике. Поскольку сам фермент разрушается, а не просто блокируется, выздоровление зависит от выработки организмом свежего фермента, а не от того, насколько быстро препарат очищает кровоток.';

  @override
  String get maoiReferenceDay7 =>
      'Через неделю после приема ИМАО: идет синтез фермента МАО\n\nИсточник: «Ингибиторы моноаминоксидазы (ИМАО)» (StatPearls, Книжная полка NCBI).\n\nПроцесс восстановления ферментов\nВ отличие от СИОЗС, СИОЗС и ТЦА, которые обратимо ингибируют обратный химический захват мозга, необратимые ИМАО (фенелзин, транилципромин) навсегда разрушают молекулы фермента моноаминоксидазы. Таким образом, клиническое вымывание определяется тем, насколько быстро организм может синтезировать совершенно новый фермент (около 2 недель), а не тем, насколько быстро сам препарат выводится из кровотока.\n\nЧто происходит через неделю\n• Синтез ферментов МАО-А и МАО-В идет полным ходом, примерно в середине примерно двухнедельного окна ресинтеза.\n• Фаза острого риска, описанная на третий день, проходит, хотя тщательный медицинский контроль остается важным.\n\nДиетические предостережения\nЛечение ИМАО требует диеты с низким содержанием тирамина, поскольку эти ферменты обычно расщепляют тирамин и не позволяют ему вызвать гипертонический криз. Рекомендации заключаются в том, чтобы продолжать соблюдать диетические ограничения в течение этого окна ресинтеза — ваш врач посоветует, когда можно безопасно их ослабить.';

  @override
  String get maoiReferenceDay14 =>
      'Через две недели после приема ИМАО: активность ферментов МАО существенно восстановилась\n\nИсточник: Фриц и др. (1983), Биологическая психиатрия\n\nКритическая двухнедельная отметка\nДве недели — это стандартный клинический срок восстановления фермента МАО после прекращения приема необратимых ИМАО, таких как транилципромин или фенелзин. Изучая транилципромин, это исследование показало, что каталитическая активность МАО-В тромбоцитов, резко снижающаяся в течение дня после приема, возвращается к норме в течение примерно двух недель, поскольку организм заменяет пораженные препаратом тромбоциты свежими, несущими активный фермент, хотя общий уровень белка МАО-В никогда не менялся.\n\nВосстановление ферментов МАО\n• К этому моменту активность тромбоцитов МАО-В существенно восстановилась.\n• Мозговые МАО-А и МАО-В, которые следуют во многом схожему графику ресинтеза, также в значительной степени восстанавливаются.\n• Нормальный метаболизм тирамина восстанавливается — диетические ограничения ИМАО обычно можно ослабить после консультации с лечащим врачом.\n\nХимический баланс мозга возвращается\nПо мере восстановления активности ферментов МАО химические системы мозга, на которые влияют ИМАО, начинают подчиняться естественной регуляции:\n• Серотонин, норадреналин и дофамин больше не повышаются при ингибировании МАО.\n• Сверхчувствительность моноаминовых рецепторов (вызванная хроническим повышением уровня химических веществ в мозге из-за ИМАО) начинает исчезать.\n• Возвращается естественное настроение и регуляция энергии.';

  @override
  String get maoiReferenceDay30 =>
      'Через месяц после приема ИМАО: восстановление баланса химических систем мозга\n\nИсточник: «Ингибиторы моноаминоксидазы (ИМАО)» (StatPearls, Книжная полка NCBI).\n\nМесячная оценка\nЧерез месяц после прекращения приема ИМАО прошло примерно двухнедельное окно ресинтеза фермента МАО, описанное в этом источнике, поэтому к этому моменту активность фермента МАО полностью восстановилась, и химические системы мозга находятся под полностью естественной регуляцией.\n\nЧто восстановилось за месяц\n• Полная ферментативная активность МАО: как МАО-А, так и МАО-В полностью работоспособны.\n• Диетические ограничения устранены: нормальная диета без ограничений по тирамину.\n• Естественная деградация серотонина: восстанавливается нормальный цикл обмена серотонина в мозге.\n• Естественная регуляция катехоламинов: уровни дофамина и норадреналина регулируются естественной активностью МАО.\n\nМеры предосторожности при взаимодействии с лекарственными средствами\nИМАО связаны с опасным для жизни взаимодействием с серотониновыми препаратами. Эти риски взаимодействия исчезли через месяц. Тем не менее, всегда сообщайте своему лечащему врачу и фармацевту о предыдущем использовании ИМАО, когда назначается какое-либо новое лекарство.';

  @override
  String get maoiReferenceDay90 =>
      'Три месяца после ИМАО: отмена уже давно прошла\n\nИсточник: «Синдром отмены антидепрессантов», Therapeutics Letter 112 (2018), Therapeutics Initiative, на книжной полке NCBI.\n\nОтказ от терапии антидепрессантами\nЭтот обзор доказательств рассматривает отмену антидепрессантов как реальный феномен толерантности и зависимости, помещая антидепрессанты «рядом с опиатами и бензодиазепинами». Его подробные доказательства сосредоточены на СИОЗС и СИОЗСН, но реакции отмены распознаются во всех классах антидепрессантов, в том числе после прекращения приема ИМАО. Симптомы «обычно появляются в течение нескольких дней после прекращения приема» и «большинство… проходят в течение 2 недель», хотя некоторые длятся дольше.\n\nЧто означают три месяца\nК трем месяцам острая фаза отмены значительно отстает у подавляющего большинства людей, и организм уже давно приспособился к регулированию моноаминов без ингибирования МАО.\n\nСигнал восстановления при «ресенсибилизации рецепторов»\nУверенные утверждения о том, что рецепторы серотонина, норадреналина и дофамина «повторно чувствительны к трем месяцам», выходят за рамки того, что подтверждают доказательства. На что можно положиться: фаза абстиненции к настоящему времени обычно проходит, и у большинства людей настроение, энергия и эмоциональный диапазон стабилизируются благодаря естественным, саморегулируемым сигналам мозга.\n\nОтмена или рецидив\nВ письме подчеркивается, что отказ от лечения следует отличать от подлинного возвращения основного состояния. Если симптомы сохраняются в течение трех месяцев, проконсультируйтесь с лечащим врачом, а не предполагайте, что это всего лишь синдром отмены.';

  @override
  String get maoiReferenceDay180 =>
      'Шесть месяцев после ИМАО: долгосрочное восстановление\n\nИсточник: Zwiebel & Viguera (2022), Медицинский журнал клиники Кливленда.\n\nШестимесячная оценка\nВ этом обзоре объясняется, что антидепрессанты работают частично за счет того, что со временем вызывают подавление моноаминовых рецепторов, и что это снижение требует недель или месяцев, чтобы обратить вспять после прекращения приема лекарства - более медленный процесс, чем сам примерно двухнедельный ресинтез фермента МАО.\n\nЧто означают шесть месяцев\nШесть месяцев комфортно проходят после периода перестройки рецепторов, продолжающегося несколько недель или месяцев, для подавляющего большинства людей, наряду с активностью ферментов, которая полностью нормализуется в течение первого месяца. Сигнал восстановления: точные сроки полной ресенсибилизации рецепторов серотонина, норадреналина и дофамина в литературе не установлены с повседневной уверенностью — достоверно то, что к шести месяцам большинство людей функционируют на основе естественных, саморегулируемых сигналов мозга.\n\nПримечание о фенэтиламине\nИМАО также ингибируют распад фенилэтиламина (ФЭА), следового амина, связанного с настроением и энергией. Ожидается, что его метаболизм нормализуется вместе с общим восстановлением ферментов МАО, хотя, как и в случае с ресенсибилизацией рецепторов, точные сроки, специфичные для ПЭА, в исследовательской литературе не установлены.';

  @override
  String get maoiReferenceDay365 =>
      'Год спустя после ИМАО: восстановление достигнуто\n\nИсточник: «Ингибиторы моноаминоксидазы (ИМАО)» (StatPearls, Книжная полка NCBI).\n\nОдин год: выдающееся достижение\nЗавершение одного года после прекращения приема ИМАО является действительно важной вехой. ИМАО являются одними из самых требовательных к действию антидепрессантов, поскольку их необратимый механизм действия, строгая диета с низким содержанием тирамина и меры предосторожности при взаимодействии лекарств не похожи ни на один другой класс антидепрессантов.\n\nЧто представляет собой этот год\n• Целый год естественной, саморегулируемой активности моноаминоксидазы, основанной на ресинтезе фермента, который завершается в течение первого месяца.\n• Доказанная способность поддерживать хорошее самочувствие без лекарственного ингибирования МАО.\n• Достаточно длинный послужной список, чтобы быть уверенным, что острые риски прекращения приема на третий день остались позади.\n\nПримечание об ИМАО\nИМАО остаются уникально эффективными при некоторых резистентных к лечению состояниях и атипичной депрессии. Успешное прекращение приема не умаляет их ценности как лекарств — оно демонстрирует способность мозга к восстановлению и способность пациента управлять исключительно сложным медицинским процессом. Одна долгосрочная мера предосторожности: продолжайте рассказывать любому новому врачу или анестезиологу о прошлом использовании ИМАО, поскольку некоторые риски взаимодействия лекарств стоит отмечать на неопределенный срок.';

  @override
  String get marijuanaReferenceDay1 =>
      'Отказ от марихуаны: первый день\n\nИсточник: «Синдром отмены каннабиса: современные представления», Substance Abuse and Rehabilitation (2017), PubMed Central.\n\nСиндром отмены каннабиса реален\nВ рецензируемом обзоре синдром отмены каннабиса описывается как хорошо подтвержденное клиническое состояние. Он часто возникает у людей с зависимостью от каннабиса после прекращения употребления, а его пиковая выраженность может быть сопоставима с синдромом отмены табака.\n\nПочему возникает абстиненция\nТГК действует на эндоканнабиноидную систему, включая рецепторы CB1, участвующие в регуляции настроения, аппетита, сна, памяти и реакции на стресс. При длительном употреблении эта система адаптируется; после прекращения каннабиса ей требуется время для восстановления. В обзоре отмечается, что функция рецепторов CB1 приближается к норме примерно через четыре недели воздержания.\n\nНачало в первый день\nФизические симптомы обычно появляются первыми — в течение 1–3 дней после последнего употребления, тогда как психологические симптомы могут развиваться в течение 2–10 дней. Возможны:\n• Раздражительность, тревога и беспокойство.\n• Трудности со сном.\n• Снижение аппетита.\n• Физическое напряжение, потливость или озноб.\n• Сниженное настроение.\n\nВыраженность\nСиндром отмены каннабиса обычно не опасен для жизни, а симптомы чаще бывают легкими или умеренными. Однако они могут быть достаточно неприятными, чтобы повышать риск возврата к употреблению, поэтому полезно заранее понимать обычные сроки и проявления.';

  @override
  String get marijuanaReferenceDay3 =>
      'График отказа от каннабиса: первые дни\n\nИсточник: «Временной ход симптомов отмены каннабиса DSM-5 у лиц, злоупотребляющих несколькими психоактивными веществами», BMC Psychiatry (2013), на PubMed Central.\n\nИзмеренный ход времени\nВ этом исследовании отслеживались симптомы отмены каннабиса DSM-5 у 90 пациентов в течение четырех недель, что дало одну из самых четких картин того, как симптомы усиливаются и исчезают. Общая тяжесть заболевания следовала кривой: росла, а затем снижалась в течение следующих недель.\n\nЧто достигает пика рано\nНекоторые из наиболее разрушительных для физического здоровья симптомов достигают максимума в течение первых нескольких дней после прекращения приема:\n• Бессонница — пик примерно в первый день.\n• Нервозность — достигает пика примерно на четвертый день.\n• Подавленное настроение и физические симптомы — пик примерно на 5-й день.\n• Беспокойство — достигает пика примерно на 6-й день.\n\nЧто достигнет пика позже\nИсследование показало, что некоторые симптомы появляются и достигают пика позже, чем в первую неделю:\n• Яркие, неприятные сны — пик примерно на 11-й день.\n• Раздражительность и гнев — пик примерно на 14-й день.\n\nСон и конопля\nЗапоздалые, яркие сны отражают отскок быстрого сна: каннабис подавляет быстрый сон во время употребления, а после его остановки мозг осуществляет сверхкомпенсацию. Авторы утверждают, что этот симптом достаточно распространен, чтобы его можно было отнести к формальным критериям отмены.\n\nИтоги третьего дня\nК третьему дню вы находитесь в самом разгаре раннего физического пика — бессонница, нервозность и беспокойство близки к худшему. Последовательная, предсказуемая кривая сама по себе обнадеживает: эти симптомы имеют известное течение и с этого момента они идут на убыль.';

  @override
  String get marijuanaReferenceDay7 =>
      'Одна неделя без каннабиса: через худшее\n\nИсточник: «Синдром отмены каннабиса: современные идеи», «Злоупотребление психоактивными веществами и реабилитация» (2017), PubMed Central.\n\nГде находится одна неделя синдрома\nВ этом обзоре документально подтверждено, что синдром отмены каннабиса обычно длится примерно до трех недель, причем наиболее тревожный период приходится на первую и третью неделю. Через неделю самые ранние физические симптомы — бессонница, потеря аппетита, беспокойство — обычно проходят свой пик и ослабевают.\n\nЧто еще решается\nВ обзоре проводится различие между ранним пиком физических симптомов и более поздним пиком психологических симптомов. За одну неделю:\n• Физический дискомфорт и аппетит значительно улучшаются.\n• У многих по-прежнему нарушается сон, при этом яркие сновидения (отскок быстрого сна) часто достигают своего пика именно сейчас.\n• Раздражительность и настроение могут оставаться повышенными, поскольку они имеют тенденцию достигать пика позже, в течение первых двух недель.\n\nНейробиология восстановления\nВ основе этих изменений в обзоре отмечается, что подавленные рецепторы CB1 возвращаются к нормальному функционированию примерно через четыре недели после воздержания. Прошла неделя, и это перерегулирование уже идет полным ходом — система восстанавливается, хотя некоторые симптомы сохраняются.\n\nВывод\nДостижение одной недели означает, что острый физический пик позади. Остальные симптомы сна и настроения являются частью синдрома с известным конечным течением, который продолжает разрешаться в течение следующих нескольких недель.';

  @override
  String get marijuanaReferenceDay14 =>
      'Две недели без каннабиса: острая абстиненция заканчивается\n\nИсточник: Бадни, AJ и др. (2003) - рецензируемое исследование о времени отмены каннабиса.\n\nРезультаты исследования\nВ этом рецензируемом исследовании систематически документировалось течение симптомов отмены каннабиса у постоянных потребителей. Результаты показали, что острый синдром отмены достигает пика в течение первой недели и в значительной степени проходит в течение 2 недель после прекращения приема большинства симптомов.\n\nЧто проходит через 2 недели\nИсследование показало, что к 14 дням у участников исследования в значительной степени исчезли следующие симптомы:\n• Физический дискомфорт и телесные симптомы\n• Нарушение аппетита\n• Большинство нарушений сна\n• Пиковая раздражительность и тревожность.\n\nЧто может сохраняться более 2 недель\nИсследование также выявило симптомы, которые у некоторых пользователей сохранялись по истечении двух недель:\n• Подавленное настроение\n• Трудности с концентрацией внимания\n• Качество сна (хотя и улучшается).\n\nЗначение 2-недельной отметки\nПрохождение двухнедельной отметки имеет большое значение, поскольку означает, что острый синдром отмены в основном завершен. Проблемы, выходящие за рамки этого этапа, в первую очередь связаны с долгосрочным восстановлением мозга и устранением основных причин употребления каннабиса, а не с острой физиологической реакцией на прекращение употребления каннабиса.';

  @override
  String get marijuanaReferenceDay30 =>
      'Месяц без марихуаны: улучшается функция памяти\n\nИсточник: Поуп и др. (2001), Архив общей психиатрии.\n\nКаннабис и память: проблема\nВ этом исследовании мы следили за постоянными и длительными потребителями каннабиса в течение 28 дней подтвержденного воздержания и сравнивали результаты их тестов на мышление и память с теми, кто употреблял марихуану регулярно и не употреблял ее. В начале воздержания, а также в дни 1 и 7, активные потребители показали худшие результаты, чем контрольная группа, при запоминании списков слов - дефицит, который отслеживался по уровням метаболита ТГК в моче, что отражает недавнее воздействие препарата, а не употребление в течение всей жизни.\n\nХорошие новости: восстановление к 28-му дню\nК 28-му дню активные пользователи, легкие пользователи и непользователи показали практически одинаковые результаты в тестах на мышление и память. На тот момент также не было значимой связи между общим употреблением каннабиса в течение жизни и результатами тестов.\n\nЧто это значит через 30 дней\n• Вербальное обучение и запоминание вернулись на уровень контрольной группы.\n• Остаточный дефицит, наблюдавшийся в первую неделю, исчез.\n• Оставшийся ранее дефицит был связан с недавним воздействием, а не с необратимым ущербом.\n\nЧто показывают доказательства\nК 28-му дню согласно полному набору тестов на мышление и память, активные пользователи были практически неотличимы от тех, кто регулярно употреблял и не употреблял наркотики. Дефицит вербального обучения и запоминания, наблюдаемый в первую неделю, восстановился до уровня контрольной группы.';

  @override
  String get marijuanaReferenceDay60 =>
      'Два месяца без каннабиса: усиливается концентрация\n\nИсточник: Ротен и др. (2015), Аддиктивное поведение\n\nВопрос исследования\nВ этом исследовании по отказу от употребления марихуаны среди молодежи отслеживались результаты тестов памяти и мышления, а также анализы мочи в течение примерно двух месяцев, сравнивая продолжающихся потребителей марихуаны с людьми, которые недавно прекратили употребление марихуаны или воздерживались от неё.\n\nКлючевые выводы\nПостоянное воздержание было связано со значительным улучшением:\n• Комплексный показатель памяти\n• В частности, вербальная память — наиболее затронутая область.\n• Скорость движения и реакции.\n\nЧерез два месяца\nПримерно за восемь недель постоянного воздержания показатели памяти, движений и скорости реакции заметно поднялись по сравнению с теми, которые были во время активного употребления, близко отслеживая подтвержденное неиспользование, а не время простоя.\n\nЧто показывает исследование\nУ подростков и молодых людей с зависимостью от каннабиса последовательное воздержание привело к значительному улучшению общей памяти, вербальной памяти, а также скорости движений и реакции в течение примерно двухмесячного периода лечения.';

  @override
  String get marijuanaReferenceDay90 =>
      'Три месяца без каннабиса: стабильность настроения возвращается\n\nИсточник: Коннор и др. (2022), Зависимость — клинический обзор отмены каннабиса.\n\nКак на самом деле проходила абстиненция\nВ этом обзоре описаны симптомы отмены каннабиса, которые обычно начинаются через 24–48 часов после прекращения употребления и достигают пика примерно на 2–6 день. Гнев, агрессия и депрессивное настроение могут появиться уже через неделю, но обычно достигают пика примерно через две недели воздержания; В частности, нарушение сна может сохраняться дольше, чем другие симптомы.\n\nЧто означают три месяца\nЧерез три месяца вы выйдете далеко за пределы документально подтвержденного курса абстиненции: симптомы обычно начинаются в течение 24–48 часов, достигают пика примерно на 2–6 день, а еще более медленные симптомы настроения и сна достигают пика в течение следующих недель. Девяносто дней дают людям, страдающим абстинентным настроением и эффектами сна, месяцы на то, чтобы прийти в норму.\n\nПримечание об эндоканнабиноидной системе\nИсследования по отмене каннабиса также показывают, что пониженная регуляция рецепторов CB1 возвращается к нормальному функционированию примерно через четыре недели после воздержания. Через 90 дней вы уже далеко за пределами этого окна восстановления рецепторов.\n\nЗаглядывая в будущее\nВ обзоре также обсуждаются прогнозы после детоксикации и профилактика рецидивов, подчеркивая, что постоянная поддержка и стратегии преодоления последствий имеют значение далеко за пределами окна острой абстиненции.';

  @override
  String get marijuanaReferenceDay180 =>
      'Шесть месяцев без каннабиса: планирование и принятие решений\n\nИсточник: Crean, Crane & Mason (2011), Журнал наркозависимости.\n\nПланирование и принятие решений после употребления каннабиса\nВ этом обзоре изучались внимание, принятие решений, самоконтроль, рабочая память и беглость речи с первых часов после употребления до длительного воздержания. К шести месяцам вы уже далеко преодолеете краткосрочные последствия и глубоко войдете в период восстановления.\n\nЧто обнаружило исследование\nНекоторые проблемы, связанные с интенсивным употреблением, исчезают при длительном воздержании, при этом некоторые исследования показывают выздоровление через 28 дней. К областям, которые восстанавливаются медленнее всего после интенсивного употребления с ранним началом, относятся:\n• Принятие решений и принятие рисков — специально отмечены как области, в которых дефицит может сохраняться в течение длительного времени у тяжелых и хронических потребителей.\n• Абстрактное мышление и речевые навыки — особенно нарушены у взрослых, которые начали употреблять наркотики до 17 лет.\n\nРаннее восстановление\nШесть месяцев — это далеко за рамки краткосрочных последствий, описанных в этом обзоре. Планирование, принятие решений и рассуждение продолжают улучшаться по мере длительного воздержания, что делает длительное воздержание самым надежным путем к дальнейшему выздоровлению.\n\nБолее широкая картина\nДля более легкого использования во взрослом возрасте перспективы более благоприятны: многие люди в возрасте шести месяцев сообщают о более ясном мышлении, более устойчивом принятии решений и более сильном чувстве самостоятельности. Наибольшие преимущества дает сохранение воздержания, особенно после интенсивного или раннего начала употребления.';

  @override
  String get marijuanaReferenceDay365 =>
      'Год без каннабиса: восстанавливается структура мозга\n\nИсточник: «Вред, защита и восстановление гиппокампа после регулярного употребления каннабиса», Трансляционная психиатрия (2016), на PubMed Central.\n\nСтруктурные изменения от каннабиса\nВ ходе этого исследования по сканированию мозга исследовался гиппокамп, центральная область мозга, отвечающая за память, у нынешних пользователей, бывших пользователей и непользователей. У нынешних пользователей, не подвергавшихся воздействию КБД, гиппокамп был примерно на 11% меньше, а маркер здоровья клеток головного мозга примерно на 15% ниже, чем у контрольной группы.\n\nКлючевой вывод: выздоровление при воздержании\nАнализ аппроксимации кривой подтвердил модель «защиты и восстановления». Важно отметить, что бывшие пользователи, воздерживавшиеся от каннабиса в среднем около 29 месяцев, не отличались от тех, кто не использовал средства контроля по каким-либо показателям добросовестности. Авторы приходят к выводу, что вред, нанесенный ТГК области памяти, «может быть восстановлен при длительном воздержании».\n\nВосстановление мозга в течение года и более\nЧерез год без каннабиса система памяти мозга начинает восстанавливаться: размер гиппокампа и здоровье клеток мозга возвращаются к норме, поддерживая память и эмоциональный контроль.\n\nСигнал восстановления\nБывшие потребители, воздерживавшиеся от каннабиса в течение примерно 29 месяцев, соответствовали показателям здоровья гиппокампа, которые не употребляли наркотики. Через год система памяти уже движется по документированному пути восстановления к нормальной жизни.';

  @override
  String get mdmaReferenceDay1 =>
      'После МДМА: спад\n\nИсточник: Мейер (2013), «3,4-Метилендиоксиметамфетамин (МДМА): текущие перспективы», Злоупотребление психоактивными веществами и реабилитация.\n\nПочему вы чувствуете себя подавленным\nМДМА действует за счет значительного выброса серотонина (с некоторым количеством дофамина). После этого мозг временно лишается серотонина. В этом обзоре описывается снижение настроения — так называемая «хандра середины недели», которую исследователи наблюдали как у новичков, так и у опытных пользователей через 2–5 дней после использования.\n\nЧто помогает\n• Гидратация и питательное питание.\n• Сон\n• Терпение: провал — это истощение, а не постоянное состояние.\n\nСпад после однократного употребления отличается от синдрома отмены, связанного с зависимостью, который в том же обзоре описывается как связанный с тягой, но не с выраженными физическими симптомами.';

  @override
  String get mdmaReferenceDay3 =>
      'Через несколько дней после МДМА\n\nИсточник: Мейер (2013), «3,4-Метилендиоксиметамфетамин (МДМА): текущие перспективы», Злоупотребление психоактивными веществами и реабилитация.\n\nСпад настроения в середине недели\nПримерно это окно описывает этот обзор, когда обсуждается «хандра в середине недели» — падение настроения, измеряемое через 2–5 дней после использования как у новичков, так и у опытных пользователей, связанное с кратковременным истощением серотонина, а не с долгосрочными изменениями.\n\nЧто улучшается\n• Настроение сейчас обычно поднимается с самой низкой точки.\n• Возврат энергии\n• Сон начинает нормализоваться';

  @override
  String get mdmaReferenceDay7 =>
      'Через неделю после приема МДМА\n\nИсточник: Мейер (2013), «3,4-Метилендиоксиметамфетамин (МДМА): текущие перспективы», Злоупотребление психоактивными веществами и реабилитация.\n\nПосле спада настроения в середине недели\nДля большинства людей прошла неделя после периода в 2–5 дней, который в этом обзоре ассоциируется с острым ухудшением состояния, поэтому настроение должно вернуться в норму. В обзоре отмечается, что у людей, которые употребляют интенсивно или неоднократно, тяга к МДМА может сохраняться как часть модели зависимости, хотя в нем не описывается это как выраженный физический синдром абстиненции.\n\nКогда обращаться за помощью\nЕсли плохое настроение, тревога или проблемы со сном сохраняются в течение недели, это может быть не просто ухудшением состояния — стоит обратиться к профессионалу.';

  @override
  String get mdmaReferenceDay14 =>
      'Две недели без МДМА\n\nИсточник: Мейер (2013), «3,4-Метилендиоксиметамфетамин (МДМА): текущие перспективы», Злоупотребление психоактивными веществами и реабилитация.\n\nГрафик восстановления\nДля одноразового снижения дозы две недели значительно превышают период от 2 до 5 дней, описанный в этом обзоре, поэтому настроение, сон и концентрация должны быть стабильными. После более интенсивного или многократного употребления, восстановление продолжается и после снижения, а визуализирующие исследования при воздержании показывают, что способность к переработке серотонина увеличивается при длительном воздержании.\n\nЧто это значит для вас\nЕсли вы использовали его нерегулярно, вы, вероятно, пережили худшее. Если это было часто или тяжело, наберитесь терпения — полное восстановление передачи сигналов серотонина — это более длительный процесс, чем две недели, описанный в следующих этапах.';

  @override
  String get mdmaReferenceDay30 =>
      'Месяц без МДМА\n\nИсточник: «Наличие транспортера серотонина, нейрокогнитивные функции и их взаимосвязь у воздерживающихся потребителей МДМА», на PubMed.\n\nЧто означает один месяц\nОстрый спад и абстиненция уже позади, а настроение, мышление и память стали более устойчивыми. Визуализирующие исследования показывают, что МДМА снижает способность мозга перерабатывать серотонин, и что эта способность восстанавливается при длительном воздержании.\n\nСигнал восстановления\nТо же исследование показывает, что способность к переработке серотонина восстанавливается при длительном воздержании. В первую очередь улучшаются настроение и функция серотонина, в то время как память продолжает восстанавливаться самостоятельно — длительное воздержание поддерживает и то, и другое.';

  @override
  String get mdmaReferenceDay90 =>
      'Три месяца без МДМА\n\nИсточник: «Наличие транспортера серотонина, нейрокогнитивные функции и их взаимосвязь у воздерживающихся потребителей МДМА», на PubMed.\n\nПродолжение восстановления\nПри длительном воздержании серотониновая система мозга продолжает восстанавливаться, особенно в более глубоких областях мозга. К этому моменту настроение и сон обычно стабильны.\n\nСигнал восстановления\nУстойчивое воздержание способствует продолжению восстановления транспортеров серотонина во всех областях мозга, в то время как настроение и сон остаются стабильными, а восстановление мышления и памяти продолжается.';

  @override
  String get mdmaReferenceDay365 =>
      'Год без МДМА\n\nИсточник: «Наличие транспортера серотонина, нейрокогнитивные функции и их взаимосвязь у воздерживающихся потребителей МДМА», на PubMed.\n\nГод спустя\nЗа год воздержания обработка серотонина в мозге существенно восстановилась, а настроение стабилизировалось.\n\nСигнал восстановления\nПолный год воздержания дает серотониновой системе длительное окно восстановления. Визуализирующие исследования показывают, что способность к переработке серотонина увеличивается при воздержании, что делает значительное восстановление серотонина наиболее четким биологическим сигналом на этом этапе.';

  @override
  String get methReferenceDay1 =>
      'Отказ от метамфетамина: первые 24 часа\n\nИсточник: МакГрегор и др., «Природа, продолжительность и тяжесть синдрома отмены метамфетамина», Наркомания (2005), на PubMed.\n\nАвария\nМетамфетамин вызывает большое выделение дофамина; когда использование прекращается, система остается истощенной. В этом исследовании ежедневно отслеживались симптомы абстиненции в течение первых трех недель воздержания и было обнаружено, что общая тяжесть была максимальной в течение 24 часов после последнего употребления — «крах», резкий переход от крайней стимуляции к физическому и психологическому истощению.\n\nСимптомы первого дня\nИсследование зафиксировало особенности синдрома отмены, которые сейчас наиболее выражены:\n• Сильная усталость и повышенный сон (гиперсомния).\n• Повышенный аппетит (мет сильно подавляет аппетит).\n• Подавленное настроение и потеря удовольствия.\n• Сильная тяга к кратому.\n• Тревога и раздражительность\n\nФизическая безопасность\nСиндром отмены метамфетамина сам по себе, как правило, не опасен для жизни, но симптомы, связанные с депрессией, измеренные в этом исследовании, могут быть серьезными на ранних этапах и могут включать суицидальные мысли. Медицинский контроль настоятельно рекомендуется, особенно для тяжелых пользователей.\n\nОн начинает подниматься\nОбнадеживающий вывод этого исследования: степень тяжести наиболее высока в самом начале, а затем снижается. После этого 24-часового пика симптомы постепенно уменьшаются в последующие дни — худший момент — это начало.';

  @override
  String get methReferenceDay3 =>
      'Отказ от метамфетамина: день третий — все еще в острой фазе\n\nИсточник: МакГрегор и др., «Природа, продолжительность и тяжесть синдрома отмены метамфетамина», Наркомания (2005), на PubMed.\n\nСпускаемся с вершины\nЭто исследование показало, что общая тяжесть абстиненции достигает пика в течение первых 24 часов, а затем снижается примерно линейно в течение острой фазы (около 7–10 дней). К третьему дню вы прошли самую высокую точку, но все еще твердо находитесь в острой фазе — симптомы остаются заметными, даже несмотря на тенденцию к снижению.\n\nСимптомы третьего дня\nОсобенности, выявленные в ходе исследования, которые все еще важны сейчас:\n• Депрессия и потеря удовольствия.\n• Сильная тяга к кратому.\n• Трудности с концентрацией внимания и ясным мышлением.\n• Нарушенный сон — бессонница, чередующаяся с гиперсомнией.\n• Продолжающаяся усталость\n\nПочему так кажется\nИнтенсивность отмены метамфетамина отражает масштаб истощения дофамина, который она вызывает. Симптомы, связанные с депрессией, которые измерялись в ходе исследования, наиболее очевидны в эти первые дни, но, что важно, исследование показало, что общая тяжесть абстиненции «снижается до почти контрольного уровня к концу первой недели воздержания».\n\nЭто пройдет\nСамый трудный период — первые несколько дней, и с этого момента данные показывают неуклонное снижение. Понимание этого состояния как временного, а также мозга и нервов, а не постоянного состояния, помогает пережить его.';

  @override
  String get methReferenceDay7 =>
      'Одна неделя без метамфетамина: острая фаза заканчивается\n\nИсточник: МакГрегор и др., «Природа, продолжительность и тяжесть синдрома отмены метамфетамина», Наркомания (2005), на PubMed.\n\nКонец острой фазы\nЭто один из самых обнадеживающих результатов исследования. В исследовании сообщалось, что общая тяжесть абстиненции, включая отслеживаемые симптомы, связанные с депрессией, «снизилась до уровня, близкого к контрольному, к концу первой недели воздержания», что ознаменовало конец острой фазы. Самая крутая часть подъема позади.\n\nДве фазы абстиненции\nАвторы описали отмену метамфетамина как проявление:\n• Острая фаза, продолжающаяся около 7–10 дней, во время которой тяжесть симптомов неуклонно снижается по сравнению с ранним пиком.\n• Подострая фаза, продолжающаяся как минимум еще две недели, с более легкими и затяжными симптомами.\n\nЧто осталось на 7-й день\nВступая в подострую фазу, доминирующими проблемами теперь являются психологические, а не острые проблемы:\n• Плохое настроение, хотя с первых дней оно значительно улучшилось.\n• Тяга, особенно в ответ на сигналы\n• Концентрация и память все еще восстанавливаются.\n• Сон все еще налаживается.\n\nФизическое восстановление продолжается\nПосле окончания острой фазы аппетит вернулся, и энергия постепенно нарастает, поскольку организм восстанавливается после воздействия метамфетамина на сон, питание и сердечно-сосудистую систему.';

  @override
  String get methReferenceDay30 =>
      'Один месяц без метамфетамина: настроение стабилизируется, тяга сохраняется\n\nИсточник: Зорик и др., «Симптомы абстиненции у абстинентных субъектов, зависимых от метамфетамина», Наркомания (2010), на PubMed Central.\n\nОтслеживание первых пяти недель\nВ этом исследовании участвовали участники, зависимые от метамфетамина, которые воздерживались от употребления метамфетамина на срок до пяти недель, и сравнивались их со здоровыми людьми из контрольной группы, что дает необычайно ясную картину того, где находится отметка в один месяц.\n\nЧто улучшилось за месяц\n• Депрессивные симптомы «существенно снизились в течение первых двух недель воздержания до стабильно низкого уровня» и к концу четырех недель приближались к уровню здорового контроля, хотя еще и не были статистически соответствующими (разрыв сузился до пограничной, незначительной тенденции).\n• Симптомы психиатрического и психотического типа достигли низкого исходного уровня к концу второй недели.\nТаким образом, через 30 дней тяжелая депрессия, вызванная преждевременной отменой, в значительной степени прошла — это настоящее, измеренное улучшение.\n\nЧто еще сохраняется\nИсследование показало, что один симптом длится дольше остальных: тяга к метамфетамину «все еще сохранялась на сниженном уровне в течение 5 недель воздержания». Тяга к метамфетамину слабее, чем в первую неделю, но не прошла, поэтому месяц все еще остается периодом высокого риска, и постоянная поддержка имеет значение.\n\nВывод\nК месяцу механизм настроения мозга достаточно восстанавливается, и повседневное самочувствие становится намного лучше, чем при ранней абстиненции, хотя сохраняющаяся тяга к метамфетамину является нормальной частью этой стадии, а не признаком неудачи.';

  @override
  String get methReferenceDay90 =>
      'Три месяца без метамфетамина: исцеление началось — наберитесь терпения\n\nИсточник: Волков и др., «Потеря транспортеров дофамина у лиц, злоупотребляющих метамфетамином, восстанавливается при длительном воздержании», Journal of Neuroscience (2001).\n\nОб этом исследовании\nВ этом знаменательном исследовании по сканированию мозга дважды наблюдали за потребителями метамфетамина — примерно через три месяца и снова примерно через 14 месяцев — чтобы увидеть, как восстанавливается дофаминовая система.\n\nЧто означают три месяца\nЧерез три месяца период ранней отмены уже давно закончился и происходит более глубокое восстановление дофамина. Позже то же исследование показало, что количество белков, которые перерабатывают дофамин в зонах вознаграждения и движения мозга, выросло примерно на 16–19% после 12–17 месяцев отсутствия метамфетамина.\n\nЧто это значит для вас\nК 90 дням острая абстиненция уже далеко позади, настроение и сон улучшаются, а участие в терапии становится гораздо более продуктивным. Но более глубокое восстановление дофамина — это более длительный проект, который развернется в следующем году. Если через три месяца мотивация и удовольствие по-прежнему ощущаются приглушенными, это ожидаемо, а не признак неудачи — траектория в этом исследовании явно идет вверх.\n\nПочему стоит подождать\nТо же исследование показало, что воздержание является движущей силой выздоровления: чем дольше воздержание, тем выше измеренное восстановление DAT. Три месяца — это фундамент; улучшения продолжаются.';

  @override
  String get methReferenceDay180 =>
      'Шесть месяцев без метамфетамина: сердце может восстановиться\n\nИсточник: «Прекращение употребления метамфетамина может обратить вспять связанное с ним повреждение сердца», Американский колледж кардиологии (2017), отчет об исследовании в JACC: Сердечная недостаточность.\n\nМет и сердце\nМетамфетамин – один из наиболее кардиотоксичных рекреационных наркотиков. Это может привести к тяжелой гипертонии и аритмиям, а со временем – к кардиомиопатии, связанной с метамфетамином, — ослаблению сердечной мышцы, которое приводит к сердечной недостаточности.\n\nЧто обнаружило исследование\nACC сообщил о пациентах с мета-ассоциированной кардиомиопатией (все со значительным снижением сердечной функции). Главный и обнадеживающий вывод: прекращение употребления метамфетамина «может обратить вспять повреждение, которое препарат наносит сердцу, и улучшить сердечную функцию». Пациенты, которые прекратили употребление, имели заметно лучшие результаты, чем те, кто продолжал употреблять, и авторы подчеркнули, что раннее выявление заболевания «может предотвратить дальнейшее ухудшение кардиомиопатии».\n\nПочему шесть месяцев имеют значение\nКаждый месяц воздержания снимает продолжающуюся токсическую нагрузку на сердце и дает мышцам шанс восстановиться. Через шесть месяцев вы дали своей сердечно-сосудистой системе существенный и устойчивый отдых от этого повреждения — именно то состояние, при котором в этом исследовании наблюдалось улучшение.\n\nСигнал восстановления\nПодтвержденный фактами результат убедительный: прекращение приема метамфетамина может обратить вспять повреждение сердца, связанное с метамфетамином, и улучшить функцию сердца. Шесть месяцев без повторного воздействия стимуляторов дают сердцу существенный период восстановления.';

  @override
  String get methReferenceDay365 =>
      'Один год без метамфетамина: измеримое восстановление мозга\n\nИсточник: Ван и др., «Частичное восстановление метаболизма мозга у лиц, злоупотребляющих метамфетамином, после длительного воздержания», Американский журнал психиатрии (2004), на PubMed.\n\nЧто показывает изображение\nВ ходе этого исследования по сканированию мозга проверялись потребители метамфетамина на ранних стадиях воздержания, а затем снова через 12–17 месяцев. Было обнаружено подлинное восстановление мозга, причем некоторые области восстанавливались быстрее, чем другие.\n\nХорошие новости: восстановление глубокого мозга и мышления\nТаламус, глубокий мозговой релейный центр, начал более нормально использовать энергию при длительном воздержании. Это восстановление сопровождалось улучшением движений и вербальной памяти, поэтому улучшение сканирования мозга отразилось на реальном мышлении и памяти.\n\nСхемы вознаграждения восстанавливаются медленнее\nЧерез 12–17 месяцев глубокий ретрансляционный центр мозга значительно восстановился, и это улучшение отразилось на улучшении движений и вербальной памяти. Системы вознаграждения и мотивации также продолжали укрепляться, что сделало годичную картину значительным восстановлением мышления и памяти.\n\nЧто это значит через год\nЧерез год ожидайте, что мозг будет думать и запоминать гораздо лучше, чем на раннем этапе выздоровления, — четкое, измеримое исцеление. Но если мотивация или способность чувствовать удовольствие время от времени все еще отстают, это согласуется с наукой, а не является личным недостатком: это исследование показало, что эти схемы вознаграждения могут восстанавливаться медленнее, а некоторые дефициты все еще сохраняются более чем через год.';

  @override
  String get methReferenceDay420 =>
      '14 месяцев без метамфетамина: уровень дофамина восстанавливается\n\nИсточник: Волков и др., «Потеря транспортеров дофамина у лиц, злоупотребляющих метамфетамином, восстанавливается при длительном воздержании», Journal of Neuroscience (2001).\n\nГлавный вывод\nВ ходе этого знакового исследования по сканированию мозга проверялись потребители метамфетамина на ранних этапах воздержания, а затем снова примерно через 12–17 месяцев. Количество белков, перерабатывающих дофамин, выросло примерно на 16–19% в областях мозга, отвечающих за вознаграждение и движение, и достигло уровней, которые больше существенно не отличались от здорового контроля. Более длительное воздержание означало большее выздоровление.\n\nПочему DAT имеет значение\nЭти белки перерабатывают дофамин после его высвобождения. Мет истощает их, в результате чего дофаминовая система плохо регулируется. Их восстановление примерно через 14 месяцев является подлинным, измеримым признаком исцеления.\n\nСигнал восстановления\nЧерез 12–17 месяцев количество белков, перерабатывающих дофамин в зонах вознаграждения и движения, выросло примерно на 16–19% и достигло контрольного уровня для здоровых людей. Дофаминовая система заметно вернулась к норме, а мышление, память и движение продолжают улучшаться.\n\nЧто это значит в 14 месяцев\nАппаратное обеспечение дофаминовой системы заметно восстанавливается до нормального уровня — это настоящий повод для оптимизма. Но полное функциональное восстановление (память, мотивация, мелкая моторика) может отставать от визуализации и продолжает улучшаться при продолжающемся воздержании.';

  @override
  String get methReferenceDay730 =>
      'Два года без метамфетамина: мышление и настроение продолжают улучшаться\n\nИсточник: Юдичелло и др., «Долгосрочное улучшение нейрокогнитивного функционирования и аффективный стресс среди потребителей метамфетамина, достигших стабильного воздержания», Журнал клинической и экспериментальной нейропсихологии (2010), на PubMed Central.\n\nВосстановление, которое продолжается уже год\nВ этом исследовании наблюдали за потребителями метамфетамина в течение примерно 13 месяцев и сравнивали стабильно воздерживающихся от употребления метамфетамина с продолжающими употреблять метамфетамин и здоровыми людьми из контрольной группы. Стабильное воздержание улучшило общее мышление и уменьшило эмоциональный стресс, причем улучшения продолжались и в течение года.\n\nЧто улучшается\n• В целом мышление у трезвенников сравнялось со здоровым контролем, в то время как продолжающие употреблять алкоголь оставались значительно нарушенными.\n• Наибольший прирост наблюдался в скорости обработки информации и двигательных способностях, особенно у тех, у кого на начальном этапе наблюдались наиболее слабые нарушения.\n• Настроение заметно улучшилось: только у трезвенников наблюдалось значительное улучшение депрессии и общего настроения.\n\nСигнал восстановления\nСтабильно воздерживающиеся от употребления алкоголя догнали здоровый контроль над общим мышлением и сообщили о меньшем эмоциональном стрессе. Вербальное обучение, рабочая память, планирование и сосредоточенность могут продолжать улучшаться после первого года, поэтому тенденция восстановления сохраняется и на второй год.\n\nДва года спустя\nИдея, основанная на фактических данных: устойчивое воздержание продолжает окупаться и после первого года — более острое мышление, лучшее настроение и постоянное улучшение функций — даже если для восстановления некоторых областей требуется больше времени.';

  @override
  String get nitrousOxideReferenceDay1 =>
      'День первый: Газ закончился, но смотрите B12\n\nИсточник: Кнуф и Маани, «Закись азота», StatPearls (книжная полка NCBI).\n\nКак быстро он очищается\nЗакись азота начинает действовать быстро — от 2 до 5 минут — и выводится из организма так же быстро, как только вы перестаете вдыхать ее. К настоящему моменту в вашей системе не осталось газа.\n\nРеальный риск – это не газ\nПосле остановки важно то, что, возможно, уже произошло при повторном воздействии. Закись азота инактивирует метионинсинтазу, фермент, который зависит от витамина B12. StatPearls отмечает, что многократное воздействие — профессиональное или рекреационное — может привести к мегалобластной анемии, дисфункции головного мозга и нервов, а в редких случаях — к дегенерации спинного мозга.\n\nЕсли вы употребляли много или часто\nНет документально подтвержденных фактов, что закись азота вызывает физический синдром отмены, как это происходит с опиоидами или алкоголем, поэтому первый день не связан с тем, что ваше тело требует наркотика. Речь идет о том, чтобы начать обращать внимание на симптомы, связанные с B12, которые рассматриваются в следующих нескольких этапах, и проверяться, если таковые появляются.';

  @override
  String get nitrousOxideReferenceDay3 =>
      '72 часа: никакой физической абстиненции, но следите за нервными симптомами\n\nИсточник: Кнуф и Маани, StatPearls; Тикария и др. (2026), Куреус\n\nВ отличие от опиоидов или алкоголя, закись азота не вызывает физического синдрома отмены. Побуждения на этом этапе — это привычка и тяга, а не тело, требующее препарата для функционирования.\n\nСледите за этим\nСистематический обзор 1809 случаев закиси азота в рекреационных целях (Tikaria et al., 2026) показал, что симптомы со стороны головного мозга и нервов — особенно покалывание или онемение (парестезия) — являются наиболее частым признаком вреда, связанного с B12, часто появляющимся даже тогда, когда стандартные анализы крови выглядели нормальными. Сообщалось также о проблемах с походкой и слабости.\n\nЕсли вы заметили что-либо из этого\nОбратитесь за медицинской экспертизой. В том же обзоре было обнаружено, что стандартные анализы крови (гемоглобин, сыворотка B12) не учитывают значительную долю больных пациентов — тесты на метилмалоновую кислоту (ММА) и гомоцистеин более чувствительны, и их следует запрашивать специально, если вы сообщаете об употреблении закиси азота.';

  @override
  String get nitrousOxideReferenceDay7 =>
      'Одна неделя: пройдите тестирование, если вы много употребляли\n\nИсточник: Тикария и др. (2026), «Токсическое наследие использования закиси азота в рекреационных целях», Cureus\n\nЧто показывают доказательства\nЭтот систематический обзор показал, что дефицит витамина B12 из-за закиси азота часто является «функциональным» — сывороточный B12 выглядел нормальным примерно у половины больных пациентов, даже если у них было реальное повреждение головного мозга и нервов. Гомоцистеин и ММА были аномальными гораздо чаще (84% и 73% обследованных пациентов соответственно) и являются более надежными маркерами.\n\nЧто делать\nЕсли вы употребляли интенсивно или часто, одна неделя перерыва — разумное время, чтобы обратиться к врачу и попросить конкретно проверить гомоцистеин и ММА, а не только стандартный уровень B12, особенно если у вас есть покалывание, онемение, проблемы с равновесием или необъяснимая слабость.\n\nВосстановление мозга является обычным явлением после прекращения приема азота и лечения витамином B12: в крупных клинических исследованиях сообщается о частичном или полном улучшении у большинства наблюдаемых пациентов, при этом восстановление продолжается в течение первых месяцев после лечения.';

  @override
  String get nitrousOxideReferenceDay14 =>
      'Две недели: симптомы со стороны мозга и нервов требуют дальнейшего наблюдения\n\nИсточник: Тикария и др. (2026), Куреус; Кнуф и Маани, StatPearls\n\nЧто сообщалось\nОтчеты о случаях заболевания и серии исследований, рассмотренные Tikaria et al. описывают повреждение нервов, связанное с закисью азота, проявляющееся потерей чувствительности, атаксией походки, а иногда и слабостью, влияющей на ходьбу - результаты, которые могут напоминать другие состояния мозга и нервов и иногда пропускаются, если об использовании закиси азота не сообщается клиницисту.\n\nСигнал восстановления на временных графиках\nНи один из источников не сообщает, сколько времени обычно занимает восстановление после прекращения употребления и устранения любого дефицита. В отчетах о случаях описывается широкий спектр исходов — от полного выздоровления до стойкого дефицита — в значительной степени в зависимости от того, насколько серьезный ущерб был нанесен до постановки диагноза. Во всей литературе сходным является то, что более раннее начало лечения приводит к лучшим результатам.\n\nЕсли вас не проверили\nДве недели перерыва по-прежнему являются хорошим временем для сдачи анализа крови, даже без симптомов, особенно на гомоцистеин и ММА, а не только на сывороточный B12.';

  @override
  String get nitrousOxideReferenceDay30 =>
      'Один месяц: привычка и тяга, а не физическая зависимость\n\nИсточник: Кнуф и Маани, «Закись азота», StatPearls (книжная полка NCBI).\n\nГде ты стоишь\nStatPearls не описывает закись азота как вызывающую синдром физической зависимости, поэтому месячный перерыв означает, что любые сохраняющиеся позывы связаны с привычкой, социальным контекстом или скукой, а не с тем, что организм все еще приспосабливается к отсутствию препарата.\n\nВопрос B12\nЕсли вы проходили тестирование и лечились от дефицита B12, один месяц — это разумный срок для вашего врача, чтобы проверить, отреагировал ли ваш уровень и какие-либо симптомы. Если вы не проходили тестирование и не подвергались интенсивному использованию, спросить все равно стоит.\n\nЧто защищено\nКаждый месяц, который вы не принимаете, — это месяц, когда вы не увеличиваете существующую инактивацию метионинсинтазы или связанный с ней риск для мозга и нервов.';

  @override
  String get nitrousOxideReferenceDay90 =>
      'Три месяца: время перепроверить, если вы этого еще не сделали\n\nИсточник: Тикария и др. (2026), «Токсическое наследие использования закиси азота в рекреационных целях», Cureus\n\nЧто мы знаем и чего не знаем\nЭта исследовательская база построена на отчетах о случаях заболевания и сериях случаев, а не на контролируемых исследованиях выздоровления, поэтому не существует надежных опубликованных графиков того, как симптомы исчезнут конкретно за три месяца. Фактические данные показывают, что результаты сильно различаются: некоторые пациенты с легким, рано выявленным дефицитом полностью выздоравливают, в то время как у пациентов с поздней диагностикой или более тяжелым повреждением нервов могут наблюдаться стойкие нарушения.\n\nДейственная часть\nЕсли у вас были какие-либо симптомы со стороны мозга и нервов и вы не проходили контрольный анализ крови или осмотр специалиста, разумным решением будет трехмесячный перерыв. Если вы лечились и вам стало лучше, сейчас самое время подтвердить, что тенденция сохраняется, у вашего врача.\n\nСамое важное – оставаться в стороне\nОбзор единодушен в одном: продолжающееся воздействие продолжает инактивировать B12 и увеличивает риск. Неиспользование — самый важный фактор в вашу пользу.';

  @override
  String get nitrousOxideReferenceDay365 =>
      'Один год: лучшая защита — длительное воздержание\n\nИсточник: Кнуф и Маани, StatPearls; Тикария и др. (2026), Куреус\n\nГде на самом деле находятся доказательства\nНи один из источников не обещает конкретных сроков восстановления, и в этом стоит быть честным: литература о закиси азота и дефиците B12 почти полностью построена на отчетах об отдельных случаях, а не на долгосрочных последующих исследованиях. Что хорошо известно, так это механизм: закись азота инактивирует витамин B12 каждый раз, когда он используется, и прекращение приема полностью устраняет этот продолжающийся вред.\n\nЕсли у вас были симптомы, связанные с дефицитом\nВ отчетах о случаях описывается широкий спектр исходов: от полного выздоровления до стойких нервных симптомов, что во многом зависит от того, насколько серьезно произошло повреждение и как рано его начали лечить. Если через год вы все еще испытываете симптомы, это повод продолжать работу с неврологом, а не признак того, что ничего нельзя сделать — восстановление нервов может продолжаться в течение длительного периода.\n\nЧто наверняка\nГод без закиси азота — это год без дальнейшей инактивации метионинсинтазы. Это единственная гарантия, которую поддерживают оба источника.';

  @override
  String get opioidReferenceDay1 =>
      'Отмена опиоидов: день первый\n\nИсточник: «Клинические рекомендации по лечению абстиненции и лечению наркотической зависимости в закрытых учреждениях», Всемирная организация здравоохранения (2009), на книжной полке NCBI.\n\n⚠ Примечание по безопасности\nОтмена опиоидов редко приводит к летальному исходу у здоровых людей, но она вызывает тяжелые физические страдания и сопряжена с высоким риском рецидива. Рецидив после периода воздержания особенно опасен, поскольку толерантность быстро снижается — использование той же дозы, что и до воздержания, может привести к смертельной передозировке. Настоятельно рекомендуется медицинское наблюдение и лечение опиоидными агонистами.\n\nКогда начинается синдром отмены\nГрафик отмены ВОЗ устанавливает сроки в зависимости от типа опиоида:\n• Опиоиды короткого действия (героин, оксикодон): начало действия через 8–24 часа после последнего употребления, продолжительность 4–10 дней.\n• Опиоиды длительного действия (метадон): начало действия 12–48 часов, продолжительность 10–20 дней.\n\nСимптомы первого дня\nВ рекомендациях ВОЗ перечислены ранние признаки отмены опиоидов:\n• Тревога и возбуждение\n• Мышечные спазмы и боли.\n• Водянистые выделения из глаз и носа.\n• Зевота и потливость\n• Бессонница с приливами жара и холода.\n• Ранняя тошнота\n\nПочему это так плохо\nОпиоидная система регулирует боль, стресс, эмоциональное благополучие и базовый комфорт. Длительное употребление опиоидов подавляет выработку организмом собственных опиоидов (эндорфинов). Когда опиоиды удаляются, организм остается без нормальной системы комфорта — он испытывает боль, тревогу и дистресс на уровне, отражающем глубину этого подавления. Рекомендации ВОЗ рекомендуют поддерживающую терапию, включающую употребление 2–3 литров воды в день и мониторинг 3–4 раза в день.';

  @override
  String get opioidReferenceDay7 =>
      'Неделя отказа от опиоидов: пиковые симптомы уменьшаются\n\nИсточник: «Клинические рекомендации по лечению абстиненции и лечению наркотической зависимости в закрытых учреждениях», Всемирная организация здравоохранения (2009), на книжной полке NCBI.\n\nПик и спад\nГрафик ВОЗ предусматривает отмену опиоидов короткого действия в течение 4–10 дней, при этом симптомы появляются рано, а затем ослабевают в течение этого периода. К концу первой недели:\n• Рвота и диарея в основном проходят.\n• Мышечные судороги менее выражены.\n• Физические страдания значительно уменьшаются.\n\nЧто осталось на 7-й день\nХотя острые физические симптомы улучшаются, сохраняются серьезные проблемы:\n• Бессонница — нарушение сна является одним из наиболее стойких симптомов отмены опиоидов.\n• Подавленное настроение и эмоциональная уравновешенность.\n• Усталость и слабость\n• Тяга к опиоидам\n• Тревога\n\nПост-острая абстиненция\nПосле первого периода отмены проблемы со сном, изменение настроения и волны тяги к опиоидам могут продолжаться в течение недель или месяцев. Постоянная поддержка имеет наибольшее значение на этом более длительном этапе восстановления.\n\nЛечение опиоидными агонистами\nВ рекомендациях ВОЗ метадон и бупренорфин описываются как эффективные методы лечения, которые уменьшают тяжесть абстиненции и способствуют выздоровлению. Эти лекарства также снижают смертность от расстройств, вызванных употреблением опиоидов, и многие люди, успешно выздоравливающие в долгосрочной перспективе, используют их на ранней стадии выздоровления.';

  @override
  String get opioidReferenceDay14 =>
      'Две недели без опиоидов: режим сна начинает улучшаться\n\nИсточник: Рецензируемые фармакологические исследования опиоидов и сна.\n\nСвязь опиоидов со сном\nВ этой исследовательской работе рассматривается двунаправленная связь между употреблением опиоидов и нарушением сна. Результаты показывают, что опиоиды серьезно нарушают нормальную архитектуру сна посредством нескольких механизмов:\n• Подавление медленноволнового (глубокого) сна.\n• Нарушение быстрого сна.\n• Вызывает нарушение дыхания во сне (центральное апноэ во сне).\n• Нарушение регуляции циркадных ритмов.\n\nПорочный круг\nИсследование подчеркивает двунаправленный характер проблемы: употребление опиоидов нарушает сон, а плохой сон увеличивает болевую чувствительность и интенсивность тяги, что приводит к дальнейшему употреблению опиоидов. Преодоление опиоидной зависимости также означает разрыв цикла нарушений сна.\n\nСон в две недели\nК 14 дням воздержания от опиоидов сон начинает нормализоваться:\n• Центральное апноэ во сне (при наличии) проходит в течение нескольких дней.\n• Глубокий медленноволновой сон начинает восстанавливаться.\n• Быстрый сон возвращается к нормальной пропорции\n• Наступление сна становится более надежным.\n\nВ течение двух недель сон остается серьезной проблемой для многих людей, но ситуация явно улучшается. Хороший сон напрямую улучшает настроение, уменьшает тягу и поддерживает ясное мышление, необходимое для выздоровления.';

  @override
  String get opioidReferenceDay30 =>
      'Месяц отказа от опиоидов: мышление и память начинают восстанавливаться\n\nИсточник: Клиника Мэйо.\n\nПонимание расстройства, связанного с употреблением опиоидов\nВ клинике Майо объясняют, что опиоиды прикрепляются к рецепторам по всему мозгу и телу, вызывая облегчение боли, эйфорию и сонливость. При многократном использовании мозг реагирует менее резко и производит меньше собственных опиоидоподобных химических веществ. Это создает физическую зависимость.\n\nМышление и память за один месяц\nЧерез 30 дней произошло значимое восстановление мышления и памяти. Худший мозговой туман рассеялся, и передняя часть мозга, отвечающая за планирование и самоконтроль, восстанавливается:\n• Процесс принятия решений улучшается\n• Рабочая память восстанавливается\n• Увеличение скорости обработки\n• Концентрация более надежная\n\nЭндорфиновая система\nЧерез месяц естественная эндорфиновая система мозга активно восстанавливается: она производит больше собственных опиоидоподобных химических веществ и снова реагирует более нормально. Эмоциональная уравновешенность и снижение болевой терпимости продолжают улучшаться по мере продолжения выздоровления.\n\nПрофилактика рецидивов\nВ клинике Майо подчеркивают, что один месяц трезвости не означает, что риск рецидива миновал — он остается повышенным. Толерантность значительно снизилась, а это означает, что рецидив при использовании предыдущих доз несет в себе серьезный риск передозировки.';

  @override
  String get opioidReferenceDay60 =>
      'Два месяца без опиоидов: стрессовые цепи мозга начинают успокаиваться\n\nИсточник: «Нейропластичность расширенной миндалины при отмене опиоидов и длительном воздержании от опиоидов», Frontiers in Pharmacology (2023).\n\nОткуда берутся негативные чувства\nВ этом обзоре показано, как длительное употребление опиоидов меняет цепи стресса и страха в мозгу. Во время абстиненции эти цепи становятся сверхактивными, а передача сигналов дофамина в цепях вознаграждения падает. Эта комбинация помогает объяснить беспокойство, плохое настроение и тягу на ранних этапах выздоровления.\n\nПочему два месяца приносят облегчение\nВажно отметить, что обзор документально подтверждает, что некоторые из этих изменений обратимы. В моделях на животных потеря плотности позвоночника в прилежащей оболочке описывается как «стойкое, но обратимое снижение», возвращающееся к значениям, существовавшим до приема препарата, в течение нескольких недель. По мере того как эти цепи стресса и вознаграждения перерегулируются, механистическая основа эмоционального потрясения на раннем этапе восстановления ослабевает, что согласуется со снижением реактивности и более устойчивым настроением, о котором многие люди сообщают примерно к двум месяцам.\n\nСигнал восстановления\nОбратимые изменения плотности позвоночника и цепей стресса, описанные в этой литературе, демонстрируют реальный процесс биологического восстановления: во время воздержания схема, управляющая негативным эмоциональным состоянием зависимости, возвращается к состоянию, существовавшему до приема наркотиков.';

  @override
  String get opioidReferenceDay90 =>
      'Три месяца без опиоидов: химия вознаграждения начинает восстанавливаться\n\nИсточник: «Структурное и функциональное восстановление мозга у людей с расстройствами, связанными с употреблением психоактивных веществ во время абстиненции: обзор продольных исследований нейровизуализации», «Зависимость от наркотиков и алкоголя» (2022), на PubMed Central.\n\nДофамин и опиоиды\nОпиоиды стимулируют высвобождение дофамина в системе вознаграждения мозга. Длительное употребление приводит к истощению этой системы: в одном исследовании по сканированию мозга белки, которые перерабатывают дофамин, в начале были примерно на 30% ниже здорового уровня. Это помогает объяснить потерю удовольствия, наблюдаемую при расстройствах, связанных с употреблением опиоидов, и раннее выздоровление.\n\nВосстановление происходит постепенно\nВ этом обзоре собраны продольные исследования, в которых повторно проверялись те же люди на предмет воздержания. Дефицит транспортера дофамина восстановился примерно на 20% за 6–12 месяцев воздержания, а некоторые аномалии лобного серого и белого вещества, наблюдаемые при раннем отказе, больше не обнаруживались примерно через месяц. Через три месяца вы уже находитесь на ранней стадии восстановления: система вознаграждения и фронтальная система заметно восстанавливаются, но еще не завершились.\n\nЧто испытывают люди\nПо мере восстановления этих цепей многие люди примерно через 90 дней замечают:\n• Больше подлинного удовольствия от занятий, еды и отношений.\n• Снижение тяги по сравнению с ранним выздоровлением.\n• Более ясное мышление и лучшее принятие решений\n\nСигнал восстановления\nПродольная визуализация человека показывает, что доступность транспортера дофамина увеличивается через 6–12 месяцев воздержания, в то время как нарушения лобного серого и белого вещества начинают нормализоваться гораздо раньше. Через 90 дней уже установлено измеримое восстановление мозга.';

  @override
  String get opioidReferenceDay180 =>
      'Шесть месяцев без опиоидов: иммунная система начинает восстанавливаться\n\nИсточник: «Влияние толерантности к опиоидам и синдрома отмены на иммунную систему», Журнал нейроиммунной фармакологии (2006), на PubMed.\n\nОпиоиды и иммунная система\nЭтот обзор показывает, что длительное употребление опиоидов ослабляет иммунную систему несколькими способами:\n• Прямое действие опиоидов на иммунные клетки (Т-клетки, NK-клетки, макрофаги)\n• Нарушение химических веществ, передающих иммунные сигналы.\n• Нарушение оси гипоглубинно-мозг-гипофиз-надпочечники (ГГН).\n• Повышенная восприимчивость к инфекциям.\n\nСигнал восстановления\nОпиоиды длительного действия подавляют несколько частей иммунной системы. Через шесть месяцев после прекращения приема опиоидов это постоянное подавление исчезло на полгода, и иммунная функция активно восстанавливается до нормального уровня.\n\nЧто означают шесть месяцев\nШесть месяцев без опиоидов дают иммунным клеткам, иммунной системе сигнализации и стрессовой системе организма достаточно времени для восстановления до нормального состояния.\n\nПочему это все еще важно\nЭто особенно актуально для людей, которые употребляли опиоиды путем инъекций и столкнулись с дополнительным риском заражения, например, ВИЧ и гепатитом С. Отказ от опиоидов, улучшение питания и поддержание воздержания создают иммунную систему условия, необходимые для дальнейшего выздоровления.';

  @override
  String get opioidReferenceDay365 =>
      'Год без опиоидов: восстановление структуры и биохимических процессов мозга\n\nИсточник: «Структурное и функциональное восстановление мозга у людей с расстройствами, связанными с употреблением психоактивных веществ во время абстиненции: обзор продольных исследований нейровизуализации», «Зависимость от наркотиков и алкоголя» (2022), на PubMed Central.\n\nЧто показывает нейровизуализация у людей\nВ этом обзоре собраны исследования, в которых одних и тех же людей с расстройством, связанным с употреблением опиоидов, сканировали более одного раза в период воздержания. Результаты последовательно указывают на выздоровление:\n• Белки, перерабатывающие дофамин в зонах вознаграждения и движения, примерно на 30 % ниже нормы в начале, выросли примерно на 20 % за 6–12 месяцев отсутствия опиоидов.\n• Аномалии лобного серого вещества, присутствующие при ранней отмене, больше не обнаруживались примерно через месяц воздержания.\n• Белое вещество (лобное и поясная извилина) и лобная активность в состоянии покоя также начали нормализоваться в течение первого месяца.\n\nЧто означает один год\nК двенадцати месяцам вы достигнете или превысите самое длинное окно, измеренное этими исследованиями. У дофаминовой системы было больше всего времени на восстановление, а лобные цепи, поддерживающие самоконтроль и суждение, восстанавливались в течение нескольких месяцев — биологический аналог более ясного мышления, более слабой тяги и более устойчивого настроения, которые люди описывают через год.\n\nСигнал восстановления\nЧерез год данные нейровизуализации у людей в значительной степени ориентирован на восстановление: доступность транспортера дофамина возросла в течение 6–12 месяцев, в то время как лобные структурные и функциональные нарушения потребовались многие месяцы для нормализации.';

  @override
  String get opioidReferenceDay730 =>
      'Два года без опиоидов: стабильный фундамент\n\nИсточник: «Лечение расстройств, связанных с употреблением опиоидов», Центры по контролю и профилактике заболеваний (CDC).\n\nХроническое заболевание, которое хорошо лечится\nCDC описывает расстройство, связанное с употреблением опиоидов, как «хроническое заболевание, которое может затронуть любого» — «состояние здоровья, а не моральный недостаток». Достижение двух лет устойчивого выздоровления означает, что вы успешно справились с этим заболеванием в один из наиболее уязвимых периодов.\n\nТо, что говорит CDC, работает\nРекомендации CDC сосредоточены на методах лечения, которые обеспечивают стабильное выздоровление в долгосрочной перспективе:\n• Лекарства от расстройств, вызванных употреблением опиоидов, — бупренорфин, метадон и налтрексон, — которые он называет особенно эффективными.\n• Сочетание лечения с поведенческой терапией и консультированием.\n• Лечение, которое длится разную продолжительность, в зависимости от конкретного человека.\nЦентры по контролю и профилактике заболеваний (CDC) отмечают, что эти лекарства помогают «нормализовать химию мозга» и облегчить тягу — химия, которая была нарушена при активной зависимости, снова работает с вами.\n\nОставайтесь в безопасности\nЦентр по контролю и профилактике заболеваний (CDC) призывает людей, выздоравливающих, спрашивать своего врача о риске повторного употребления и передозировки, а также держать налоксон под рукой. Толерантность падает во время воздержания, поэтому возвращение к опиоидам после такого длительного периода особенно опасно, зная, что это часть защиты того, что вы создали.\n\nДва года спустя\nЦентры по контролю и профилактике заболеваний (CDC) ясно понимают, что восстановление часто является долгосрочным процессом, а не финишной чертой. Два года — это не конец пути. Это стабильный, здоровый фундамент и убедительное доказательство того, что используемый вами подход работает.';

  @override
  String get pornographyReferenceDay1 =>
      'День первый: возвращение контроля\n\nИсточник: Краус и др., Компульсивное расстройство сексуального поведения в МКБ-11, Мировая психиатрия (2018).\n\nКлинически важной проблемой является не использование порнографии само по себе. Компульсивное расстройство сексуального поведения определяется как постоянные трудности с контролем повторяющегося сексуального поведения, когда этот паттерн вызывает значительный дискомфорт или ухудшение состояния. Проблемное использование порнографии может быть одним из проявлений этой более широкой проблемы.\n\nЭто делает первый день скорее конкретным, чем мистическим: вы прервали поведение, которое, по вашему мнению, вышло из-под контроля. Один завершенный день не является доказательством перезагрузки мозга и нервов, но он дает вам первое реальное наблюдение за тем, когда появляются побуждения, какие ситуации их вызывают и что вы можете сделать вместо этого.\n\nЕсли ваше использование не причиняло беспокойства, не наносило вреда и не было трудным для контроля, клиническая концепция CSBD может к вам не относиться. Эти вехи нацелены на людей, которые намеренно отказываются от проблемного или компульсивного употребления.';

  @override
  String get pornographyReferenceDay3 =>
      'День третий: узнайте, как может выглядеть желание\n\nИсточник: Левчук и др., Отстранение и толерантность в связи с компульсивным расстройством сексуального поведения и проблематичным использованием порнографии, Журнал поведенческих зависимостей (2022).\n\nВ предварительно зарегистрированной на национальном уровне репрезентативной польской выборке из 1541 взрослого люди, о которых сами сообщали, более сильные переживания, подобные синдрому отмены, были связаны с более выраженным CSBD и тяжестью проблемного использования порнографии. Среди участников с проблематичным использованием порнографии чаще всего сообщалось о таких переживаниях, как трудноостановимые сексуальные мысли, трудноконтролируемое желание, повышенное возбуждение, раздражительность, изменения настроения и проблемы со сном.\n\nБеспокойство, навязчивые сексуальные мысли, сильные побуждения и раздражительность зарегистрированы у людей с более серьезными проблемами употребления наркотиков. Если они появятся примерно на третий день, воспринимайте их как настоящую модель абстиненции и управляйте триггерами.\n\nЗапишите, какие побуждения происходят на самом деле, что им предшествовало и какая реакция помогла. Выздоровлением становится легче управлять, когда триггер назван, а не рассматривается как загадочное событие в мозгу.';

  @override
  String get pornographyReferenceDay7 =>
      'Одна неделя: что обнаружило рандомизированное исследование абстиненции\n\nИсточник: Влияние 7-дневного периода воздержания от порнографии на симптомы абстиненции у постоянных пользователей порнографии, Архивы сексуального поведения (2023).\n\nИсследователи рандомизировали 176 постоянных пользователей порнографии, которые либо попытались воздерживаться в течение семи дней, либо продолжали вести себя как обычно. Во всей выборке воздержание не привело к значительному общему увеличению тяги, плохого настроения или симптомов абстиненции.\n\nПредварительный анализ действительно выявил повышенное влечение среди людей, которые до исследования сочетали высокие показатели проблемного использования с ежедневным использованием порнографии. Этот результат нуждается в повторении, но он полезен: трудная первая неделя может стать реальной для более тяжелых проблемных пользователей, в то время как всеобщий синдром отмены порнографии не подтверждается этим испытанием.\n\nЕсли вы прожили неделю, у вас теперь есть больше доказательств вашей собственной модели поведения, чем может предоставить любая общая временная шкала в Интернете.';

  @override
  String get pornographyReferenceDay14 =>
      'Две недели: наметьте триггеры, которые действительно имеют значение\n\nИсточник: Биопсихосоциальные детерминанты проблемного использования порнографии: систематический обзор (2023).\n\nВ этом обзоре были обобщены данные 66 исследований и обнаружено, что проблематичное использование порнографии связано с сочетанием факторов, а не с одним простым дофаминовым механизмом. Неоднократно выявленные психологические и социальные факторы включали тягу, стресс, избегание, одиночество, самооценку, негативные убеждения и стиль преодоления трудностей.\n\nДве недели дают вам возможность неоднократно подвергаться воздействию будних дней, выходных, скуки, стресса, уединения, устройств и других контекстов, которые могли сигнализировать о старом поведении. Используйте эти данные. Если триггером является стресс, разработайте реакцию на стресс. Если спусковым крючком является одиночество, добавьте контакт. Если легкий доступ является триггером, измените среду.\n\nФактические данные подтверждают работу над причинами проблемного употребления; не требуется притворяться, что каждый человек следует одному и тому же биологическому обратному отсчету.';

  @override
  String get pornographyReferenceDay30 =>
      'Один месяц: контроль важнее простого подсчета частот\n\nИсточник: Бете и др., Связаны ли проблемы сексуального функционирования с частым использованием порнографии и/или проблематичным использованием порнографии?, Аддиктивное поведение (2021).\n\nВ выборке из 14 581 взрослого человека проблемное использование порнографии имело умеренную положительную связь с проблемами сексуального функционирования как у мужчин, так и у женщин. Частота использования порнографии сама по себе показала слабую отрицательную связь с этими проблемами.\n\nЭто различие имеет значение. Факты не подтверждают утверждение каждому пользователю порнографии о том, что частота просмотра сама по себе вредит сексуальной функции. Более клинически значимой целью является потеря контроля и проблемы, связанные с этой закономерностью.\n\nЧерез месяц сравните жизнь сейчас с тем, когда вы начали: озабоченность, потерянное время, способность остановиться, сексуальное функционирование, конфликты в отношениях и стресс. Эти изменения имеют большее значение, чем ожидание мифической перезагрузки мозга на 30-й день.';

  @override
  String get pornographyReferenceDay90 =>
      'Три месяца: устойчивые изменения возможны\n\nИсточник: Кросби и Тухиг, Терапия принятия и приверженности при проблемном использовании порнографии в Интернете: рандомизированное исследование, Поведенческая терапия (2016).\n\nВ этом небольшом рандомизированном исследовании сравнивалась программа ACT из 12 сеансов со списком ожидания у 28 взрослых мужчин. Просмотр порнографии значительно сократился в группе ACT в конце лечения, и существенное снижение сохранилось и в течение трехмесячного периода наблюдения.\n\nИсследование не доказывает, что 90 дней воздержания сами по себе приводят к такому же результату, а его выборка была небольшой и демографически узкой. Важно то, что он демонстрирует: проблемное использование порнографии можно изменить, а структурированные навыки могут привести к изменениям, которые сохраняются после непосредственного периода лечения.\n\nЕсли ваш прогресс по-прежнему зависит главным образом от упорства, три месяца — хороший момент для укрепления системы вокруг него: триггерные планы, принятие побуждений без действий, разногласия в окружающей среде, ответственность и терапия, когда это необходимо.';

  @override
  String get pornographyReferenceDay180 =>
      'Шесть месяцев: долгосрочный контроль симптомов может сохраняться\n\nИсточник: Холлберг и др., Рандомизированное контролируемое исследование групповой когнитивно-поведенческой терапии гиперсексуального расстройства у мужчин, Журнал сексуальной медицины (2019).\n\nУ 137 мужчин с неконтролируемым сексуальным поведением семинедельная групповая КПТ привела к более значительному снижению гиперсексуальных симптомов и сексуальной компульсивности, чем список ожидания, а также к улучшению психического благополучия. Результаты лечения оставались стабильными как через три, так и через шесть месяцев наблюдения.\n\nЭто исследование охватывало гиперсексуальное расстройство в более широком смысле, а не только воздержание от порнографии, поэтому его не следует превращать в утверждение, что каждый человек биологически выздоравливает через шесть месяцев. Это подтверждает более сильное и полезное утверждение: устойчивое улучшение компульсивного сексуального поведения может оставаться стабильным в течение этого периода времени.\n\nТаким образом, шесть месяцев являются важной вехой в обслуживании. Сохраняйте процедуры, которые облегчили контроль, вместо того, чтобы воспринимать дату как разрешение на их отмену.';

  @override
  String get pornographyReferenceDay365 =>
      'Один год: доказательства устойчивого изменения поведения\n\nИсточник: Последующие результаты лечения гиперсексуальности, основанного на принятии, в течение одного года (2026 г.).\n\nЧерез год наблюдения участники этого исследования, основанного на принятии лечения, не вернулись к уровню гиперсексуальности, который был до лечения. Авторы описали полученные результаты как предварительное свидетельство устойчивых, клинически значимых преимуществ, а также предполагаемого контроля над тягой среди процессов, наблюдаемых с течением времени.\n\nЭто свидетельства последующего лечения, а не доказательство годичной перезагрузки мозга. Осмысленное утверждение в любом случае лучше: клинически значимый контроль может сохраняться в течение года, а не исчезать, как только заканчивается первоначальное вмешательство.\n\nГод ваших собственных изменений — это также большой набор личных данных. Сравните текущий контроль, дистресс, функционирование, отношения и использование времени с тем, с чего вы начали; именно такие результаты имеют клиническое значение.';

  @override
  String get pornographyReferenceDay1825 =>
      'Пять лет: результат — долгосрочный контроль\n\nИсточник: Компульсивное расстройство сексуального поведения и проблемное использование порнографии: комплексный междисциплинарный обзор, проведенный экспертами (2026 г.).\n\nСовременные обзоры рассматривают CSBD и проблемное использование порнографии как сложные проблемы, включающие контроль, дистресс, функционирование, контекст и индивидуальные различия. Не существует подтвержденного пятилетнего порога перезагрузки мозга и нервов.\n\nНо пять лет – это не пустая веха. Это 1825 дней сохранения выбранного вами направления поведения. Поскольку клинической проблемой является стойкая потеря контроля с дистрессом или ухудшением состояния, устойчивый контроль и восстановление функционирования в течение многих лет сами по себе являются значимыми результатами.\n\nНа этом этапе полезный вопрос уже не в том, достиг ли ваш мозг вымышленного процента перенастройки. Вопрос в том, контролирует ли старый шаблон ваш выбор или разрушает жизнь, которую вы хотите. Если этого не произойдет, это будет существенным долгосрочным успехом.';

  @override
  String get smokingReferenceDay1 =>
      'День первый: преимущества начинаются прямо сейчас\n\nИсточник: Национальная служба здравоохранения «Лучшее здоровье».\n\nПреимущества начинаются в течение нескольких минут, а не дней. Организм начинает нормализоваться, как только прекращается дым.\n\nЧто происходит сегодня\n• 20 минут: частота пульса начинает возвращаться к норме.\n• 8 часов: угарный газ в крови снижается вдвое; уровень кислорода восстанавливается\n• 48 часов: уровень угарного газа снизился до уровня некурящего.\n\nУгарный газ связывается с эритроцитами сильнее, чем кислород, вытесняя его из крови. Каждый орган получал меньше кислорода, чем следовало бы. Ситуация меняется в течение двух дней.\n\nСиндром отмены начинается в первый день\n• Тяга — каждая обычно длится 3–5 минут.\n• Раздражительность и трудности с концентрацией внимания.\n• Повышенный аппетит.\n\nЭто временные и управляемые проблемы. Программа NHS Better Health предлагает бесплатную поддержку, включая приложения и консультации фармацевтов.';

  @override
  String get smokingReferenceDay3 =>
      'День третий: пик абстиненции\n\nИсточник: Маклафлин, Дэни и Де Биази.\n\nЧерез 72 часа никотин выводится из вашего организма. За годы курения в мозгу появились дополнительные никотиновые рецепторы; теперь они недостаточно стимулированы, вызывая синдром отмены.\n\nПиковые симптомы\n• Тяга — наиболее сильная в данный момент.\n• Раздражительность, разочарование, беспокойство.\n• Трудности с концентрацией внимания\n• Тревога\n• Головные боли\n• Повышенный аппетит.\n• Кашель (дыхательные пути очищаются — хороший знак)\n\nЭто самый трудный день. Хуже не бывает — с этого момента симптомы постепенно ослабевают по мере того, как ваш мозг приспосабливается.\n\nНЗТ, варениклин и бупропион значительно снижают тяжесть синдрома отмены на этом этапе.';

  @override
  String get smokingReferenceDay7 =>
      'Одна неделя: возвращение вкуса и обоняния\n\nИсточник: Национальная служба здравоохранения «Лучшее здоровье».\n\nНедельный отказ от курения является надежным предиктором долгосрочного успеха: люди, пережившие первую неделю, с гораздо большей вероятностью бросят курить навсегда.\n\nЧто восстановлено\n• Еда становится более ароматной\n• Запахи стали более яркими\n• Дыхание становится легче — дыхательные пути очищаются.\n• Кровообращение улучшается\n• Кожа становится лучше увлажненной\n\nКурение напрямую повреждает вкусовые и обонятельные рецепторы; через несколько дней после прекращения приема они начинают выздоравливать.\n\nОстрая никотиновая абстиненция ослабевает. Физические тяги короче и реже. Тяга, основанная на триггерах, все еще может присутствовать, но худшая физическая потребность уже позади.';

  @override
  String get smokingReferenceDay14 =>
      'Две недели: кровообращение улучшается\n\nИсточник: Национальная служба здравоохранения «Лучшее здоровье».\n\nЧерез 2–12 недель после прекращения кровообращение улучшается. Никотин сужает кровеносные сосуды с каждой сигаретой; без него сосуды расслабляются и кровь течет свободнее.\n\nЧто это значит\n• Улучшается приток крови к рукам, ногам и периферическим тканям.\n• Многие люди замечают, что руки и ноги стали теплее.\n• Ходить и подниматься по лестнице становится легче.\n\nПоскольку угарный газ уже выведен из крови в первый день, а кровообращение теперь улучшается, кислород более эффективно поступает в мышцы.\n\nРеснички, выстилающие дыхательные пути, восстанавливаются и выталкивают скопившуюся слизь. Если вы кашляете сильнее обычного, это признак выздоровления, а не неудачи.';

  @override
  String get smokingReferenceDay30 =>
      'Один месяц: функция легких повышается\n\nИсточник: Национальная служба здравоохранения «Лучшее здоровье».\n\nДыхание становится легче, а функция легких улучшается — увеличение до 10% за период от 3 до 9 месяцев. Через месяц вы уже находитесь на кривой восстановления.\n\nЧто происходит в легких\n• Реснички отросли и более эффективно очищают от слизи.\n• Воспаление дыхательных путей проходит.\n• У заядлого курильщика кашель проходит.\n• Улучшается толерантность к физическим нагрузкам\n\nКашель, хрипы и проблемы с дыханием улучшаются по мере улучшения функции легких. Один месяц — значимая точка на этой кривой восстановления.';

  @override
  String get smokingReferenceDay90 =>
      'Три месяца: риск сердечного приступа снижается\n\nИсточник: PMC — Сердечно-сосудистые последствия курения и прекращения курения (2024 г.).\n\nКурение повреждает сердце и артерии разными способами: оно ускоряет образование бляшек в артериях, способствует свертыванию крови, повышает кровяное давление и повреждает оболочку артерий. Прокоагулянтный и способствующий свертыванию крови эффекты обращаются в течение нескольких дней после прекращения курения, и в этом обзоре сообщается о заметном снижении частоты сердечных приступов и инсультов в течение первого года после прекращения курения.\n\nЧто улучшено на данный момент\n• Факторы свертываемости крови нормализуются.\n• Артериальное давление и частота сердечных сокращений стабилизируются.\n• Резкое раннее снижение риска острых сердечно-сосудистых событий уже идет полным ходом.\n\nПреимущества более медленного действия — обращение вспять многолетнего накопления артериальных бляшек — требуют больше времени и рассматриваются в более поздних этапах. Каждый месяц без курения способствует выздоровлению.';

  @override
  String get smokingReferenceDay180 =>
      'Шесть месяцев: восстановление иммунной защиты\n\nИсточник: Период без курения и восстановление функции альвеолярных иммунных клеток (PubMed).\n\nКурение подавляет иммунные клетки глубоко в легких, ухудшая их способность поглощать и убивать бактерии. Выздоровление происходит постепенно: у тех, кто воздерживается всего лишь 2 месяца, наблюдаются наибольшие нарушения, в то время как функции неуклонно улучшаются при более длительном воздержании. К 6 месяцам иммунная защита легких существенно восстановилась.\n\nЧто это значит\nЛегкие могут более эффективно очищать вдыхаемые бактерии и частицы, снижая восприимчивость к простуде, гриппу и пневмонии.\n\nИммунная защита продолжает улучшаться и по прошествии шести месяцев, но к настоящему времени защита организма заметно сильнее, чем в те первые недели.';

  @override
  String get smokingReferenceDay365 =>
      'Год: риск сердечного приступа резко снижается\n\nИсточник: PMC — Прекращение курения и исход инсульта; CDC, Преимущества отказа от курения\n\nКурение примерно удваивает риск инсульта, способствуя образованию бляшек в артериях, повышая свертываемость крови, повышая кровяное давление и повреждая кровеносные сосуды головного мозга. Собственная временная шкала пользы от отказа от курения CDC предполагает резкое снижение риска сердечного приступа на отметке в 1-2 года — вы находитесь на переднем крае этого окна.\n\nГрафик восстановления\nПолная нормализация риска инсульта занимает больше времени: цитируемое исследование инсульта, в котором наблюдали за бросившими курить в среднем почти пять лет, показало значительно более низкую частоту инсульта, чем у продолжающих курить, а данные Центров по контролю и профилактике заболеваний показывают, что риск ишемической болезни сердца снижается вдвое в течение 3–6 лет, при этом риск инсульта снижается в течение 5–10 лет.\n\nОдин год по-прежнему является настоящей медицинской вехой: самая крутая часть снижения острого риска уже позади, хотя долгосрочные преимущества в отношении сердечно-сосудистых и онкологических заболеваний продолжают накапливаться в течение многих лет.';

  @override
  String get smokingReferenceDay1825 =>
      'Пять лет: риск рака снижается\n\nИсточник: CDC, Преимущества отказа от курения.\n\nВ пять лет наступают одни из самых значительных преимуществ от рака.\n\nВехи на период от пяти до десяти лет\n• Повышенный риск рака рта, горла и голосового аппарата: снижен вдвое.\n• Риск инсульта: снижается\n\nВсе еще впереди\n• Десять лет: риск смерти от рака легких снижается примерно вдвое (через 10–15 лет); снижается риск развития рака мочевого пузыря, пищевода и почек\n• Пятнадцать лет: риск ишемической болезни сердца близок к риску некурящего человека.\n• Двадцать лет: риск рака рта, горла и голосового аппарата близок к уровню некурящих; Дополнительный риск рака шейки матки снизился примерно вдвое\n\nПять лет отказа от курения — это настоящее достижение: теперь вы находитесь в окне, где происходит наиболее значительное снижение риска рака, хотя до некоторых преимуществ (например, полной нормализации риска ишемической болезни сердца) еще далеко.';

  @override
  String get snriReferenceDay3 =>
      'Прекращение приема СИОЗСН: первые дни\n\nИсточник: Harvard Health Publishing.\n\nВажное примечание по безопасности\nПрием СИОЗСН следует прекращать только под медицинским наблюдением и с постепенным снижением дозы. Венлафаксин (Эффексор), в частности, имеет короткий период полувыведения — около 5 часов, поэтому уровень препарата снижается быстро, а симптомы отмены могут возникать резко и быть выраженными.\n\nПочему отмена СИОЗСН может быть сложнее, чем отмена СИОЗС\nСИОЗСН влияют на две системы, связанные с настроением, — серотониновую и норадреналиновую. После прекращения приема обеим системам приходится адаптироваться. Возможные симптомы отмены:\n• Гриппоподобные ощущения, усталость, потливость и мышечная боль.\n• Бессонница и нарушение сна.\n• Тошнота.\n• Нарушение равновесия и головокружение.\n• Сенсорные нарушения, включая так называемые «электрические разряды» в голове.\n• Повышенная возбудимость, раздражительность и тревога.\n\nСравнение препаратов СИОЗСН\nИз-за короткого периода полувыведения венлафаксин часто связан с более выраженными симптомами отмены. У дулоксетина период полувыведения дольше — около 12 часов, а десвенлафаксин занимает промежуточное положение.';

  @override
  String get snriReferenceDay7 =>
      'Неделя после прекращения приема СИОЗСН: адаптация двух систем мозга\n\nИсточник: Национальная служба здравоохранения Великобритании — рекомендации по прекращению приема антидепрессантов. Описанные ниже норадреналиновые механизмы отражают общую фармакологию СИОЗСН.\n\nАдаптация двух систем\nСИОЗСН влияют одновременно на серотонин и норадреналин. В течение первой недели обе системы продолжают перестраиваться.\n\nНорадреналиновая система\nОна участвует в реакции «бей или беги», регуляции артериального давления и уровня бодрости. Во время адаптации:\n• Артериальное давление может колебаться.\n• Тревога иногда ощущается физически — например, как сердцебиение или потливость.\n• Уровень энергии может быть нестабильным.\n\nСеротониновая система\nОдновременно перестраивается серотониновая система, поэтому могут сохраняться типичные симптомы отмены антидепрессантов. Из-за адаптации сразу двух систем первая неделя может быть особенно сложной.\n\nК концу недели физическая стабильность обычно начинает улучшаться: эпизоды головокружения при вставании становятся реже, а настроение постепенно выходит из наиболее резкой фазы колебаний.';

  @override
  String get snriReferenceDay14 =>
      'Две недели после прекращения приема СИОЗСН: физические симптомы ослабевают\n\nИсточник: Davies & Read (2019), Addictive Behaviors.\n\nСостояние через две недели\nПосле постепенного снижения дозы у многих людей острая физическая фаза к этому времени заметно ослабевает:\n• Сенсорные «разряды» становятся реже или исчезают.\n• Тошнота и гриппоподобные симптомы уменьшаются.\n• Головокружение и нарушения равновесия становятся менее выраженными.\n• Артериальное давление и частота сердечных сокращений стабилизируются по мере адаптации норадреналиновой системы.\n\nЧто может сохраняться\n• Повышенная эмоциональная чувствительность и перепады настроения.\n• Тревога.\n• Усталость и нестабильный уровень энергии.\n\nКонтекст исследования\nСистематический обзор Davies & Read (2019) показал, что симптомы отмены антидепрессантов могут быть выраженными, а венлафаксин относится к препаратам, при прекращении которых особенно важно постепенное снижение дозы.';

  @override
  String get snriReferenceDay30 =>
      'Месяц после прекращения приема СИОЗСН: стабилизация двух систем\n\nИсточник: Davies & Read (2019), Addictive Behaviors — систематический обзор частоты, тяжести и продолжительности симптомов отмены антидепрессантов.\n\nФаза стабилизации\nОдин месяц — важная точка адаптации серотониновой и норадреналиновой систем. У части людей симптомы отмены могут длиться дольше нескольких недель, но к этому сроку многие уже прошли наиболее тяжелую острую фазу.\n\nЧто обычно улучшается за месяц\n• Сенсорные нарушения, тошнота и головокружение у многих исчезают или заметно уменьшаются.\n• Артериальное давление становится стабильнее.\n• Сон постепенно возвращается к естественному режиму.\n• Уровень энергии выравнивается по мере адаптации норадреналиновой системы.\n\nЭмоциональный диапазон\nНекоторые люди во время приема СИОЗСН отмечают эмоциональное притупление. После прекращения препарата и адаптации мозга эмоциональная чувствительность и диапазон переживаний могут постепенно возвращаться.';

  @override
  String get snriReferenceDay90 =>
      'Три месяца после прекращения приема СИОЗСН: острая отмена обычно позади\n\nИсточник: «Синдром отмены антидепрессантов», Therapeutics Letter 112 (2018), Therapeutics Initiative, NCBI Bookshelf.\n\nПочему СИОЗСН требуют особого внимания\nВ обзоре выделяются антидепрессанты с коротким периодом полувыведения, включая венлафаксин и дулоксетин, поскольку при их прекращении риск симптомов отмены выше. В одном исследовании у 51% людей после прекращения дулоксетина отмечался как минимум один симптом. Поэтому постепенное снижение дозы под наблюдением особенно важно.\n\nЧто означают три месяца\nВ обзоре отмечается, что симптомы отмены обычно появляются в течение нескольких дней после прекращения или уменьшения дозы, а большинство проходит примерно за две недели, хотя у части людей они сохраняются дольше. К трем месяцам острая фаза обычно уже далеко позади.\n\nЧто известно о восстановлении\nНадежные данные описывают прежде всего сроки и выраженность синдрома отмены, а не точный момент «полного восстановления рецепторов». К этому сроку многие люди отмечают уменьшение эмоционального притупления и других побочных эффектов, связанных с приемом СИОЗСН.\n\nОтмена или рецидив\nЕсли тревога или сниженное настроение сохраняются спустя три месяца, важно обсудить это с лечащим врачом и отличить затяжные симптомы отмены от возвращения исходного состояния.';

  @override
  String get snriReferenceDay180 =>
      'Шесть месяцев после прекращения приема СИОЗСН: долгосрочная адаптация\n\nСостояние через шесть месяцев\nЧерез шесть месяцев после завершения постепенной отмены под медицинским наблюдением тяжелая ранняя фаза обычно остается далеко позади. За это время продолжают стабилизироваться настроение, сон, сексуальная функция и ясность мышления:\n• Серотониновая система работает без постоянного воздействия препарата.\n• Норадреналиновая регуляция и реакция на стресс продолжают нормализоваться.\n• Структура сна становится более устойчивой.\n• Сексуальная функция у многих улучшается; если нарушения сохраняются, их стоит обсудить с лечащим врачом.\n\nУстойчивость к стрессу\nПо мере нормализации норадреналиновой системы некоторые люди отмечают более стабильную реакцию на повседневный стресс и менее резкие колебания уровня возбуждения и энергии.';

  @override
  String get snriReferenceDay365 =>
      'Год после прекращения приема СИОЗСН: устойчивое восстановление\n\nОдин год адаптации\nЧерез год после завершения постепенного снижения дозы серотониновая и норадреналиновая системы длительное время работают без постоянного воздействия препарата.\n\nЧто подтверждают данные\nTherapeutics Letter отмечает, что симптомы отмены обычно начинаются в течение нескольких дней после прекращения приема и у большинства проходят примерно за две недели, хотя возможны более длительные случаи. Контролируемых исследований, специально оценивающих состояние ровно через год после отмены СИОЗСН, нет. Поэтому корректнее говорить о длительной стабильности, а не о доказанном «полном восстановлении» к конкретной дате.\n\nК этому сроку у многих людей уже давно прошли симптомы отмены, а эмоциональное притупление и сексуальные побочные эффекты, связанные с приемом препарата, уменьшились или исчезли. Если какие-либо симптомы сохраняются, их следует обсудить с лечащим врачом.\n\nЗначение этой вехи\nГод после прекращения приема СИОЗСН — значимая веха, отражающая длительный период стабильности после завершения контролируемого снижения дозы.';

  @override
  String get socialMediaReferenceDay1 =>
      'Отход от социальных сетей: день первый\n\nИсточник: Ламберт и др., «Недельный перерыв в социальных сетях улучшает самочувствие, депрессию и тревогу: рандомизированное контролируемое исследование», Киберпсихология, поведение и социальные сети (2022), на PubMed.\n\nЧто показывают доказательства\nВ этом строго контролируемом исследовании людям случайным образом было поручено либо сделать недельный перерыв в использовании Facebook, Instagram, Twitter и TikTok, либо продолжать использовать их как обычно. Группа перерыва показала значительное улучшение самочувствия и снижение депрессии и тревоги. Это реальные, контролируемые доказательства того, что отступление помогает.\n\nЧто показывают доказательства\nКомпульсивное использование социальных сетей тесно связано с ухудшением настроения и повышенной тревожностью, а рандомизированные исследования показывают, что намеренное сокращение использования социальных сетей может улучшить самочувствие, одновременно уменьшая депрессию и тревогу в течение недели.\n\nДень первый: чего ожидать\n• Беспокойство и желание проверить\n• \"Фантомные\" уведомления: ощущение кайфа, которого не было.\n• Скука, когда вы приспосабливаетесь к менее постоянной стимуляции.\nЭто нормальные ощущения, связанные с привычкой, и они временные. Распознавание шаблона – первый шаг к его изменению.';

  @override
  String get socialMediaReferenceDay3 =>
      'Три дня без социальных сетей: тревога и настроение\n\nИсточник: Ламберт и др., «Недельный перерыв в социальных сетях улучшает самочувствие, депрессию и тревогу: рандомизированное контролируемое исследование», Киберпсихология, поведение и социальные сети (2022), на PubMed.\n\nПочему перерыв улучшает настроение\nВ этом контролируемом исследовании люди, случайно назначенные на недельный перерыв в социальных сетях, закончили неделю с меньшим уровнем тревоги и депрессии и более высоким самочувствием, чем те, кто продолжал прокручивать страницу. Большая часть ежедневных страданий от интенсивного употребления происходит из-за социального сравнения — сравнения вашей реальной жизни с лучшими роликами других людей — и из-за низкосортного страха упустить что-то.\n\nЧто происходит около 72 часов\nВ начале перерыва привычка все еще громкая:\n• Сильные позывы проверить, часто вызванные рутинными моментами (пробуждение, ожидание в очереди).\n• Некоторая раздражительность и беспокойство.\n• Для некоторых людей первое ослабление тревоги, вызванной сравнением,\n• Привычка прокручивать страницы перед сном начинает ослабевать.\n\nЛовушка сравнения ослабевает\nБез постоянной подачи ярких моментов других людей сравнение, которое вызывает большую тревогу в социальных сетях, имеет меньше топлива. Результаты исследования показывают, что к концу первой недели эти ранние изменения приводят к измеримому улучшению настроения, поэтому дискомфорт в течение трех дней — это самая сложная часть изменений, которые окупаются.';

  @override
  String get socialMediaReferenceDay7 =>
      'Одна неделя без социальных сетей: измеренная отдача\n\nИсточник: Ламберт и др., «Недельный перерыв в социальных сетях улучшает самочувствие, депрессию и тревогу: рандомизированное контролируемое исследование», Киберпсихология, поведение и социальные сети (2022), на PubMed.\n\nРовно неделя — и это сработало\nЭто та веха, о которой исследование говорит наиболее непосредственно: в ходе исследования был сделан недельный перерыв. По сравнению с людьми, которые продолжали пользоваться социальными сетями, группа перерыва показала значительно более высокое самочувствие и значительно меньшую депрессию и тревогу всего за семь дней. Достижение одной недели — это достижение точки, когда контролируемое исследование обнаружило реальную пользу.\n\nЧто обычно замечают люди\nПомимо измеренного улучшения настроения, люди часто сообщают:\n• Больше восстановленного времени — многие удивляются, сколько они потратили.\n• Облегчается концентрация внимания, поскольку ослабевает привычка к постоянному переключению внимания.\n• Более спокойные вечера и более легкий сон без прокрутки перед сном.\nЭти результаты соответствуют более широкому улучшению благосостояния, измеренному в ходе исследования.\n\nПродолжайте идти\nОдна неделя — это настоящая, подтвержденная фактами веха. Преимущества настроения, времени и внимания, как правило, тем глубже, чем дольше сохраняется более здоровый образ жизни.';

  @override
  String get socialMediaReferenceDay14 =>
      'Две недели без социальных сетей: результаты за две недели\n\nИсточник: Койн и Вудрафф, «Перерыв: эффекты участия в двухнедельной цифровой детоксикации в социальных сетях… среди молодых людей», Поведенческие науки (2023), на PubMed Central.\n\nОб этом исследовании\nМолодые люди ограничили использование социальных сетей примерно 30 минутами в день в течение двух недель, при этом использование объективно отслеживалось на их телефонах (оно упало примерно на 78%). Участники сократили использование социальных сетей примерно на 78%, став прямым проверкой того, что происходит, когда использование социальных сетей резко сокращается на две недели.\n\nЧто улучшилось\nЗа две недели участники продемонстрировали улучшения в:\n• Сон — как продолжительность, так и качество\n• Удовлетворенность жизнью\n• Стресс\n• Воспринимаемое здоровье\n• Результаты по шкале зависимости от смартфонов и социальных сетей.\nИзмеренные результаты были конкретными: более продолжительный и лучший сон, снижение стресса, более высокая удовлетворенность жизнью и воспринимаемое хорошее самочувствие, а также снижение показателей зависимости от смартфонов/социальных сетей.\n\nСледите за откатом\nИсследователи также заметили, что после этого использование возвращается к предыдущим уровням. Две недели — это реальная выгода, но она подчеркивает, почему целенаправленный план, а не просто временный перерыв, — это то, что сохраняет преимущества.';

  @override
  String get socialMediaReferenceDay30 =>
      'Месяц без социальных сетей: реальная связь углубляется\n\nИсточник: Койн и Вудрафф, «Перерыв: эффекты участия в двухнедельной цифровой детоксикации в социальных сетях… среди молодых людей», Поведенческие науки (2023), на PubMed Central.\n\nСвязь может улучшиться, если вы сделаете шаг назад\nЭто звучит парадоксально, но в этом исследовании отказ от социальных сетей был связан с улучшением поддерживающих отношений, а также с большей удовлетворенностью жизнью и снижением стресса. Время и внимание, ушедшие на ленту, стали доступны людям, реально присутствующим в вашей жизни.\n\nЧто принесет один месяц\nК 30 дням, когда автоматическая проверка становится намного слабее, многие люди обнаруживают:\n• Разговоры стали более активными и менее прерываемыми\n• Повышенный интерес к реальной деятельности и хобби.\n• Самооценка меньше зависит от лайков, комментариев и количества подписчиков.\n\nСигнал восстановления\nК одному месяцу вы сохраните более здоровый образ жизни в течение удвоенного периода вмешательства в исследовании. Улучшения в плане сна, стресса, удовлетворенности жизнью, хорошего самочувствия и отношений, измеренные за две недели, получили еще две недели, чтобы превратиться в рутину.\n\nСчитайте время\nСтремитесь заполнить освободившееся время занятиями, которые создают настоящую связь и удовлетворение, а не просто заменяют один экран другим.';

  @override
  String get socialMediaReferenceDay60 =>
      'Два месяца без социальных сетей: что подтверждают доказательства\n\nИсточник: Рамадан и др., «Влияние детоксикации цифровых социальных сетей на психическое здоровье: систематический обзор и метаанализ», Narra J (2024), на PubMed Central.\n\nСамая достоверная картина\nИсследователи объединили результаты 10 исследований, включая семь контролируемых испытаний. Наиболее очевидным результатом стало значительное уменьшение симптомов депрессии после того, как люди отказались от социальных сетей.\n\nСамый сильный результат\nСовместное исследование выявило явное снижение симптомов депрессии. К двум месяцам вы поддерживаете такое же снижение воздействия цифровых технологий, которое привело к такому же улучшению психического здоровья.\n\nКак могут выглядеть два месяца\nБлагодаря меньшему количеству ежедневных сравнений и меньшему подкреплению, основанному на ленте новостей, самооценка имеет гораздо меньше причин зависеть от лайков, комментариев или количества подписчиков, в то время как самые убедительные совокупные данные указывают на снижение симптомов депрессии.\n\nПрактический вывод\nФактические данные вознаграждают преднамеренные и устойчивые изменения. Используйте двухмесячный срок, чтобы сохранять осознанные ограничения, а не отступать назад, и инвестировать в офлайновые источники смысла и связи.';

  @override
  String get socialMediaReferenceDay90 =>
      'Три месяца без социальных сетей: новая норма\n\nИсточник: Койн и Вудрафф, «Перерыв: эффекты участия в двухнедельной цифровой детоксикации в социальных сетях… среди молодых людей», Поведенческие науки (2023), на PubMed Central.\n\nСон — выдающийся\nСреди наиболее ярких результатов этого исследования было улучшение сна — как продолжительности, так и качества — когда участники сразу отключали социальные сети. К трем месяцам устойчивого здорового образа жизни ночная прокрутка, которая раньше ела перед сном, уже давно перестала конкурировать с отдыхом, а лучший сон имеет тенденцию поднимать настроение, концентрацию и энергию.\n\nЧто еще улучшилось\nВ том же исследовании было обнаружено улучшение стресса, удовлетворенности жизнью, ощущения благополучия и поддерживающих отношений. Через три месяца это уже не новинка — у них было время привыкнуть к новой норме.\n\nСигнал восстановления на механизме\nОтказ от социальных сетей резко улучшил как продолжительность, так и качество сна в интервенционном исследовании. Три месяца поддержания этой схемы превращают сокращение ночной прокрутки в прочную привычку ко сну.\n\nПрисутствие и отношения\nПоскольку рефлекс заполнять каждую минуту тишины с телефоном гораздо слабее, присутствие — во время разговоров, еды и простоя — становится более естественным, и отношения, в которые вы вложили более трех месяцев, как правило, из-за этого становятся сильнее.';

  @override
  String get socialMediaReferenceDay180 =>
      'Шесть месяцев без социальных сетей: постепенное восстановление\n\nИсточник: Рамадан и др., «Влияние детоксикации цифровых социальных сетей на психическое здоровье: систематический обзор и метаанализ», Narra J (2024), на PubMed Central.\n\nЧто добавляет метаанализ\nОбъединив 10 исследований, в том числе семь контролируемых, исследователи обнаружили явное снижение симптомов депрессии после того, как люди сократили или приостановили использование социальных сетей.\n\nЧто на самом деле было найдено\n• Депрессия: статистически значимое снижение (наиболее явный и последовательный результат).\n• Удовлетворенность жизнью: значимого эффекта нет.\n• Стресс: нет существенного эффекта\n• Общее психическое благополучие: существенного влияния нет.\nСамый сильный совокупный результат очевиден: цифровой детокс значительно уменьшает симптомы депрессии.\n\nПочему вы все еще можете ощущать широкие преимущества\nШесть месяцев снижения воздействия корма дополняют практические преимущества, наблюдаемые при более коротких вмешательствах: больше свободного времени, меньше навязчивых проверок и устойчивое снижение воздействия цифровых технологий, связанного с симптомами депрессии.\n\nДержите контроль над лентой\nСамый большой выигрыш можно получить от отказа от тяжелого, пассивного и компульсивного употребления наркотиков. К шести месяцам новым стандартом становится намеренный контроль над социальными сетями, а не лента, контролирующая ваше внимание.';

  @override
  String get socialMediaReferenceDay365 =>
      'Один год без социальных сетей: пересмотр отношений\n\nИсточник: Рамадан и др., «Влияние детоксикации цифровых социальных сетей на психическое здоровье: систематический обзор и метаанализ», Narra J (2024), на PubMed Central.\n\nОдин год устойчивых перемен\nСамые убедительные совокупные исследования показывают, что отказ от социальных сетей уменьшает симптомы депрессии. Полный год означает, что для вас стал привычным режим более низкого воздействия, а не короткий перерыв.\n\nЧто строит год\nПолный год возвращает вам сотни часов для настоящих отношений, хобби, навыков, размышлений и творчества. Автоматической проверке понадобился целый год, чтобы ослабить, в то время как автономным процедурам потребовался целый год, чтобы укрепиться.\n\nУстойчивые преимущества\nНаиболее очевидным показателем улучшения психического здоровья является уменьшение симптомов депрессии. Практические выгоды — больше времени, меньше перерывов и меньше навязчивых проверок — увеличиваются с каждым днем, когда вы сохраняете контроль над новостной лентой.\n\nЧто будет дальше\nГод преднамеренных перемен перезагрузил отношения. Независимо от того, вернетесь ли вы к ограниченному, целенаправленному использованию или вообще откажетесь от него, навязчивая петля разорвана — и это долгосрочная победа.';

  @override
  String get ssriReferenceDay3 =>
      'Прекращение приема СИОЗС: первые дни\n\nИсточник: Издательство Harvard Health Publishing.\n\nВажное примечание по безопасности\nПрием СИОЗС следует прекращать только под медицинским наблюдением после постепенного снижения дозы. Резкое прекращение употребления, особенно после длительного применения, значительно увеличивает тяжесть симптомов отмены.\n\nЧто такое синдром отмены СИОЗС?\nСиндром отмены СИОЗС — хорошо документированный медицинский феномен, который возникает, когда прием СИОЗС прекращается или существенно снижается. Клиницисты используют аббревиатуру ФИНИШ для описания общих симптомов:\n• Гриппоподобные симптомы (утомляемость, потливость, мышечные боли)\n• Бессонница и нарушение сна.\n• Тошнота\n• Дисбаланс и головокружение.\n• Сенсорные нарушения — особенно «мозговые перебои».\n• Повышенное возбуждение, раздражительность и тревожность.\n\nПериод полураспада имеет значение\nФлуоксетин (Прозак) имеет очень длительный период полувыведения, составляющий 4–6 дней, поэтому он эффективно постепенно снижается и вызывает более мягкий эффект отмены. Пароксетин (Паксил) имеет самый короткий период полувыведения среди обычных СИОЗС и вызывает наиболее выраженные симптомы отмены. Сертралин, циталопрам и эсциталопрам находятся между ними.';

  @override
  String get ssriReferenceDay7 =>
      'Через неделю после приема СИОЗС: острая фаза\n\nИсточник: Национальная служба здравоохранения — Прекращение приема антидепрессантов или отказ от них.\n\nФаза острой отмены\nНациональная служба здравоохранения сообщает, что большинство симптомов отмены антидепрессантов начинаются в течение пяти дней после прекращения приема и в большинстве случаев длятся до шести недель. Через неделю острые физические симптомы обычно становятся наиболее выраженными и начинают снижаться у тех, кто постепенно снижал дозу.\n\nЧего ожидать через неделю\n• Физические симптомы (тошнота, головокружение, гриппоподобные ощущения) наиболее интенсивны, но должны начать ослабевать.\n• Распространены нарушения сна, включая яркие сны или бессонницу.\n• На этом этапе часто наблюдается эмоциональная лабильность — быстрая смена настроения.\n• Мозговые перебои все еще могут присутствовать, но их частота обычно начинает уменьшаться.\n\nРоль сужения\nНациональная служба здравоохранения настоятельно рекомендует постепенное снижение дозы — иногда в течение нескольких месяцев для долгосрочных пользователей — чтобы свести к минимуму последствия прекращения приема. Королевский колледж психиатров разработал рекомендации по постепенному снижению дозы, которые предполагают очень постепенное снижение дозы, часто с использованием жидких форм, для тех, кто принимает СИОЗС в течение длительного периода времени.';

  @override
  String get ssriReferenceDay14 =>
      'Две недели после приема СИОЗС: исчезновение физических симптомов\n\nИсточник: Davies & Read (2019), Аддиктивное поведение — «Систематический обзор частоты, тяжести и продолжительности эффектов отмены антидепрессантов».\n\nЧто обнаружило исследование\nЭтот знаковый систематический обзор показал, что примерно 56% людей, прекращающих прием антидепрессантов, испытывают эффекты отмены, и 46% из них описывают их как тяжелые. У большинства людей после правильного снижения дозы острая фаза в основном проходит через две недели:\n• Мозговые перебои значительно уменьшены или отсутствуют.\n• Устранились тошнота и гриппоподобные симптомы.\n• Улучшается головокружение и проблемы с равновесием.\n• Сон начинает нормализоваться\n\nОтличие прекращения лечения от рецидива\nСимптомы, которые появляются в течение нескольких дней после прекращения приема и соответствуют профилю ФИНИШ, скорее всего, являются синдромом отмены. Симптомы, которые появляются через 2–4 недели и напоминают исходное состояние, подвергаемое лечению, с большей вероятностью рецидивируют. Важно следить за этим различием вместе с врачом, назначающим лекарство.';

  @override
  String get ssriReferenceDay30 =>
      'Через месяц после приема СИОЗС: стабилизация\n\nИсточник: Хаддад П.М. (2001), Безопасность лекарств — «Синдромы прекращения приема антидепрессантов».\n\nФаза стабилизации\nВ этом обзоре начало прекращения приема описывается как быстрое, обычно в течение нескольких дней после прекращения приема или снижения дозы антидепрессанта, и отмечается, что большинство реакций легкие и кратковременные и проходят без специального лечения. Один месяц представляет собой переход от этого острого окна к стабилизации; у большинства людей, завершивших постепенное снижение дозы, острые симптомы отмены в настоящее время в значительной степени исчезли.\n\nЭмоциональный ландшафт через месяц\nЭмоциональные изменения в течение одного месяца различны и их важно отслеживать:\n• Некоторые люди поначалу чувствуют себя эмоционально «более плоскими», когда мозг приспосабливается — обычно это улучшается.\n• Другие испытывают эмоциональную яркость, которой не ощущали годами.\n• Уровни тревоги значительно различаются в зависимости от индивидуального состояния и основного заболевания.\n\nЦенность немедикаментозной поддержки\nИсследования неизменно показывают, что разговорная терапия, такая как КПТ (КПТ) и другие научно обоснованные психологические методы лечения, очень эффективны при заболеваниях, которые лечат СИОЗС. Отметка в один месяц — отличное время, чтобы убедиться в наличии такой поддержки.';

  @override
  String get ssriReferenceDay90 =>
      'Три месяца после приема СИОЗС: уже давно прошла отмена\n\nИсточник: «Синдром отмены антидепрессантов», Therapeutics Letter 112 (2018), Therapeutics Initiative, на книжной полке NCBI.\n\nЧто означают три месяца\nВ этом обзоре доказательств отмечается, что симптомы отмены антидепрессантов «обычно появляются в течение нескольких дней после прекращения приема или снижения дозы» и что «большинство симптомов отмены антидепрессантов проходят в течение 2 недель», хотя тяжелые случаи могут длиться от нескольких недель до месяцев. К трем месяцам острая фаза абстиненции значительно отстает у подавляющего большинства людей.\n\nПочему СИОЗС различаются\nОтмена более вероятна при использовании СИОЗС с более коротким периодом полувыведения (таких как пароксетин), чем при использовании СИОЗС с длительным периодом полувыведения (флуоксетин). В письме откровенно говорится, что реакции отмены могут быть существенными — два систематических обзора показали, что они «очень похожи» на реакции от бензодиазепинов — и возникают по крайней мере у трети людей, которые прекращают приём антидепрессантов.\n\nСигнал восстановления о «восстановлении рецептора»\nВы можете увидеть уверенные заявления о том, что рецепторы серотонина «полностью восстанавливают чувствительность к 2–3 месяцам». Надежные доказательства касаются синдрома отмены и его времени, а не точных часов восстановления рецепторов. Что достоверно: к трем месяцам фаза отмены обычно проходит, и многие люди замечают, что эмоциональное притупление и сексуальные побочные эффекты, которые некоторые испытывают при приеме СИОЗС, ослабевают после прекращения приема.\n\nЕсли симптомы сохраняются\nВ письме рекомендуется отличать отмену от подлинного возвращения основного состояния. Если плохое настроение или тревога сохраняются в течение трех месяцев, стоит обсудить это с вашим лечащим врачом, а не предполагать, что это «просто синдром отмены».';

  @override
  String get ssriReferenceDay180 =>
      'Шесть месяцев после приема СИОЗС: обоснованный взгляд\n\nИсточник: «Синдром отмены антидепрессантов», Therapeutics Letter 112 (2018), Therapeutics Initiative, на книжной полке NCBI.\n\nЧто устоялось за шесть месяцев\nВ этом обзоре отмечается, что даже тяжелые и продолжительные симптомы абстиненции обычно длятся от нескольких недель до месяцев, а не бесконечно, поэтому к шести месяцам острый синдром абстиненции у подавляющего большинства людей полностью проходит.\n\nБыть честным в остальном\nК шести месяцам обычный период отмены уже позади, и у серотониновой системы есть месяцы, чтобы прийти в норму. Сексуальные побочные эффекты обычно улучшаются после прекращения приема; если они сохраняются, обсудите их со своим врачом.\n\nЧто обычно сообщают люди\n• Более широкий эмоциональный диапазон по сравнению с приемом лекарств.\n• Улучшение сна и энергии у большинства\n• Продолжающееся постепенное улучшение, хотя темпы сильно различаются у разных людей.';

  @override
  String get ssriReferenceDay365 =>
      'Год спустя после приема СИОЗС: измеренное выздоровление\n\nИсточник: Даффи и др. (2021 г.), Оценка технологий здравоохранения — исследование ANTLER\n\nЧто на самом деле обнаружило это испытание\nANTLER наблюдал за длительными приемами антидепрессантов в учреждениях первичной медико-санитарной помощи Великобритании, которые либо продолжали принимать лекарства, либо прекратили прием. В течение следующего года у 56% тех, кто прекратил лечение, случился рецидив, по сравнению с 39% тех, кто продолжал принимать лекарства, что примерно в два раза увеличивает риск, а группа, прекратившая лечение, сообщила в среднем о несколько более низком качестве жизни.\n\nБолее полная картина\nНесмотря на более высокую частоту рецидивов, у значительной части людей, прекративших лечение, рецидива не было, и они оставались здоровыми без лекарств. Около трети из тех, кто прекратил прием антидепрессанта, в конечном итоге возобновили прием антидепрессанта — разумный клинический выбор, а не неудача.\n\nЗаметка о будущем\nДепрессия и тревога являются хроническими состояниями для некоторых людей. Возобновление приема лекарств не является неудачей, если основное заболевание вновь проявляется. Целью является благополучие, и один год успешного прекращения приема является настоящим достижением, независимо от того, что будет дальше.';

  @override
  String get steroidsReferenceDay1 =>
      'Отказ от анаболических стероидов: первые дни\n\nИсточник: «Общие симптомы, связанные с использованием и прекращением приема анаболических андрогенных стероидов у мужчин», Best Practice & Research Clinical Endocrinology & Metabolism (2022).\n\nОстрая фаза\nВ этом обзоре отмена ААС описывается как происходящая в два этапа. Первый, вызванный активацией симпатической нервной системы, а не уровнем гормонов, появляется в течение 1–2 дней после прекращения лечения и может включать:\n• Головная боль\n• Тремор\n• Сердцебиение\n• Тошнота\n\nПочему появляются симптомы\nАнаболические стероиды также подавляют выработку собственного тестостерона в организме — мозг обнаруживает стероиды и отключает гормональные сигналы, которые обычно управляют им. Это подавление сохраняется и после остановки, создавая вторую, более длительную фазу абстиненции, описанную в последующих этапах.\n\nПримечание по безопасности\nДепрессия может возникнуть во время отмены стероидов и стать серьезной. Обратитесь за медицинской помощью и неотложной помощью при любых мыслях о членовредительстве. Врачи часто направляют выздоровление; некоторые используют лекарства для его поддержки.';

  @override
  String get steroidsReferenceDay14 =>
      'Две недели без анаболических стероидов\n\nИсточник: «Общие симптомы, связанные с использованием и прекращением приема анаболических андрогенных стероидов у мужчин», Best Practice & Research Clinical Endocrinology & Metabolism (2022).\n\nНаступает хроническая фаза\nК двум неделям краткие симпатические симптомы первых дней обычно проходят, и вторая фаза обзора, вызванная продолжающимся дефицитом тестостерона, становится более заметной:\n• Усталость и плохое настроение.\n• Мышечные боли (миалгия)\n• Снижение либидо.\n• Бессонница и тяга к стероидам.\n\nВсе еще в периоде низких уровней гормонов\nДля восстановления естественной выработки тестостерона требуется гораздо больше времени, чем две недели, поэтому эта фаза является ожидаемой, а не признаком того, что что-то не так.\n\nИзвестная ловушка\nНекоторые мужчины возвращаются к употреблению специально для того, чтобы избежать этого периода — цикла, который сбрасывает часы восстановления, а не заканчивает его. Поддержка врача или консультанта помогает преодолеть эту фазу, а не лечить ее дополнительными стероидами.';

  @override
  String get steroidsReferenceDay30 =>
      'Месяц без анаболических стероидов\n\nИсточник: «Физическое, психологическое и биохимическое восстановление после гипогонадизма, вызванного анаболическими стероидами: обзорный обзор», на PubMed.\n\nВосстановление начинается\nПосле прекращения приема гормональные сигналы, стимулирующие выработку тестостерона в яичках, начинают восстанавливаться. Исследования показывают, что большая часть этого восстановления приходится на период от трех до шести месяцев, поэтому через месяц процесс уже идет.\n\nЧего ожидать\nСниженное настроение, либидо и уровень энергии могут сохраняться, в то время как уровень гормонов восстанавливается. Восстановление зависит от возраста и того, интенсивности и продолжительности предыдущего употребления.';

  @override
  String get steroidsReferenceDay90 =>
      'Три месяца без анаболических стероидов\n\nИсточник: «Физическое, психологическое и биохимическое восстановление после гипогонадизма, вызванного анаболическими стероидами: обзорный обзор», на PubMed.\n\nХорошее время для анализа крови\nК трем месяцам гормональная система успела значительно восстановиться. Полезно попросить вашего лечащего врача проверить тестостерон и гормоны, которые его контролируют.\n\nЧего ожидать\nУ многих мужчин через три месяца уровень повышается, но не нормализуется полностью. Настроение и либидо часто улучшаются до того, как уровень тестостерона полностью восстановится. Размер яичек и выработка спермы восстанавливаются медленнее и могут продолжать улучшаться в течение следующего года. Рост ткани молочной железы (гинекомастия), если она возникла, вряд ли обратится вспять без специального лечения.';

  @override
  String get steroidsReferenceDay180 =>
      'Шесть месяцев без анаболических стероидов\n\nИсточник: «Физическое, психологическое и биохимическое восстановление после гипогонадизма, вызванного анаболическими стероидами: обзорный обзор», на PubMed.\n\nЧто показывает исследование\nВ обзоре сообщается, что ЛГ и ФСГ — гормоны, которые заставляют яички вырабатывать тестостерон, — обычно восстанавливаются в течение трех-шести месяцев. К шести месяцам уровень тестостерона также обычно значительно восстанавливается.\n\nЕсли восстановление еще не завершилось\nЕсли симптомы низкого уровня тестостерона все еще присутствуют через шесть месяцев, эндокринолог может проверить, что происходит, и обсудить лечение, а не заставлять вас ждать.';

  @override
  String get steroidsReferenceDay365 =>
      'Год без анаболических стероидов\n\nИсточник: «Гипогонадизм, вызванный анаболическими андрогенными стероидами, обратимое состояние у мужчин? Систематический обзор», на PubMed.\n\nГод без стероидов\nГод без стероидов дает гормональной системе длительный период восстановления. Тестостерону, настроению, либидо, естественной силе и здоровью сердца потребовалось достаточно времени для восстановления.\n\nДолгосрочная картина\nЕсли симптомы низкого уровня тестостерона все еще присутствуют в течение года, следующим шагом будет специализированная гормональная оценка. Отказ от стероидов защищает уже достигнутое выздоровление.';

  @override
  String get steroidsReferenceDay730 =>
      'Два года без анаболических стероидов\n\nИсточник: «Гипогонадизм, вызванный анаболическими андрогенными стероидами, обратимое состояние у мужчин? Систематический обзор», на PubMed.\n\nНовая норма\nК двум годам уровень гормонов отражает естественную выработку вашего организма. У большинства мужчин, которые выздоравливают, настроение, либидо, сила и мотивация стабильны и без стероидов.\n\nДолгосрочное восстановление гормонов\nИсследования показывают, что уровень тестостерона восстанавливается в течение нескольких месяцев, тогда как гормоны, которые сигнализируют яичкам, обычно восстанавливаются в течение трех-шести месяцев. Размер яичек, выработка спермы и либидо могут улучшаться в течение месяцев или лет. Через два года стойкие симптомы низкого уровня тестостерона должны решаться специалистом, а не другим курсом стероидов.';

  @override
  String get tcaReferenceDay3 =>
      'Прекращение приема ТЦА: первые дни — отскок ацетилхолина\n\nИсточник: Dilsaver, Feinberg & Greden (1983), Американский журнал психиатрии — «Симптомы отмены антидепрессантов, купированные антихолинергическими препаратами» (отчет о случае, 3 пациента).\n\nЧем отличается отмена ТЦА\nТрициклические антидепрессанты принципиально отличаются от СИОЗС и СИОЗСН по механизму действия. Помимо блокирования обратного захвата серотонина и норадреналина, ТЦА сильно подавляют холинергическую систему. После прекращения приема эта система возвращается к нормальной активности.\n\nСимптомы холинергического отскока\nВ отличие от отмены СИОЗС, прекращение приема ТЦА может вызвать временный избыток активности ацетилхолина:\n• Тошнота, рвота и диарея.\n• Чрезмерное слюноотделение и потливость.\n• Головная и мышечная боль.\n• Бессонница с яркими или тревожными снами.\n• Тревога и беспокойство.\n\nРаспространенные ТЦА и их профили\nАмитриптилин и имипрамин обладают выраженным антихолинергическим действием и поэтому могут вызывать более заметный отскок. У нортриптилина этот эффект обычно мягче. Кломипрамин также значительно влияет на серотониновую систему.';

  @override
  String get tcaReferenceDay7 =>
      'Через неделю после приема ТЦА: симптомы ацетилхолина ослабевают\n\nВосстановление ацетилхолина\nВосстановление ацетилхолина обычно достигает своего пика в течение первых нескольких дней и начинает существенно снижаться через неделю. Когда система ацетилхолина возвращается к своему естественному уровню:\n\nЧто улучшается\n• Желудочно-кишечные симптомы (тошнота, спазмы, диарея) уменьшаются.\n• Потоотделение и симптомы гриппа ослабевают.\n• Сон, хотя и нарушен, начинает стабилизироваться.\n• Чрезмерное слюноотделение проходит.\n\nВегетативная нервная система\nТЦА влияют на вегетативные функции организма — частоту сердечных сокращений, кровяное давление и пищеварение — посредством нескольких механизмов. Через неделю самые интенсивные вегетативные симптомы, включая головокружение при вставании и быстрые изменения сердечного ритма, начинают исчезать по мере перестройки нервной системы.';

  @override
  String get tcaReferenceDay14 =>
      'Через две недели после приема ТЦА: реверсирование эффектов антиацетилхолина\n\nСнижение бремени антиацетилхолина\nТЦА оказывают на организм значительное блокирующее ацетилхолин действие, которое влияет на несколько систем. По мере того, как это бремя снимается в течение первых двух недель:\n\nФизические преимущества\n• Устранение сухости во рту — функция слюнных желез возвращается в норму.\n• Устранение запоров — моторика кишечника восстанавливается естественным путем.\n• Нормализация функции мочеиспускания — проблема задержки мочи, вызванная ТЦА, проходит.\n• Прояснение зрения: глаза снова нормально приспосабливаются к свету.\n\nПреимущества мышления и памяти\nАцетилхолин необходим для памяти, внимания и обучения. Пути ацетилхолина, подавленные ТЦА, восстанавливаются:\n• Улучшение рабочей памяти\n• Увеличение скорости обработки\n• Возвращается ясность ума.\n\nМногие люди удивляются тому, к какому количеству затуманенных мыслей и проблем с памятью они приспособились, принимая ТЦА.';

  @override
  String get tcaReferenceDay30 =>
      'Через месяц после приема ТЦА: стабилизация вегетативной нервной системы\n\nВосстановление работы сердца\nВо время лечения ТЦА могут влиять на сердечный ритм через холинергические и адренергические механизмы. Клиническая литература по отмене ТЦА показывает, что острые симптомы отмены, включая вегетативные проявления, обычно легкие и проходят в течение одной-двух недель после прекращения приема. К концу первого месяца большинство людей уже миновали этот острый период:\n• Сердечный ритм возвращается к уровню, близкому к исходному.\n• Вариабельность сердечного ритма приближается к естественному уровню.\n• Регуляция артериального давления продолжает стабилизироваться.\n\nВосстановление структуры сна\nТЦА заметно подавляют фазу быстрого сна. По мере исчезновения антихолинергического эффекта:\n• Быстрый сон возвращается; вначале это может сопровождаться более яркими сновидениями.\n• Медленноволновой (глубокий) сон улучшается.\n• Общее качество и восстановительный эффект сна постепенно улучшаются.';

  @override
  String get tcaReferenceDay90 =>
      'Три месяца после ТЦА: острые риски остались позади\n\nЧто показывают доказательства\nМетаанализ 103 рандомизированных исследований (10 590 участников), проведенный в 2024 году, показал, что по сравнению с плацебо ТЦА уменьшают симптомы депрессии, но также почти в три раза повышают вероятность серьезных нежелательных явлений (отношение шансов 2,78). В самих испытаниях участников наблюдали только в течение 12 недель лечения, поэтому контролируемых долгосрочных данных о периоде после прекращения терапии нет. Далее отражено общее клиническое понимание фармакологии ТЦА, а не конкретные результаты этого исследования.\n\nВосстановление нескольких систем\nТЦА влияют на более широкий спектр химических систем мозга, чем СИОЗС или СИОЗСН:\n• Серотониновая система продолжает адаптироваться.\n• Норадреналиновая система возвращается к обычной регуляции.\n• Холинергическая система возвращается к нормальной активности.\n• Седативное влияние на гистаминовую систему исчезает.\n\nЧерез три месяца у этих систем было достаточно времени для дальнейшего восстановления, а повышенный риск нежелательных явлений, связанный с активным приемом ТЦА, уже не действует. Многие отмечают:\n• Более ясное мышление, особенно улучшение памяти и внимания.\n• Более стабильное настроение.\n• Больше энергии и мотивации.\n• Меньшую сонливость и лучшую концентрацию.';

  @override
  String get tcaReferenceDay180 =>
      'Шесть месяцев после ТЦА: восстановление сердца и мышления\n\nСигнал восстановления долгосрочных данных\nРанний период отмены после приема ТЦА обычно протекает легко и проходит в течение одной-двух недель. Через шесть месяцев после контролируемого снижения дозы ТЦА на сердцебиение, память и мышление потребовались месяцы, чтобы восстановиться.\n\nВосстановление сердечно-сосудистой системы\nК шести месяцам прямое влияние ТЦА на сердечный ритм должно быть давно решено:\n• Нормальный сердечный ритм поддерживается без воздействия лекарств.\n• Ожидается, что вариабельность сердечного ритма (показатель того, насколько хорошо ваше сердце адаптируется) значительно улучшится.\n• Головокружение при стоянии полностью исчезло.\n\nВосстановление мышления и памяти\nТЦА могут вызывать затуманивание сознания и проблемы с памятью, блокируя ацетилхолин, особенно у пожилых людей. Эти эффекты улучшаются после прекращения приема препарата. В шесть месяцев:\n• Значительно улучшена консолидация памяти.\n• Нормализована скорость обработки.\n• Планирование, рабочая память и способность переключаться между задачами или идеями значительно восстанавливаются.';

  @override
  String get tcaReferenceDay365 =>
      'Год после ТЦА: восстановление достигнуто\n\nОдин год: длительное восстановление нескольких систем\nОбзор синдромов отмены антидепрессантов, охватывающий ТЦА, ИМАО, СИОЗС и другие препараты, показал, что симптомы отмены обычно начинаются в течение нескольких дней после прекращения приема и без специального лечения проходят за несколько дней или недель. Исследований, специально измеряющих системы, затронутые ТЦА, ровно через год после отмены, нет. Однако год после завершения постепенного снижения дозы намного превышает обычную продолжительность симптомов отмены, поэтому серотониновая, норадреналиновая, холинергическая и гистаминовая системы имели достаточно времени для нормализации.\n\nЗначение восстановления после ТЦА\nТЦА воздействуют на большее число рецепторных систем, чем многие более новые антидепрессанты. После успешного прекращения приема продолжается восстановление нескольких функций:\n• Уменьшаются нарушения памяти и мышления, связанные с антихолинергическим действием ТЦА.\n• Исчезает прямое влияние препарата на сердечный ритм.\n• Химическая регуляция мозга возвращается к естественному режиму.\n\nГод после прекращения приема ТЦА — значимая веха как для завершения процесса отмены, так и для поддержания благополучия без препарата.';
}
